COLLDATA("qenc","ur",[[496,"§قید خانہ\nدیکھیے: سجن","",{}],[497,"§قیوم(اسم باری تعالی)","",{}],[498,"§کاروبار\nدیکھیے: تجارت","",{}],[499,"§کافر\nکافر لفظ کفر سےبنا ہے، جس کےمعنی ہیں: ڈھانکنا،چھپانا، انکار کرنا۔اسی طرح تاریک رات سمندر، بڑی وادی، کالابادل، تاریکی، کھجور کےشگوفے کا غلاف، بڑا دریا، زرہ، وہ شخص جس نے زرہ کو اپنے کپڑوں سے چھپارکھا ہو،کاشت کار، ہتھیار بند، چھپاہوا مقیم، سب کو کافراسی معنی میں کہتے ہیں کہ اس میں چھپنےاورپوشیدگی کا عمل پایاجاتاہے۔چوں کہ کافر یا بےدین اپنی فطرت کو چھپاتا اوراللہ تعالی کا انکار کرتا ہے، اس لیے اسے کافر کہا جاتا ہے۔\nجو لوگ کافر کے معنی نہیں جانتے، وہ اس لفظ کو ایک گالی سمجھتے ہیں۔اس کی حقیقت جاننے کے لیے ضروری ہے کہ ہم اس کے صحیح مطلب کو جانیں۔\nابوہریرہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَا مِنْ مَوْلُودٍ إِلا يُولَدُ عَلَی الْفِطْرَةِ فَأَبَوَاهُ يُهَوِّدَانِهِ وَيُنَصِّرَانِهِ أَوْ يُمَجِّسَانِهِ». (صحیح البخاری: ۱۳۵۹، و صحیح مسلم: ۲۶۵۸/۲۲) \"ہر شخص اپنی فطرت پر پیدا کیا جاتا ہے، اس کے ماں باپ اس کو عیسائی بنا لیتے ہیں یا یہودی بنا لیتے ہیں، یا مجوسی(مشرک) بنا لیتے ہیں\"۔\nیہاں فطرت سے مراد توحید ہے، جس کی طرف اسلام بلاتا ہے۔بلکہ اسلام ہی فطرت ہے جس پر ہر ایک بچہ پیدا ہوتا ہے۔ اس کے ماں باپ جس دین پر ہوتے ہیں، اس کو اسی پر ڈال دیتے ہیں۔ اسی لیے عیسائی کا بچہ عیسائی، یہودی کا بچہ یہودی بن جاتاہے۔اس لیے کہ اس کو اپنی فطرت پر پلنے بڑھنے کا موقع نہیں مل پاتا۔ اس کی فطرت پر پردہ پڑ جاتا ہے۔\nکفر ایک بلاہے،جس کی طرف قرآن مجید نے مختلف درجات میں اشارہ کیا ہے۔ اسلام مخالفین کے لیے دُنیوی زندگی شان وشوکت بن گئی۔ قرآن میں ہے:﴿زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابࣲ‏﴾ [البقرة: ۲۱۲] \"جن لوگوں نے کفر کیا، ان کے لیے دُنیوی زندگی شان و شوکت والی بنا دی گئی۔ اور وہ ایمان لانے والوں پر ہنستے ہیں، جب کہ وہ لوگ اللہ سے ڈرتے ہیں۔ قیامت کے دن وہ ان سے اوپر ہوں گے اللہ جسے چاہے بے حساب رزق دے\"۔\n§انکارنبوت ورسالت کے اسباب:\nقرآن مجیدنے کفر کی مختلف وجوہ کو واضح طور پر بیان کیا ہے:\n۱- آبا واجداد کی تقلیداوران کے دین کے بارے میں تعصب: گزشتہ قوموں نےاپنےانبیاورسل کی مخالفت محض آباء واجداد کی تقلید میں کی اورخود قریش اور دوسرے قبائل کے لوگوں کی نبی اکرم صلی اللہ علیہ وسلم سےمخالفت کابڑا سبب یہی آباءواجداد کی تقلید تھی اور اس بات کا اظہارانھوں نے کھل کر کیا: ﴿وَإِذَا قِيلَ لَهُمُ ٱتَّبِعُواْ مَآ أَنزَلَ ٱللَّهُ قَالُواْ بَلۡ نَتَّبِعُ مَآ أَلۡفَيۡنَا عَلَيۡهِ ءَابَآءَنَآۚ أَوَلَوۡ كَانَ ءَابَآؤُهُمۡ لَا يَعۡقِلُونَ شَيۡـࣰٔ ا وَلَا يَهۡتَدُونَ﴾ [البقرة: ۱۷۰] \"اور ان سے جب کبھی کہا جاتا ہے کہ اللہ تعالیٰ کی اتاری ہوئی کتاب کی تابعداری کرو تو جواب دیتے ہیں ہم اس طریقے کی پیروی کریں گے جس پر ہم نے اپنے باپ دادوں کو پایا، گو ان کے باپ دادے بےعقل اور گم کردہ راہ ہوں \"۔\n۲- حسد: انبیاورسل کی دعوت حق کو نہ ماننے کاایک بڑا سبب حسد ہے۔ پرانی قوموں کے مطالعے سے معلوم ہوتا ہےکہ انھوں نے اپنے نبیوں کا انکار حسد کی وجہ سے کیا تھا۔ یہ بات بھی واضح ہے کہ اہل کتاب(یہودونصاریٰ)نے آخری نبی اکرم صلی اللہ علیہ وسلم کا انکار بھی محض حسد کی وجہ سے کیا۔ نہیں تو وہ بہت اچھی طرح جانتےاورپہچانتے تھے کہ ان کی کتابوں میں جس آخری نبی کے آنے کی خوش خبری دی گئی ہے، اس سےمرادمحمد صلی اللہ علیہ وسلم ہیں، لیکن مشکل یہ آپڑی کہ ان کی توقع کے خلاف بنی اسرائیل کے بجائے اسماعیل علیہ السلام کی نسل سے نبی آخرالزماں کی بعثت ہوئی۔اس لیے حسد میں آپ کو نبی تسلیم کرنے سےانکارکردیا۔ اللہ تعالیٰ کا ارشادہے: ﴿وَدَّ كَثِيرࣱ مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ لَوۡ يَرُدُّونَكُم مِّنۢ بَعۡدِ إِيمَٰنِكُمۡ كُفَّارًا حَسَدࣰ ا مِّنۡ عِندِ أَنفُسِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡحَقُّۖ فَٱعۡفُواْ وَٱصۡفَحُواْ حَتَّىٰ يَأۡتِيَ ٱللَّهُ بِأَمۡرِهِۦٓۗ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏﴾ [البقرة: ۱۰۹] \"ان اہل کتاب کےاکثر لوگ باوجود حق واضح ہو جانے کے محض حسد و بغض کی بنا پر تمھیں بھی ایمان سے ہٹا دینا چاہتے ہیں، تم بھی معاف کرو اور چھوڑو یہاں تک کہ اللہ تعالیٰ اپنا حکم لائے۔ یقیناً اللہ تعالیٰ ہرچیز پر قدرت رکھتا ہے\"۔\n۳- نفسانی خواہشوں کی پیروی:انسان قدیم زمانے سےاپنی نفسانی خواہشوں کی وجہ سے حق کا انکارکرتا رہا ہے۔ ارشادباری تعالیٰ ہے: ﴿يَٰدَاوُۥدُ إِنَّا جَعَلۡنَٰكَ خَلِيفَةࣰ فِي ٱلۡأَرۡضِ فَٱحۡكُم بَيۡنَ ٱلنَّاسِ بِٱلۡحَقِّ وَلَا تَتَّبِعِ ٱلۡهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمۡ عَذَابࣱ شَدِيدُۢ بِمَا نَسُواْ يَوۡمَ ٱلۡحِسَابِ﴾ [ص: ۲۶] \"اے داود! ہم نے تمہیں زمین میں خلیفہ بنا دیا تم لوگوں کے درمیان حق کے ساتھ فیصلے کرو اور اپنی نفسانی خواہش کی پیروی نہ کرو ورنہ وہ تمھیں اللہ کی راہ سے بھٹکا دے گی، یقیناً جو لوگ اللہ کی راہ سے بھٹک جاتے ہیں ان کے لئے سخت عذاب ہے اس لئے انھوں نے حساب کے دن کو بھلا دیا ہے\"۔\n۴-دنیوی مصالح کے زوال کاخوف: دنیوی مصالح میں سیادت وقیادت، جاہ ومنصب اورمال ودولت ہے،جن کے زوال کے خوف سے آدمی دعوت حق نہیں قبول کرتا۔دنیوی فتنوں میں مال ودولت اور آل واولاد بڑےفتنوں میں سے ہیں، اس کے بارے میں ارشادباری تعالیٰ ہے :﴿إِنَّمَآ أَمۡوَٰلُكُمۡ وَأَوۡلَٰدُكُمۡ فِتۡنَةࣱۚ وَٱللَّهُ عِندَهُۥٓ أَجۡرٌ عَظِيمࣱ‏﴾ [التغابن: ۱۵] \"تمھارے مال اور اولاد تو سراسر تمھاری آزمایش ہیں اور بہت بڑا اجر اللہ کے پاس ہے \"۔\nنبی اکرم صلی اللہ علیہ وسلم نے بھی مال ودولت اورجاہ ومنصب کے لالچ کو انسان کےدین کے حق میں مہلک ترین بتایا،سنن ترمذی میں کعب بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:«مَا ذِئْبَانِ جَائِعَانِ أُرْسِلاَ فِي غَنَمٍ بِأَفْسَدَ لَهَا مِنْ حِرْصِ الْمَرْءِ عَلَی الْمَالِ وَالشَّرَفِ لِدِينِهِ» (سنن الترمذی : ۲۳۷۷، سنن ابی داود : ۲۷۷۲، مسند احمد: ۳/۴۵۶، ۴۶۰) \"دوبھوکے بھیڑیئے جنھیں بکریوں کے ریوڑ میں چھوڑدیاجائے اتنا نقصان نہیں پہنچائیں گے جتنانقصان آدمی کے مال وجاہ کی حرص اس کے دین کوپہنچاتی ہے\"۔\nاس حدیث سے معلوم ہواکہ مال وجاہ کی محبت اورحرص جس کے اندرآگئی وہ ہلاکتوں سے اپنا دامن نہیں بچاسکتا۔بدقسمتی سے آج امت اسی فتنہ سے دوچارہے اوراس کی تباہی کا یہ عالم ہے کہ جس انتشار اورشدیداختلافات کا یہ امت اوراس کی دینی جماعتیں شکارہیں ان کے اسباب میں بھی مال وجاہ کی محبت سرفہرست ہے۔\nنبی اکرم صلی اللہ علیہ وسلم کی نبوت نہ ماننے کاایک سبب سرداروں کوان کی سرداری اورقیادت وسیادت چھن جانے کا خوف بھی تھا۔قریش کے سرداروں کویہ خوف لاحق تھا کہ قیادت وسیادت ان کے ہاتھ سے نکل جائے گی۔اس لیے نبی اکرم صلی اللہ علیہ وسلم اورمسلمانوں اوردین اسلام کی جم کرمخالفت کی حتی کہ مسلمانوں کو ایک بار عرب سرزمین چھوڑکر حبشہ ہجرت کرنی پڑی اور دوبارہ سارے مسلمان مکہ چھوڑکر مدینہ ہجرت کرگئے۔اس کے بعد بھی آٹھ سال سے مسلسل ان کے خلاف دشمنی کااظہارہوتارہااور اس کے نتیجےمیں جنگیں ہوئیں۔جان ومال کا نقصان ہوا۔ فتح مکہ کے بعد جب قریش کے سارے لوگ پسپاہوگئے اور پھراللہ تعالیٰ نے سب کو اسلام کی دولت دی تو یہ سلسلہ تھما۔\nقرآن مجیدمیں ہے :﴿فَقَالَ ٱلۡمَلَؤُاْ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦ مَا هَٰذَآ إِلَّا بَشَرࣱ مِّثۡلُكُمۡ يُرِيدُ أَن يَتَفَضَّلَ عَلَيۡكُمۡ وَلَوۡ شَآءَ ٱللَّهُ لَأَنزَلَ مَلَٰٓئِكَةࣰ مَّا سَمِعۡنَا بِهَٰذَا فِيٓ ءَابَآئِنَا ٱلۡأَوَّلِينَ﴾ [المؤمنون: ۲۴] \"اس پر اس کی قوم کے سردار جنھوں نے کفر کیا، کہنے لگے:یہ بس تمھارے جیسا ایک شخص ہے، چاہتا ہے کہ تم پر بڑائی حاصل کرے اور اگر اللہ چاہتا تو فرشتے بھیجتا، ہم نے تو اپنے بزرگوں سے یہ بات کبھی نہیں سنی\"۔\nاس لیے جب اللہ تعالیٰ نے انبیاکو ان کی اصلاح کے لیے اور ان کی فطرت کی پہچان کرانے کے لیے بھیجا تو سب سے پہلے انکار کرنے والے یہی رہنما اور سردار ہوتے تھے۔ قریش کے سردار بھی لوگوں کو قرآن سننے سے روکتے تھے۔ کہ کہیں اس سے متاثر ہوکر یہ لوگ اپنا رہنما نہ پاجائیں اور ہماری سرداری خطرے میں نہ پڑ جائے:﴿وَقَالَ ٱلَّذِينَ كَفَرُواْ لَا تَسۡمَعُواْ لِهَٰذَا ٱلۡقُرۡءَانِ وَٱلۡغَوۡاْ فِيهِ لَعَلَّكُمۡ تَغۡلِبُونَ﴾ [حم السجدة: ۲۶] \"جن لوگوں نے کفر کیا، انھوں نے کہا:اس قرآن کو سنو ہی مت اور اس کے درمیان میں شوروغل مچاؤ، تاکہ تم غالب رہو\"۔\n۵- تکبراورگھمنڈ: اپنے کو برتر جاننے، اپنے اوپراترانےاوردوسروں کوحقیرجاننےاورذلیل کرنے کو تکبراور گھمنڈکہتے ہیں۔معاشرے میں کسی بھی طرح کے باحیثیت لوگوں میں عام طور پر یہ مرض پایاجاتا ہے۔اسی مہلک مرض نے ابلیس کو ذلیل وخوار کیا، جب اس نے اللہ تعالیٰ کے آدم علیہ السلام کو سجدکرنے سے حکم سے انکار کردیااور اپنی فضیلت کی دلیل یہ دی کہ وہ آگ سے پیدا کیا گیاہے اور آدم مٹی سے اور اس کی نظر زیادہ بہتر اورافضل چیز تھی۔ اسی طرح سے مٹی کے بنے انسان بعض جھوٹی دلیلوں کاسہارا لے کر اپنے کو افضل وبرتر شمارکرتے اور دوسروں کو حقیرسمجھتے ہیں۔ یہ مرض دعوت حق قبول کرنے میں رکاوٹ کا ایک بڑا سبب ہے۔ ارشادباری تعالیٰ ہے : ﴿وَإِذۡ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ أَبَىٰ وَٱسۡتَكۡبَرَ وَكَانَ مِنَ ٱلۡكَٰفِرِينَ﴾ [البقرة: ۳۴] \"اور جب ہم نے فرشتوں سے کہا کہ آدم کو سجدہ کرو تو ابلیس کے سوا سب نے سجدہ کیا۔ اس نے انکار کیا اور تکبر کیا اور وہ کافروں میں ہو گیا\"۔\n۶- دین اسلام سے ناواقفیت : اسلام سے ناواقفیت بھی اللہ ورسول پرایمان نہ لانےاورآخری نبی پراتاری گئی کتاب کے انکارکابڑا سبب ہے۔اگرآدمی سنجیدگی سے قرآن وحدیث اورسیرت نبوی کا مطالعہ کرے اورہرطرح کے تعصب اوربندش کوبالائے طاق رکھ دے تو یہ بات یقینی طورپر کہی جاسکتی ہے کہ اسلام کےقبول واعتراف کے علاوہ اس کے سامنے کوئی اورچارہ نہیں ہے۔اس لیے عہدنبوی میں کفارومشرکین لوگوں کو قرآن نہ سننے دینے کی ترکیبیں نکالتے تھےاوربعض تو اسلام قبول کرنے سےپہلے اپنے کانوں میں روئی تک ٹھونس لیتے تھے کہ کہیں کلام اللہ کی تاثیرسے وہ اپناآبائی دین چھوڑکر حلقہ بگوش اسلام ہوجائے۔ اللہ تعالیٰ نے بھی کفارومشرکین کی اس دین سے جہالت کا ذکرکیاہےاوران کوقرآن سننے کاموقع فراہم کرنے کی ہدایت کی ہے۔ ارشادباری تعالیٰ ہے: ﴿وَإِنۡ أَحَدࣱ مِّنَ ٱلۡمُشۡرِكِينَ ٱسۡتَجَارَكَ فَأَجِرۡهُ حَتَّىٰ يَسۡمَعَ كَلَٰمَ ٱللَّهِ ثُمَّ أَبۡلِغۡهُ مَأۡمَنَهُۥۚ ذَٰلِكَ بِأَنَّهُمۡ قَوۡمࣱ لَّا يَعۡلَمُونَ﴾ [التوبة: ۶] \"اگر مشرکوں میں سے کوئی تجھ سے پناہ طلب کرے تو اسے پناہ دے دو یہاں تک کہ وہ کلام اللہ سن لے پھر اسے اپنی جائے امن تک پہنچا دے یہ اس لئے کہ یہ لوگ بےعلم ہیں\"۔\nیہ ہیں وہ اہم اسباب، جن کی موجودگی انسان ابلیس اور اس کے چیلوں کی چالوں کا شکاراپنے رب اور خالق ومالک کے پوجنے کے بجائے اس کے ساتھ نافرمانی کا رویہ اپناتاہے۔ورنہ قرآن وحدیث سیرت نبوی سے واقفیت کے بعد حق کو اگر اللہ توفیق دے تو قبول کرنا بڑا آسان ہے۔\nقرآن کریم میں وارد کفر اور کافر کے الفاظ بہت ہی معنیٰ خیز ہیں۔قرآن کریم میں ان لفظوں کا استعمال مومن اور مسلمانوں کے مقابل متضاد لفظ کی شکل میں ہوا ہے۔ کیوں کہ مومن یا مسلمان سے مراد وہ شخص ہے، جو اللہ کے حکم کی پیروی کرنے والا ہوتاہے۔ اور کافر یا بد دین سے مراد وہ شخص ہے جو اللہ اور اس کے رسول کے حکم کی پیروی کرنے سے انکار کردے۔ اس لیے اگر دیکھا جائے تو سب سے پہلا بددین ابلیس تھا، جسے اللہ نے آدم کو سجدہ کرنے کا حکم دیا، لیکن اس نے سجدہ کرنے سے انکار کردیا۔ اور اسلام مخالف ہوگیا۔ (البقرہ:۳۴)\nپھر اللہ تعالیٰ ہر زمانے میں لوگوں کی ہدایت کے لیے نبی ورسول بھیجتارہا اور ان نبیوں اوررسولوں کاانکار کرنے والوں کو کافر کہا جانے لگا۔ جیسے نوح علیہ السلام نےجب اپنی قوم کو اللہ کی طرف بلایا تو انھوں نے ان کی بات ماننے سے انکار کردیا، جس کی وجہ سے وہ طوفان میں گھر کر تباہ اور برباد ہوگئے۔ اس وقت نوح علیہ السلام نے جودعا کی وہ قرآن میں اس طرح بیان ہوئی ہے:﴿وَقَالَ نُوحࣱ رَّبِّ لَا تَذَرۡ عَلَى ٱلۡأَرۡضِ مِنَ ٱلۡكَٰفِرِينَ دَيَّارًا إِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرࣰ ا كَفَّارࣰ ا﴾ [نوح: ۲۶-۲۷] \"نوح نے کہا، اے میرے رب! تو زمین پر ان کافروں میں سے کسی کو نہ چھوڑ۔ اگر تو انھیں چھوڑ دےگا تو وہ تیرے بندوں کو گمراہ کر دیں گے اور وہ برے کام کرنے والے اور بڑے کافروں کو ہی پیدا کریں گے\"۔\nاسی طرح صالح علیہ السلام کی قوم ثمود نے ان کی تعلیم اور نصیحت سے انکار کیا اور اس اونٹنی کو، جسے اللہ نے ایک نشانی بنا کر بھیجا تھا،کوچ کاٹ کر مار ڈالا، تو انجام یہ ہوا :﴿أَلَآ إِنَّ ثَمُودَاْ كَفَرُواْ رَبَّهُمۡۗ أَلَا بُعۡدࣰ ا لِّثَمُودَ﴾ [ہود: ۶۸] \"سن لو! ثمود نے اپنے رب سے کفر کیا، تو وہ اللہ سے دور کر دیے گئے\"۔\nاسی طرح عیسیٰ علیہ السلام نے جب اپنی دعوت بنی اسرائیل میں دینی شروع کی تو آپ نے محسوس کیا کہ کچھ لوگ آپ کی تعلیم اور نصیحت سے انکار کررہے ہیں۔قرآن میں ہے:﴿فَلَمَّآ أَحَسَّ عِيسَىٰ مِنۡهُمُ ٱلۡكُفۡرَ قَالَ مَنۡ أَنصَارِيٓ إِلَى ٱللَّهِۖ قَالَ ٱلۡحَوَارِيُّونَ نَحۡنُ أَنصَارُ ٱللَّهِ ءَامَنَّا بِٱللَّهِ وَٱشۡهَدۡ بِأَنَّا مُسۡلِمُونَ﴾ [آل عمران: ۵۲] \"پھر جب عیسی نے ان کے کفر کو پہچان لیا تو کہا: کون ہے جو اللہ کی طرف بڑھنے میں میری مدد کرے۔ تو حواریوں (عیسی کے شاگردوں) نے کہا: ہم اللہ کے مددگار ہیں۔ ہم اللہ پر ایمان لائے اور گواہ رہو کہ ہم مسلمان ہیں\"۔\nیعنی بنی اسرائیل کے وہ لوگ، جو عیسی علیہ السلام پر ایمان نہیں لائے، کافر(بد دین، ملحدیامنکرین) کہلائے۔\nاب کافر ان لوگوں کو کہا جاتاہے جو نبی محمد صلی اللہ علیہ وسلم پر ایمان نہیں لاتے۔ کیوں کہ آپ پوری دنیا کے لیے نبی بنا کر بھیجے گئے ہیں۔آپ کے بعد اب قیامت تک کوئی اور نبی نہیں آئے گا، بلکہ عیسی علیہ السلام قیامت سے قبل آسمان سے واپس آئیں گے تو نبی محمد صلی اللہ علیہ وسلم کے دین پر ہی چلیں گے۔\nايک صحيح حديث میں جابر رضی اللہ عنہ سے مروی ہےنبی اکرم صلی اللہ علیہ وسلم نے فرمايا: «لَوْ کَانَ مُوسَی حَيًّا مَا وَسِعَهُ إِلا اتِّبَاعِي». (شعب الايمان: ۱۷۵/۳۴۸) وفي رواية لأحمد: «لَوْ کَانَ مُوسَی حَيًّا بَيْنَ أَظْهُرِکُمْ مَا حَلَّ لَهُ إِلاَّ أَنْ يَتَّبِعَنِی». (مسند احمد: ۱۵۰۰۶) \"اگر موسیٰ علیہ السلام اب زندہ ہوتے توميری ہی پیروی کرتے\"۔\n§کافر کے حقوق:\nکافریا تو مسلمانوں کے ملک میں ہوگا یا مسلمان اس ملک میں ہوں گے، جہاں غیر مسلموں کی اکثریت ہوگی۔دونوں حالتوں میں کا فر کی جان، مال اور اس کی عزت وآبرو کی حفاظت کرنا مسلمانوں پر فرض ہے۔ایک صحیح حدیث میں آتا ہے:جس نے کسی ذمی(غیر مسلم جو مسلم ملک میں رہ رہا ہو) کو قتل کیا، جنت اس کے لیے حرام ہے۔بلکہ قرآن مجیدمیں صاف صاف بتا دیا گیا ہے:﴿لَّا يَنۡهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمۡ يُقَٰتِلُوكُمۡ فِي ٱلدِّينِ وَلَمۡ يُخۡرِجُوكُم مِّن دِيَٰرِكُمۡ أَن تَبَرُّوهُمۡ وَتُقۡسِطُوٓاْ إِلَيۡهِمۡۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ﴾ [الممتحنة: ۸] \"اللہ تم کو اس سے نہیں روکتا کہ تم ان لوگوں کے ساتھ اچھا برتاؤ کرو اور ان کے ساتھ انصاف کرو جنھوں نے تم سے مذہب کے معاملے میں جنگ نہیں کی اور نہ تمھیں تمھارے اپنے گھروں سے نکالا۔بلاشبہ اللہ انصاف کرنے والوں کو پسند کرتاہے\"۔اس لیے کہ مسلمان نہ تو غیر مسلم کے دشمن ہیں اور نہ سارے غیر مسلم مسلمانوں کے دشمن ہیں۔ مسلمانوں کا فرض ہے کہ وہ جس ملک میں رہیں اس کی ترقی کی طرف پورا دھیان دیں اور بڑھ چڑھ کر وہاں کی ترقی میں حصہ لیں اور سب سے بڑی بات یہ ہےکہ مسلمان سچا مذہب اسلام کا پیغام پہنچانے والے ہیں، اس لیے ان کو چاہیےکہ اپنےحسن وسلوک اوراچھے برتاؤ سے اور اپنی زبان سے وہ اسلام کا صحیح نمونہ پیش کریں۔ قرآن مجیدمیں ہے: ﴿كُنتُمۡ خَيۡرَ أُمَّةٍ أُخۡرِجَتۡ لِلنَّاسِ تَأۡمُرُونَ بِٱلۡمَعۡرُوفِ وَتَنۡهَوۡنَ عَنِ ٱلۡمُنكَرِ وَتُؤۡمِنُونَ بِٱللَّهِۗ﴾ [آل عمران: ۱۱۰] \"تم ایک بہترین امت ہو، تم کو لوگوں کے سامنے لایا گیاہے۔ تم بھلائی کا حکم دیتے ہو اور برائی سے روکتے ہو اور اللہ پر ایمان لاتے ہو\"۔","",{}],[500,"§کافور\nکافورکواردو میں کپوربھی کہتے ہیں، یہ ایک نہایت خوشبودار تلخ ذائقے کا سفیدمادہ جوبطوردوا استعمال ہوتاہےاور کھلارہنے سےاُڑجاتاہے۔اسی لیےاردو محاورے میں کافور ہونا یا ہوجاناکا مطلب غائب ہوجاناچل دیناہے۔کپورکو کسی چیزمیں ملا دیا جائے تو اس کی خوشبو میں اضافہ ہوجاتا ہے۔ جنت میں نیک لوگوں کو جو پینے کی چیز ملے گی، اس میں کافور ملا ہوگا۔ قرآن مجیدمیں ہے: ﴿إِنَّ ٱلۡأَبۡرَارَ يَشۡرَبُونَ مِن كَأۡسࣲ كَانَ مِزَاجُهَا كَافُورًا عَيۡنࣰ ا يَشۡرَبُ بِهَا عِبَادُ ٱللَّهِ يُفَجِّرُونَهَا تَفۡجِيرࣰ ا﴾ [الدهر: ۵-۶] \"بےشک متقی لوگ اس جام سے پیئں گے، جس میں کافور ملا ہوگا۔ اس چشمہ کا کیا کہنا! جس سے اللہ کے بندے پئیں گے، اس طرح کہ اسے بہا کر جہاں چاہیں گے لے جائیں گے\"۔\nیہ کافور دنیا کے کافور سے مختلف ہوگا۔بے حد خوشبودار، مزیدار، ٹھنڈی، آرام دہ اور سکون والی چیز ہوگی۔ اسے پینے سے روح آسودہ ہوگی۔ اس کی نہریں بہتی ہوں گی۔ ان نہروں کو جہاں چاہیں گے بہا کر لےجائیں گے۔ حقیقت میں جنت کی چیزوں کا ہم ٹھیک ٹھیک اندازہ نہیں لگاسکتے۔ وہ ہمارے تصورات کےحدود سے بھی آگے کی چیزیں ہیں۔ اللہ تعالیٰ تو دنیا کی چیزوں کی مثال صرف قرآن کے تاثرات کو ظاہر کرنے کے لیے اور ہمیں سمجھانے کے لیے دیتاہے۔","",{}],[501,"§کبیر\nدیکھیے: اسماےحسنی","",{}],[502,"§کبیرہ (کبائر)\nکبائرکبیرہ کی جمع ہے۔یعنی بڑےگناہ۔گناہ تو سب گناہ ہی ہوتے ہیں،لیکن ان میں بعض گناہ کبیرہ ہوتے ہیں۔\n§گناہ کبیرہ کی تعریف:\nہر وہ گناہ جس کے لیے دنیا یا آخرت میں عذاب متعین ہو یااس کی دھمکی ہویااللہ ورسول نے اس کام کےکرنے والے پر لعنت کی ہویا اس کے ایمان کو خارج کردیا ہو، ان سارے گناہوں کو گناہ کبیرہ کہا جاتاہے۔گناہ کبیرہ بہت زیادہ ہیں۔صرف ایک صحیح حدیث میں سات مہلک اور خطرناک گناہ کبیرہ کا ذکر آیا ہے۔ابوہریرہ رضی اللہ عنہ سےروایت ہےکہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ قَالُوا: يَارَسُولَ اللَّهِ! وَمَا هُنَّ؟ قَالَ: الشِّرْکُ بِاللَّهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللَّهُ إِلا بِالْحَقِّ، وَأَکْلُ الرِّبَا، وَأَکْلُ مَالِ الْيَتِيمِ، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْمُؤْمِنَاتِ الْغَافِلاتِ». (صحیح البخاری: ۲۷۶۶، وصحیح مسلم: ۸۸/۱۴۴) \" ایمان کو برباد کرنے والے سات کاموں سے بچو! لوگوں نے پوچھا: وہ کیا ہیں؟ اللہ کےرسول! آپ نے فرمایا: ا-اللہ کے ساتھ کسی کو شریک کرنا، ۲-جادو، ۳- کسی کو ناحق قتل کرنا،جس کو اللہ تعالیٰ نے حرام کیاہے،۴-سود خوری، ۵-یتیم کا مال کھانا، ۶-میدان جنگ سے پیٹھ پھیر کر بھاگنا، ۷-بھولی بھالی مومن پاک دامن عورتوں پر الزام لگانا\"۔\nانھی گناہ کبیرہ میں سےماں باپ کولعنت ملامت کرناہے۔عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہےکہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «إِنَّ مِنْ أَکْبَرِ الْکَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ، قِيلَ: يَا رَسُولَ اللَّهِ! وَکَيْفَ يَلْعَنُ الرَّجُلُ وَالِدَيْهِ؟ قَالَ: يَسُبُّ الرَّجُلُ أَبَا الرَّجُلِ فَيَسُبُّ أَبَاهُ وَيَسُبُّ أُمَّهُ». (صحیح البخاری: ۵۹۷۳، صحیح مسلم: ۸۹/۱۴۵) \"بہت بڑے گناہوں میں سے یہ بھی ہے کہ کوئی شخص اپنے ماں باپ کو لعنت ملامت کرے۔ لوگوں نے پوچھا:اے اللہ کے رسول! بھلا کوئی اپنے والدین کو لعنت ملامت کرتا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:کیوں نہیں! جب کوئی شخص کسی دوسرے کے والد کو لعنت کرےگا تو وہ بھی اس کے والد کو لعنت کرےگا،اسی طرح جب کوئی کسی کی ماں کو لعن طعن کرےگا تو وہ بھی اس کی ماں کو لعن طعن کرےگا\"۔\nانھی کبیرہ گناہوں میں سےبیوی کاشوہرکے بسترسے الگ رہنا بھی ہے: ابوہریرہ رضی اللہ عنہ سے روایت ہے نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «إِذَا دَعَا الرَّجُلُ امْرَأَتَهُ إِلَی فِرَاشِهِ فَأَبَتْ أَنْ تَجِيءَ لَعَنَتْهَا الْمَلائِکَةُ حَتَّی تُصْبِحَ». (صحیح البخاری: ۵۱۹۳، وصحیح مسلم: ۱۴۳۶/۱۲۰) \"اگر شوہر اپنی بیوی کو اپنی خواہشیں پوری کرنے کے لیےبلائے مگر وہ اس کے لیے راضی نہ ہو اور اس کا شوہر ناراض ہو کر سوجائے تو ایسی بیوی پر فرشتے صبح تک لعنت بھیجتے رہتے ہیں\"۔\nگناہ کبیرہ میں سے ایک یہ بھی ہے کہ کوئی مسلمان اپنے بھائی کے خلاف اسلحہ لہرائے۔ابوہریرہ رضی اللہ عنہ سے روایت ہےکہ ابوالقاسم صلی اللہ علیہ وسلم نے فرمایا: «مَنْ أَشَارَ إِلَی أَخِيهِ بِحَدِيدَةٍ فَإِنَّ الْمَلائِکَةَ تَلْعَنُهُ حَتَّی يَدَعَهُ وَإِنْ کَانَ أَخَاهُ لأَبِيهِ وَأُمِّهِ». (صحیح مسلم: ۱۲۵/۲۶۱۶) \"کوئی شخص اپنے بھائی کی طرف ہتھیار سے نشانہ بنائے اور ڈرائے۔ اس پر فرشتے لعنت بھیجتے ہیں خواہ وہ اس کا سگا بھائی ہی کیوں نہ ہو\"۔\nسوچیے! اگر صرف ہتھیار سے ڈرانا ہی گناہ کبیرہ ہے تو اس کو قتل کرنا کتنا بڑا گناہ کبیرہ ہوگا?۔\nانھی گناہوں میں سےعوامی گھاٹ اور مقامات پرپیشاب پاخانہ کرناہے،جس کی وجہ سے لوگ ایسا کرنےوالوں کو برابھلاکہتے ہیں۔نبی اکرم صلی اللہ علیہ وسلم نے فرمایاہے: «اتَّقُوا اللَّعَّانَيْنِ»، قَالُوا: وَمَا اللَّعَّانَانِ يَا رَسُولَ اللَّهِ قَالَ: «الَّذِي يَتَخَلَّی فِي طَرِيقِ النَّاسِ أَوْ فِي ظِلِّهِمْ». (صحیح مسلم: ۶۸/۲۶۹ بروایت ابوہریرہ رضی اللہ عنہ ) \"لوگو!دو لعنتوں سے بچو! لوگوں نے پوچھا: وہ کیا ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: لوگوں کے چلنے کے راستے میں اور ان کے سایہ دار درخت کے نیچے جہاں لوگ آرام کرتے ہوں پاخانہ، پیشاب کرنا\"۔\nجن کاموں پر نبی اکرم صلی اللہ علیہ وسلم نےلعنت بھیجی ہے وہ سب گناہ کبیرہ ہیں۔ اس لیے ایک مسلمان پر لازم ہے کہ وہ ان کبیرہ گناہوں کا علم رکھے اور ان سے بچنے کی کوشش کرتارہے۔\nگناہ کبیرہ کی فہرست تو بہت لمبی ہے، لیکن ان میں سے کچھ یہ بھی ہیں:\nجھوٹی گواہی دینا، جوا کھیلنا، چوری کرنا، ڈاکا زنی، ظلم وزیادتی، بیوی سے اگلی شرم گاہ کے بجائے پیچھے مقعدمیں جماع کرنا، رشوت لینا، علم چھپانا، احسان جتانا، پڑوسی کو تکلیف پہنچانا وغیرہ۔\nمگریہ بات بھی ذہن نشیں کرلینی چاہیےکہ کسی شخص پر جو ان میں سے کسی گناہ کبیرہ کو کر گزرا ہو لعنت نہیں کرنی چاہیے،کیوں کہ ہوسکتاہے کہ اس نے توبہ کرلی ہویا اس نے کچھ ایسے عمل کیے ہوں جن کی وجہ سے اس کے بہت سارےگناہ مٹادیے گیے ہوں۔ اسی طرح اس بات کو بھی دھیان میں رکھنا چاہیے کہ سارے گناہ کبیرہ ایک ہی قبیل کے نہیں ہیں، بلکہ ان میں سے کچھ ایسے ہیں جن کے ارتکاب سےہمیشہ جہنم کی سزا بھگتنی پڑے گی جیسے! اللہ کے ساتھ کسی کو شریک ٹھہرانا۔ایسے شخص کو اللہ کبھی معاف نہیں کرےگا جو اس کی ربوبیت اور عبادت میں کسی کو شریک ٹھہراتا ہے:﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا﴾ [النساء: ۴۸] \"یقیناً اللہ تعالیٰ اپنے ساتھ شریک کئے جانے کو نہیں بخشتا اور اس کے سوا جسے چاہے بخش دیتا ہے اور جو اللہ تعالیٰ کے ساتھ شریک مقرر کرے اس نے بہت بڑا گناہ اور بہتان باندھا\"۔\nاورفرمایا: ﴿إِنَّهُۥ مَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ حَرَّمَ ٱللَّهُ عَلَيۡهِ ٱلۡجَنَّةَ وَمَأۡوَىٰهُ ٱلنَّارُۖ﴾ [المائدة: ۷۲] \"جو کوئی اللہ کے ساتھ کسی کو شریک ٹھہرائے گا اس پر اللہ نے جنت حرام کردیا اور اس کا ٹھکانا جہنم ہے\"۔\nلقمان نے اپنے بیٹے کوشرک سے بچنے کی جو نصیحت فرمائی، اس کے بارے میں قرآن مجید میں ارشادہے: ﴿وَإِذۡ قَالَ لُقۡمَٰنُ لِٱبۡنِهِۦ وَهُوَ يَعِظُهُۥ يَٰبُنَيَّ لَا تُشۡرِكۡ بِٱللَّهِۖ إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمࣱ‏﴾ [لقمان: ۱۳] \"اور جب لقمان نے اپنے بیٹے کو نصیحت کرتے ہوے کہا: اے میرے بیٹے! اللہ کے ساتھ کسی کو شریک نہ ٹھہرانا، بےشک شرک کرنا بہت بڑاظلم ہے\"۔\nظلم کی تعریف یہ ہے کہ ایک چیز کو اس کے صحیح مقام سےہٹاکر غلط جگہ پر رکھ دیا جائے، اس لیے اس سےبڑا ظلم اور کیا ہو سکتا ہے کہ جواللہ رب العزت اس کائنات کاخالق ومالک اورقادرمطلق ہے اور جس نےہمیں وجودبخشا، زندگی دی، صحت کے ساتھ توانا کیا اس کو چھوڑ کر ہم کسی اور کی عبادت کرنے لگیں۔ اس کی ربوبیت میں کسی اور کو شریک ٹھہرائیں۔اس کے اسماوصفات کومخلوق کے لیے استعمال کیا جائے۔جیسے مشرکین مکہ نے لات ومنات اورعزّی اپنے معبودوں کے نام اللہ تعالیٰ کے نام،اللہ، منان اور عزیزسے لے کررکھے۔\nگناہ کبیرہ کے متعلق عبداللہ بن عباس رضی اللہ عنہما کاکہنا ہےکہ ان کی تعداد تقریباً ستّر ہے۔ اسلامی فرائض کو وقت پر ادا نہ کرنا بھی گناہ کبیرہ میں داخل ہے۔ مثلاً نماز، زکاة، حج، رمضان المبارک کے روزے وغیرہ انھیں ترک کرنے والوں پر سخت عذاب ہے۔ مثلاً جہنمیوں سے پوچھاجائے گا:﴿مَا سَلَكَكُمۡ فِي سَقَرَ قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ وَلَمۡ نَكُ نُطۡعِمُ ٱلۡمِسۡكِينَ وَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ وَكُنَّا نُكَذِّبُ بِيَوۡمِ ٱلدِّينِ حَتَّىٰٓ أَتَىٰنَا ٱلۡيَقِينُ فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّٰفِعِينَ﴾ [المدثر: ۴۲-۴۸] \"تمھیں کیا چیز جہنم میں کھینچ لائی؟ وہ کہیں گے: ہم نمازیوں میں سے نہیں تھے اور غریبوں، مفلسوں کو کھانا نہیں کھلاتے تھے اور لایعنی باتیں بنانے والوں کے ساتھ ہم بھی باتیں بناتے تھے اور روز جزا کو جھٹلاتے تھے، حتی کہ ہمیں موت آگئی، اب سفارش کرنے والوں کی سفارش کام نہیں آئے گی\"۔\nجابر رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کوفرماتے سنا: «إِنَّ بَيْنَ الرَّجُلِ وَبَيْنَ الشِّرْکِ وَالْکُفْرِ تَرْکَ الصَّلاةِ». (صحیح مسلم: ۱۳۴/۸۲) \"مومن اور منکر اسلام میں فرق صرف نماز کا ہے\"۔\nبریدہ رضی اللہ عنہ سے مروی حدیث میں آیا ہےکہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «بَيْنَنَا وَبَيْنَهُمْ تَرْکُ الصَّلَاةِ فَمَنْ تَرَکَهَا فَقَدْ کَفَرَ». (مسند احمد: ۲۳۰۰۷)\nاورایک روایت میں ہے جابر رضی اللہ عنہ کہتے ہیں کہ میں نےنبی اکرم صلی اللہ علیہ وسلم کو فرماتے سنا: «بَيْنَ الْعَبْدِ وَبَيْنَ الْکُفْرِ أَوْ الشِّرْکِ تَرْکُ الصَّلاةِ». (مسند أحمد: ۱۴۹۷۹) \"ہمارے اور ان کے بیچ صرف نماز ہے۔ جس نے نماز چھوڑی اس نے کفر کیا\"۔\nاسی طرح زکاة نہ دینے والوں کے متعلق آیا ہے: ﴿وَٱلَّذِينَ يَكۡنِزُونَ ٱلذَّهَبَ وَٱلۡفِضَّةَ وَلَا يُنفِقُونَهَا فِي سَبِيلِ ٱللَّهِ فَبَشِّرۡهُم بِعَذَابࣲ أَلِيمࣲ﴾ [التوبة: ۳۴] \"جولوگ سونا چاندی جمع کرتے ہیں اور انھیں فی سبیل اللہ خرچ نہیں کرتے (زکاة نہیں دیتے) انھیں دردناک عذاب کی خبردے دو\"۔\nگناہ کبیرہ کی دوقسمیں ہیں۔ایک وہ جن کے کرنے پرسخت سزا ہے اور دوسرے وہ جن کے نہ کرنے پر سخت سزا ہے۔ بقیہ کچھ ایسے گناہ ہیں، جن کو صغیرہ گناہ کہاجاتاہے، اگر کبائر سے بچا جائے تو اللہ تعالیٰ مختلف نیک کام کے کرنے سے انھیں معاف کردیتاہے۔ ارشادباری تعالیٰ ہے : ﴿ٱلَّذِينَ يَجۡتَنِبُونَ كَبَٰٓئِرَ ٱلۡإِثۡمِ وَٱلۡفَوَٰحِشَ إِلَّا ٱللَّمَمَۚ إِنَّ رَبَّكَ وَٰسِعُ ٱلۡمَغۡفِرَةِۚ هُوَ أَعۡلَمُ بِكُمۡ إِذۡ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَإِذۡ أَنتُمۡ أَجِنَّةࣱ فِي بُطُونِ أُمَّهَٰتِكُمۡۖ فَلَا تُزَكُّوٓاْ أَنفُسَكُمۡۖ هُوَ أَعۡلَمُ بِمَنِ ٱتَّقَىٰٓ﴾ [النجم: ۳۲] \"اور ان لوگوں کو جو بڑے گناہوں سے بچتے ہیں اور بےحیائی سے بھی سوائے کسی چھوٹے گناہ کے بے شک تیرا رب بہت کشادہ مغفرت والا ہے، وہ تمھیں بخوبی جانتا ہے جبکہ اس نے تمھیں زمین سے پیدا کیا اور جبکہ تم اپنی ماؤں کے پیٹ میں بچے تھے پس تم اپنی پاکیزگی آپ بیان نہ کرو۔ وہی پرہیزگاروں کو خوب جانتا ہے\"۔\nدوسری جگہ کہا گیا ہے: ﴿إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلࣰ ا كَرِيمࣰ ا﴾ [النساء: ۳۱] \"اگر تم گناہ کبیرہ سے بچتے رہے جن سے تمھیں روکا جارہا ہے تو ہم تمھاری چھوٹی چھوٹی برائیوں کو تم سے دور کریں گے اور تمھیں باعزت مقام پر داخلہ دیں گے\"۔\nاس آیت میں تو اللہ نے گناہ کبیرہ سے بچنے والوں کے لیے جنت کی بشارت دی ہے۔ کیوں کہ اچھے کام برے کاموں کے انجام کو مٹادیتے ہیں۔ (دیکھیے: سورہ ہود:۱۱۴)\nابوہریرہ رضی اللہ عنہ سے مروی حدیث میں ہے کہ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: «الصَّلوات الْخَمْسُ، وَالْجُمْعَةُ إِلَی الْجُمْعَةِ، وَرَمَضَانَ إِلَی رَمَضَانَ کَفَّارَةٌ لِمَا بَيْنَهُنَّ إذا اجْتُنِبَتِ الْکَبَائِرُ». (صحیح مسلم: ۱۴/۲۳۳) \"اگرگناہ کبیرہ سے بچا جائے تو پانچ وقت کی نمازیں اورایک جمعہ دوسرے جمعہ تک اور ایک رمضان دوسرے رمضان تک یہ سب ان کے درمیان ہونے والے گناہوں کو مٹادیتی ہیں\"۔\nہر مسلمان پرضروری ہے کہ وہ کبیرہ گناہوں کا علم رکھے اور ان سے بچنے کی کوشش کرے۔ کہیں اپنی لاعلمی یاجہالت کی بنا پہ وہ کسی گناہ کبیرہ میں نہ پڑ جائے اور اپنی آخری منزل آخرت کو نہ ضائع کر بیٹھے۔ اللہ تعالیٰ کا ارشادہے: ﴿خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ ذَٰلِكَ هُوَ ٱلۡخُسۡرَانُ ٱلۡمُبِينُ﴾ [الحج: ۱۱] \"دنیا بھی گئی اور آخرت بھی، یہی واضح نقصان ہے\"۔\nوہ غیرمسلم جو اسلام کو انتہا پسند مذہب کہتے ہیں ان کے لیے بھی اس میں بڑی تعلیم ہے اگر وہ علم لینا چاہیں۔","",{}],[503,"§کپڑا\nدیکھیے: لباس","",{}],[504,"§کپور\nدیکھیے: کافور","",{}],[505,"§کتا\nدیکھیے: کلب","",{}],[506,"§کتاب\nکتاب کے عام معنیٰ کتاب ہی کے ہیں، جس کو انگریزی میں بک(book)،ہندی میں پوتھی کہتے ہیں۔ اردو میں کتاب ہی مستعمل ہےاور اس کی جمع کتب ہے،جواردو میں بھی استعمال ہے۔ اردو میں اس کی جمع کتابیں بھی ہیں۔ لیکن قرآن مجیدمیں یہ لفظ مختلف معنوں میں استعمال ہوا ہے۔ ان میں سے کچھ معانی درج ذیل ہیں :\n۱- مذہبی کتاب: جیسے قرآن مجیدکو الکتاب کہا گیا ہے، سورہ البقرة کی پہلی آیت ہی میں ارشادباری تعالیٰ ہے:﴿ذَٰلِكَ ٱلۡكِتَٰبُ لَا رَيۡبَۛ فِيهِۛ هُدࣰ ى لِّلۡمُتَّقِينَ﴾ [البقرة: ۲] \"یہ کتاب ہے،جس میں کوئی شک نہیں ہے۔ ان لوگوں کےلیے رہنمائی ہے، جو اللہ سے ڈرتے ہیں\"۔\nمطلب یہ ہے کہ اس قرآن کا اللہ کی طرف سے ہونے میں کوئی شک نہیں ہے۔\nارشادباری تعالیٰ ہے : ﴿هُوَ ٱلَّذِيٓ أَنزَلَ عَلَيۡكَ ٱلۡكِتَٰبَ﴾ [آل عمران: ۷] \"وہی(اللہ) توہے جس نے تم پر کتاب نازل کی\"۔\nاسی طرح قرآن مجیدسے پہلے جو کتابیں نازل کی گئیں ان کو بھی کتاب کہا گیا ہے۔\nتورات کے تعلق سےقرآن مجیدمیں آیا ہے:﴿وَإِذۡ ءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَٱلۡفُرۡقَانَ لَعَلَّكُمۡ تَهۡتَدُونَ﴾ [البقرة: ۵۳] \"یاد کرو جب ہم نے موسیٰ کو کتاب اور معجزہ دیا، تاکہ تم لوگ ہدایت حاصل کرسکو\"۔\nقرآن مجیدمیں انجیل کو بھی کتاب کہا گیا ہے:﴿قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيࣰّ ا﴾ [مریم: ۳۰] \"وہ بچہ (عیسی علیہ السلام) بول اٹھا: میں اللہ کا بندہ ہوں۔ اس نے مجھے کتاب عطا کی اور نبی بنایا\"۔\n۲- لوح محفوظ: قرآن مجیدمیں لوح محفوظ کو کتاب کہا گیا ہے۔ آسمان میں وہ جگہ جہاں سبھی جانداروں کی قسمت محفوظ ہے اور جو کچھ ہورہا ہے،وہاں اس کا ریکارڈ رکھا ہوا ہے:﴿وَمَا مِن دَآبَّةࣲ فِي ٱلۡأَرۡضِ وَلَا طَٰٓئِرࣲ يَطِيرُ بِجَنَاحَيۡهِ إِلَّآ أُمَمࣱ أَمۡثَالُكُمۚ مَّا فَرَّطۡنَا فِي ٱلۡكِتَٰبِ مِن شَيۡءࣲۚ﴾ [الأنعام: ۳۸] \"دنیا میں چل نے والا کوئی بھی جاندار ہو اور اپنے دوپروں سے اڑنے والا کوئی بھی پرندہ ہو، ان سب کے تمھارے جیسے ہی گروہ ہیں۔ ہم نے کتاب (لوح محفوظ) میں لکھنے سے کوئی چیز نہیں چھوڑی ہے\"۔\nاورفرمایا: ﴿وَمَا يَعۡزُبُ عَن رَّبِّكَ مِن مِّثۡقَالِ ذَرَّةࣲ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ وَلَآ أَصۡغَرَ مِن ذَٰلِكَ وَلَآ أَكۡبَرَ إِلَّا فِي كِتَٰبࣲ مُّبِينࣲ﴾ [یونس: ۶۱] \"ذرّہ برابر بھی کوئی چیز یا اس سے بھی چھوٹی یا بڑی چیززمین اور آسمان میں ایسی نہیں ہے جوتیرے رب سے پوشیدہ ہو، وہ سب کچھ ایک واضح کتاب (لوح محفوظ) میں ہے\"۔\nاورفرمایا: ﴿وَمَا مِن دَآبَّةࣲ فِي ٱلۡأَرۡضِ إِلَّا عَلَى ٱللَّهِ رِزۡقُهَا وَيَعۡلَمُ مُسۡتَقَرَّهَا وَمُسۡتَوۡدَعَهَاۚ كُلࣱّ فِي كِتَٰبࣲ مُّبِينࣲ‏﴾ [ہود: ۶] \"زمین میں چلنے والا کوئی ایسا جاندار نہیں ہے،جس کی روزی اللہ کے ذمے نہ ہو اور جس کے رہنے کی جگہ اور اس کے سونپے جانے کی جگہ وہ نہ جانتا ہو۔ یہ سب کچھ ایک واضح کتاب (لوح محفوظ) میں لکھا ہوا ہے\"۔\nمزیدارشادباری تعالیٰ ہے: ﴿وَمَا مِنۡ غَآئِبَةࣲ فِي ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِلَّا فِي كِتَٰبࣲ مُّبِينٍ﴾ [النمل: ۷۵] \"آسمان وزمین میں کوئی پوشیدہ شئے ایسی نہیں ہے جو ایک واضح کتاب میں لکھی ہوئی نہ ہو\"۔\n۳-اعمال نامہ: قیامت کے روز ہرشخص کے ہاتھ میں اس کو اس کا اعمال نامہ دیا جائے گا۔اس کے لیے بھی قرآن مجید میں کتاب کا لفظ استعمال کیا گیا ہے:﴿كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينࣲ وَمَآ أَدۡرَىٰكَ مَا سِجِّينࣱ كِتَٰبࣱ مَّرۡقُومࣱ‏﴾ [المطففین: ۷-۹] \"بے شک غلط کام کرنے والوں کی کتاب (اعمال نامہ)سجین میں ہے۔تمھیں کیامعلوم سجین کیا ہے؟ یہ تو ایک تحریر کی ہوئی کتاب ہے\"۔\nسجین میں وہ کتاب موجود ہوگی، جو غلط کام کرنے والوں کا قید خانہ ہے اور جس میں ان غلط کام کرنے والوں کا ذکر کیا گیا ہوگا۔ ایک جگہ پر کہا گیا:﴿وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِشِمَالِهِۦ فَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُوتَ كِتَٰبِيَهۡ﴾ [الحاقة: ۲۵] رہا وہ جسے اس کی کتاب (اعمال نامہ) اس کے بائیں ہاتھ میں دی گئی، وہ کہے گا: ہائے، کیا اچھا ہوتا کہ میری کتاب(اعمال نامہ) نہ دی جاتی۔\nاور نیک کام کرنے والا کہے گا:﴿فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَيَقُولُ هَآؤُمُ ٱقۡرَءُواْ كِتَٰبِيَهۡ﴾ [الحاقة: ۱۹] \"تو جسےاس کی کتاب (اعمال نامہ) اس کے داہنے ہاتھ میں دی گئی، تو وہ لوگوں سے کہے گا:لو میری کتاب (اعمال نامہ) پڑھو\"۔\n۴- خط،مراسلہ اور مکتوب: جیسا کہ سلیمان علیہ السلام نے ہدہد سے کہا تھا کہ میرا یہ خط لے کرسبا کی ملکہ کے پاس جا اورفرمایا: ﴿ٱذۡهَب بِّكِتَٰبِي هَٰذَا فَأَلۡقِهۡ إِلَيۡهِمۡ ثُمَّ تَوَلَّ عَنۡهُمۡ فَٱنظُرۡ مَاذَا يَرۡجِعُونَ قَالَتۡ يَٰٓأَيُّهَا ٱلۡمَلَؤُاْ إِنِّيٓ أُلۡقِيَ إِلَيَّ كِتَٰبࣱ كَرِيمٌ إِنَّهُۥ مِن سُلَيۡمَٰنَ وَإِنَّهُۥ بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ﴾ [النمل: ۲۸-۳۰] \"میری اس کتاب (خط) کے ساتھ جا اور اسے ان کی طرف ڈال دے، (سبا کی ملکہ کے دربار میں) پھر ان کے پاس سے لوٹ آؤ، دیکھ کہ وہ کیا جواب دیتے ہیں\"۔سبا کی ملکہ نے کہا:اے سردارو! میری طرف ایک معزز کتاب (خط) ڈالی گئی ہے۔ وہ سلیمان کی طرف سے ہے اور وہ اللہ کے نام سے شروع کی گئی ہے، جو نہایت رحم والا اور مہربان ہے\"۔\n۵- فیصلہ: قرآن مجیدمیں کہا گیا ہے: ﴿لَّوۡلَا كِتَٰبࣱ مِّنَ ٱللَّهِ سَبَقَ لَمَسَّكُمۡ فِيمَآ أَخَذۡتُمۡ عَذَابٌ عَظِيمࣱ‏﴾ [الأنفال: ۶۸] \"اگر اللہ کی لکھی ہوئی(کتاب)پہلے سے موجود نہ ہوتی تو جو پالیسی تم نے اپنائی ہے، اس پر تمھیں کوئی بڑی سزا آلیتی\"۔\nاس آیت میں جنگ بدر کی طرف اشارہ کیا گیا ہے۔جب مسلمان فتح یاب ہوے اور دشمن قیدیوں کو تاوان لے کر آزاد کرنے لگے، جب کہ چاہیے تو یہ تھاکہ پہلے ان کی طاقت توڑی جاتی، تاکہ وہ مسلمانوں پر کبھی حملہ کرنے کے قابل نہ رہتے، مگرجن گی تاوان وصول کرکے ان کو چھوڑنے کی اجازت تھی، اس لیے ان کےاس کام کو اللہ نے معاف کر دیا، جیسا کہ اس سے اگلی آیت میں بتایا گیا ہے۔ اس آیت میں کتاب سےمراد اللہ کا وہ فیصلہ ہے جو اس نے پہلے دے دیا تھا۔","",{}],[507,"§کرسی\nکرسی کا ذکر قرآن مجیدمیں دو مقامات پر آیا ہے:\n۱-آیت الکرسی میں کرسی کو جوآسمانوں اور زمین کو اپنی وسعت میں لیے ہوئی ہے اور اس کی نسبت اللہ تعالیٰ سے ہے:﴿ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةࣱ وَلَا نَوۡمࣱۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءࣲ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ﴾ [البقرة: ۲۵۵] \"اللہ کے سوا کوئی عبادت کے لائق نہیں، وہ زندہ ہے، سب کو سنبھالنے اور قائم رکھنے والا ہے۔ اسے نہ اونگھ آتی ہے نہ نیند۔ آسمان وزمین کی سبھی چیزیں اسی کی ہیں۔ کون ہے جو اس کی اجازت کے بغیر اس کے سامنے سفارش کر سکے۔ وہ جانتا ہے کہ جو کچھ اس کے سامنے ہےاور جو کچھ اس کے پیچھےاور وہ اس کے علم میں سے کسی چیز کا گھیرا نہیں کر سکتے، لیکن وہ جتنا چاہے۔ اس کی کرسی کے احاطے نے آسمان اور زمین کو گھیر رکھا ہے۔ وہ اللہ ان کی حفاظت سے نہ تو تھکتا ہے اور نہ تنگ آتا ہے۔ وہ عظیم و اعلیٰ ہے\"۔\nاس آیت کو آیت الکرسی کہتے ہیں۔ صحیح حدیث میں اسے کافی اہم بتایا گیا ہے اور متعدد بار اس کی اہمیت بیان کی گئی ہے۔جیسا کہ صحیح مسلم میں آیا ہے:نبی اکرم صلی اللہ علیہ وسلم نے ابی بن کعب رضی اللہ عنہ سے پوچھا : «يَا أَبَا الْمُنْذِرِ! أَتَدْرِي أَيُّ آيَةٍ مِنْ کِتَابِ اللَّهِ مَعَکَ أَعْظَمُ؟ قَالَ: قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: يَا أَبَا الْمُنْذِرِ! أَتَدْرِي أَيُّ آيَةٍ مِنْ کِتَابِ اللَّهِ مَعَکَ أَعْظَمُ؟ قَالَ: قُلْتُ: اللَّهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ، قَالَ: فَضَرَبَ فِي صَدْرِي وَقَالَ: وَاللَّهِ لِيَهْنِکَ الْعِلْمُ أَبَا الْمُنْذِرِ». (صحیح مسلم: ۲۵۸/۸۱۰بروایت ابی بن کعب) \"اے ابو مُنذر! کیا تمھیں معلوم ہے کی اللہ کی کتاب میں عظیم آیت کونسی ہے؟انھوں نے کہا:اللہ اور اس کے رسول کو اس کا زیادہ علم ہے۔پھر آپ صلی اللہ علیہ وسلم نے اس سے یہی بات پوچھی تو انھوں نے آیت الکرسی کا نام لیا۔ اس پر آپ صلی اللہ علیہ وسلم نے ان کے سینے پر ہاتھ رکھ کر کہا اے ابو مُنذر! اللہ تیرے علم کو مبارک کرے\"۔\nآیت الکرسی کی عظمت کے تعلق سے یہ حدیث بھی آئی ہے: ابوہریرہ رضی اللہ عنہ سےمروی ہےکہ نبی اکرم صلی اللہ علیہ وسلم نےمجھ سےپوچھا: «مَا فَعَلَ أَسِيرُکَ الْبَارِحَةَ؟ قُلْتُ: يَا رَسُولَ اللَّهِ؛ زَعَمَ أَنَّهُ يُعَلِّمُنِي کَلِمَاتٍ يَنْفَعُنِي اللَّهُ بِهَا فَخَلَّيْتُ سَبِيلَهُ قَالَ: مَا هِيَ؟ قُلْتُ: قَالَ لِي: إِذَا أَوَيْتَ إِلَی فِرَاشِکَ فَاقْرَأْ آيَةَ الْکُرْسِيِّ مِنْ أَوَّلِهَا حَتَّی تَخْتِمَ الآيَةَ: اللَّهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ، وَقَالَ لِي: لَنْ يَزَالَ عَلَيْکَ مِنْ اللَّهِ حَافِظٌ وَلا يَقْرَبَکَ شَيْطَانٌ حَتَّی تُصْبِحَ، وَکَانُوا أَحْرَصَ شَيْءٍ عَلَی الْخَيْرِ، فَقَالَ النبی صَلَّی اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّهُ قَدْ صَدَقَکَ وَهُوَ کَذُوبٌ، تَعْلَمُ مَنْ تُخَاطِبُ مُنْذُ ثَلاثِ لَيَالٍ يَا أَبَا هُرَيْرَةَ؟ قَالَ: لا، قَالَ: ذَاکَ شَيْطَانٌ». (صحیح البخاری: ۲۳۱۱) \"ابوہریرہ! رات تیرے قیدی کا کیا معاملہ ہوا؟ میں نے عرض کیا: اس نے مجھ سے کہا کہ وہ مجھ کو چند کلمات سکھا دےگا جن کے ذریعہ اللہ تعالیٰ مجھے نفع پہنچائے گا، اس نے کہا: جب تم رات کو اپنے بچھونا پر جاؤ تو اول سے اخیر تک آیت الکرسی پڑھ لو رات بھر اللہ کی طرف سے تمھارےلیے ایک محافظ ہوگا اورشیطان تیرے پاس نہیں آئے گا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:اس نے تم سے بات تو سچی بتائی لیکن وہ ہے جھوٹا، جانتے ہو تین راتوں سے تم کس سے مخاطب تھے؟ ابوہریرہ نے عرض کیا: نہیں، آپ نے فرمایا: وہ شیطان تھا\"۔\nکرسی اللہ رب العزت کی عظیم مخلوقات میں سے ایک مخلوق ہے۔ اس کے بارے میں اہل سنت کا مذہب یہ ہے کہ کرسی رب عزوجل کے دونوں قدموں کی جگہ ہے، جو عرش کے سامنے ہے اور اللہ رب العزت عرش کے اوپر بلندو بالا ہے۔لیکن عرش وکرسی کے معنی کو سمجھنے کے بعد اس کی کیفیت کے بارے میں سوال صحیح نہیں ہے۔اللہ اور اس کےرسول نےعرش وکرسی کے بارے میں جومعلومات دی ہیں، اسی پراکتفاکرناچاہیے اوران عظیم مخلوقات کے ذریعے اللہ سبحانہ وتعالیٰ کی قدرت کاملہ اور اس کی عظمت اور بزرگی کاتصورکرناچاہیے۔\n۲- قرآن مجیدمیں دوسرا مقام جہاں کرسی کا استعمال ہوا ہےوہ سورہ ص کی آیت ۳۴ ہے،جس میں سلیمان علیہ السلام کی کرسی کا ذکر کیا گیا ہے، جس پر بیٹھ کر وہ حکومت چلاتے تھے، اس مقام پر آیا ہے: ﴿وَلَقَدۡ فَتَنَّا سُلَيۡمَٰنَ وَأَلۡقَيۡنَا عَلَىٰ كُرۡسِيِّهِۦ جَسَدࣰ ا ثُمَّ أَنَابَ﴾ [ص: ۳۴] \"يقيناً ہم نے سلیمان کو امتحان میں ڈالا اور ہم نے اس کی کرسی پر ایک جسم ڈال دیا۔ پھر اس نے رجوع کیا\"۔\nیہ امتحان کیا تھا؟ کرسی پر کس کاجسم ڈالا گیا تھا۔ ان باتوں کا کوئی ذکر قرآن اور صحیح احادیث میں نہیں ملتا۔ (تفصیل کے لیے دیکھیں : سلیمان)","",{}],[508,"§کریم\nدیکھیے: اسماےحسنی","",{}],[509,"§کشتی والے\nدیکھیے: اصحاب سفینہ","",{}],[510,"§کعبہ\nکعبہ کو بیت اللہ بھی کہتےہیں۔ اسے ابراہیم علیہ السلام نے اپنے بیٹے اسماعیل علیہ السلام کے ساتھ مل کرتعمیرکیا تھا۔یہ چوکور(مکعب)عمارت ہے،اس لیے اس کو کعبہ کہتے ہیں۔یہی وہ قبلہ ہے جس کی طرف مسلمان منہ کرکے نماز اداکرتے ہیں۔یہی وہ پہلا گھر ہے جسےصرف ایک اللہ کی عبادت کے لیے مکہ میں بنایا گیا۔کعبہ میں ایک دروازہ ہے۔ اس دروازے اور حجراسود کے مابین کعبہ کی دیوارکوملتزم کہا جاتاہے،جس کے بارے میں حدیث میں آتاہےکہ رسول اللہ صلی اللہ علیہ وسلم نے اپناسینہ، چہرہ، بازواور ہتھیلی کعبہ کی دیوارسےچمٹاکردعاکی۔(سنن ابی داود: ۱۸۹۹، سنن ابن ماجہ: ۲۹۶۲) اسی لیےاس جگہ کا نام ملتزم پڑا۔ کعبہ زمین سےقریب چھ، سات فٹ اونچا ہے۔کعبہ کے جنوب مشرقی کونے میں حجراسود ہے، جو جنت کا پتھر ہے۔ اسے مسلمان بوسہ لیتے ہیں۔ کعبہ کے مشرق میں مقام ابراہیم(وہ پتھرجس پر ابراہیم علیہ السلام کے پاؤں کا نشان ہے)ہے،جوایک بڑی نشانی ہے۔اس کا ذکر قرآن کریم میں آیا ہے۔ (البقرہ:۱۲۵، آل عمران:۹۷)\nکعبہ کے شمال میں ایک جگہ ہے جسے حطیم اور حجر کہتےہیں۔یہ حقیقت میں کعبہ کا ہی ایک حصہ ہے۔مگر اسلام سے پہلے جب قریش دوبارہ کعبہ کی تعمیر کر رہے تھے، اس وقت ان کے پاس حلال کی کمائی اتنی نہ تھی کہ کعبہ کو اس کی اصل بنیادوں پر اٹھائیں۔ اس لیے انھوں نے اتنے حصے کو کم کر دیا۔\nاس سلسلے میں ام المومنین عائشہ ڤکہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: \"اےعائشہ! اگر تمھاری قوم والے نئے نئے مسلمان نہ ہوتے تو میں کعبہ کو گراکر دوبارہ بناتا اور اس کا ایک پچھلا دروازہ بھی بنا دیتا اورحطیم کو اس میں ملا لیتا\"۔(صحیح مسلم: ۳۹۸/۱۳۳۳)\nتاریخی کتابوں سے پتا چلتا ہے کہ اسماعیل علیہ السلام کے بعد ایک ہزار سال تک بنو جرہم کعبہ کے نگراں (متولی) رہےاور آخر میں اس کے نگراں قریش بنے۔ بعد میں اس کا نگراں قریش کا ایک قبیلہ بنا۔جس وقت مکہ فتح ہوا، اس وقت کعبہ کی کنجی اسی قبیلے کےدوشخص عثمان بن طلحہ بن ابی طلحہ اور ان کے چچا زاد بھائی شیبۃ بن عثمان بن ابی طلحہ کے پاس تھی۔فتح مکہ کے موقعے پرنبی اکرم صلی اللہ علیہ وسلم نے ان کو کعبہ کادروازہ کھولنے کے لیے کہا اور آپ کعبہ میں داخل ہوے۔پہلے آپ نے اللہ کے گھر کو بتوں سے پاک صاف کیا، اس کے بعد دو رکعت نماز ادا کی۔ پھر کعبہ کی کنجی انھی کو لوٹا دی اور فرمایا: یہ قیامت تک انھی کے پاس رہنی چاہیے۔ان سے چھیننے والا ظالم ہوگا۔(المعجم الکبیرللطبرانی: ۱۱/۲۰)\nاس حدیث کی سند میں کچھ کمزوری ہے، لیکن دوسری سندوں سے اس کی توثیق ہوجاتی ہے۔ سن ۴۲ ہجری میں عثمان بن ابی طلحہ کی وفات ہوگئی تو کعبہ کی کنجی شیبہ بن عثمان بن ابی طلحہ کو مل گئی۔ آج تک یہ کنجی شیبہ ہی کے خاندان کے پاس ہے۔ وہی کعبہ کو کھولتے ہیں اور انھی کے ذریعے سے کعبہ پر غلاف چڑھایا جاتا ہے۔\nیہی وہ کعبہ ہے،جس کو گرانے کے لیےاوراس کے نشانات کو مٹانے کے لیے یمن سے ’ابرہہ‘نامی بادشاہ ایک بڑی فوج لےکر، جس میں ہاتھیوں کا بھی ایک جھنڈ تھا، مکہ آیا۔ مگر راستے میں ہی اللہ تعالیٰ نےاسے نیست و نابود کر دیا۔اسی واقعے کو سورة الفیل میں اس طرح بیان کیا گیا ہے:﴿أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلࣲ وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ تَرۡمِيهِم بِحِجَارَةࣲ مِّن سِجِّيلࣲ فَجَعَلَهُمۡ كَعَصۡفࣲ مَّأۡكُولِۭ﴾ [الفیل: ۱-۵] \"کیا تم نے نہیں دیکھا کہ تمھارے رب نے ہاتھی والوں کے ساتھ کیا کیا؟ کیا اس نے ان کی چال کو ناکام نہیں کر دیا؟ اور ان پر جھنڈ کے جھنڈ پرندے بھیج دیے، جو انھیں مٹی اور پتھر کی کنکریوں سے مار رہے تھے۔ آخر کار انھیں بھوسے کی طرح ریزہ ریزہ کر دیا\"۔\nیہی وہ کعبہ ہے جس کی وجہ سے مکہ کے قریش کو عزت ومرتبہ ملا۔ اسی کی وجہ سےاللہ تعالیٰ نےانھیں بھوک اور خوف سے محفوظ رکھا۔قرآن مجیدمیں ہے:﴿فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعࣲ وَءَامَنَهُم مِّنۡ خَوۡفِۭ﴾ [قریش: ۳-۴] \"اس لیے انھیں چاہیے کہ اس گھر (کعبہ) کے رب کی عبادت کریں، جس نے انھیں بھوک میں کھانا دیا اور خوف میں بے فکری دی\"۔\nکعبہ اورحطیم کے اندرنمازاداکرنے کا مسئلہ: نبی اکرم صلی اللہ علیہ وسلم فتح مکہ کے روز کعبہ میں داخل ہوے،تو آپ نےاس میں دو رکعت نفل نماز ادا کی(متفق علیہ)۔حطیم کے اندرنمازااداکرنا گویاکہ کعبہ کےاندر نماز ادا کرنا ہے۔ ام المومنین عائشہ ڤکہتی ہیں: \"میریخواہش تھی کہ کعبہ میں نماز ادا کریں۔نبی اکرم صلی اللہ علیہ وسلم نے ان کا ہاتھ پکڑا اور حطیم میں لے گئے۔فرمایا: تمھیں کعبہ میں نماز ادا کرنےکی تمناہے تو اس میں نماز ادا کر لو کیوں کہ یہ بھی کعبہ کا ایک حصہ ہے۔ مگر سرمائے کی کمی کے وجہ سے تمھاری قوم نے اس کو کعبہ سے الگ کر دیا تھا\"۔ (سنن ابی داود: ۲۰۲۸،سنن النسائی: ۲۹۱۵، سنن الترمذی: ۸۷۶)\nکعبہ کے اندراورحطیم میں نفل نمازجائز ہے۔اہل علم کا ان کے اندرفرض نماز کی ادائی کے بارے میں اختلاف ہے۔ اس لیے کہ نبی اکرم صلی اللہ علیہ وسلم نے ان مقامات پر فرض نماز نہیں اداکی۔ بعض علماء کہتے ہیں کہ کعبہ اور حجر دونوں جگہ نماز نہیں صحیح ہوگی۔احتیاط کا تقاضا یہی ہےکہ ان دونوں مقامات میں فرض نماز ادانہ کی جائے۔","",{}],[511,"§کفّارہ\nکفّارہ: کفّارکا مونث ہے۔اس کے لفظی معنی چھپانے والی چیزکے ہیں۔اسی لیے کسان اور کاشت کار کو کافرکہتے ہیں۔ کیوں کہ وہ بیج کو زمین میں چھپا دیتے ہیں۔ جیسا کہ قرآن مجیدمیں آیا ہے:﴿كَمَثَلِ غَيۡثࣲ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ﴾ [الحدید: ۲۰] \"جیسے ایک بارش ہوگئی تو اس سے پیدا ہونے والے نباتات کو دیکھ کر کفار (کسان) خوش ہوگئے\"۔\nشرعی اصطلاح میں گناہ کا کفارہ صدقہ یا روزہ ہے،جو کفارے میں اداکیاجائے۔ اس طرح اس کا اصلی اسلامی معنیٰ یہ ہواکہ کسی گناہ کے کام کا کفارہ اداکرکے خود کو پاک و صاف کیا جائے۔ قرآن اور صحیح احادیث میں مختلف امور کا مختلف کفارہ بتایا گیا ہے۔ جیسے :\n§ا- قسم کا کفارہ :\nقسم تین طرح کی ہوتی ہے:\nپہلی قسم: یمین لغو: عادت پڑجانے کی وجہ سےآدمی بات بات پرقسم کھاتے رہتے ہیں۔ لیکن اس کا حقیقی مقصد قسم کھانانہیں ہوتا۔ اس قسم کو یمین لغو کہتے ہیں۔ اس طرح کی قسم پر کوئی پکڑ نہیں ہے، جیسا کہ خود اللہ تعالیٰ کا ارشاد ہے: ﴿لَّا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ وَلَٰكِن يُؤَاخِذُكُم بِمَا كَسَبَتۡ قُلُوبُكُمۡۗ وَٱللَّهُ غَفُورٌ حَلِيمࣱ‏﴾ [البقرة: ۲۲۵] \"اللہ تمھاری ایسی قسموں پر تم کو نہیں پکڑے گا، جو یوں ہی منہ سے نکل گئی ہوں۔ لیکن ان قسموں پر تمھیں ضرور پکڑے گا، جو تمھارے دل کے ارادے کا نتیجہ ہوں۔ اور اللہ غفور وحلیم (بہت معاف کرنے والا،برداشت کرنے والا) ہے\"۔\nاورفرمایا: ﴿لَا يُؤَاخِذُكُمُ ٱللَّهُ بِٱللَّغۡوِ فِيٓ أَيۡمَٰنِكُمۡ﴾ [المائدة: ۸۹] \"تمھاری ان قسموں پر اللہ تمھیں نہیں پکڑتا جو یوں ہی غیر محتاطی میں زبان سے نکل جاتی ہیں\"۔\nدوسری قسم: یمین غموس۔یہ وہ جھوٹی قسم ہے جو تاجر اپنا مال فروخت کرنے کے لیے کھاتا یا ایک آدمی کسی کو پھنسانے کے لیے کھاتا ہے۔ یہ بہت بڑا گناہ ہے۔ صحیح حدیثوں میں اس کی کافی مذمت کی گئی ہے۔ عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں: «جَاءَ أَعْرَابِيٌّ إِلَی النبی صلی اللہ علیہ وسلم فَقَالَ: يَا رَسُولَ اللَّهِ! مَا الْکَبَائِرُ؟ قَالَ: الْإِشْرَاکُ بِاللَّهِ، قَالَ: ثُمَّ مَاذَا؟ قَالَ: ثُمَّ عُقُوقُ الْوَالِدَيْنِ، قَالَ: ثُمَّ مَاذَا؟ قَالَ: الْيَمِينُ الْغَمُوسُ، قُلْتُ: وَمَا الْيَمِينُ الْغَمُوسُ؟ قَالَ: الَّذِي يَقْتَطِعُ مَالَ امْرِئٍ مُسْلِمٍ هُوَ فِيهَا کَاذِبٌ». (صحیح البخاری: ۶۹۲۰، صحیح مسلم: ۸۷/۱۴۳) ایک بدو نےآکر نبی اکرم صلی اللہ علیہ وسلم سے بڑے گناہوں کے بارے میں پوچھا تو آپ نےفرمایا: اللہ کے ساتھ شرک کرنا۔ اس نے عرض کیا: اس کے بعد؟ فرمایا: ماں باپ کا کہنا نہ ماننا۔اس نے عرض کیا: اس کے بعد؟آپ نے فرمایا: \"یمین غموس۔ اس نے عرض کیا: یمین غموس کیا ہے؟ فرمایا: جس قسم کے ذریعے سے کسی مسلمان کا مال ہتھیا لیا جائے\"۔\nجھوٹی قسم کھانے والے کی سزا جہنم کی آگ بتائی گئی ہے۔ اس لیے ایسے آدمی کو چاہیے کہ وہ اپنے اس گناہ پر اللہ تعالیٰ سے معافی مانگے اور مستقبل میں ایسا نہ کرنے کا ارادہ کرے۔\nتیسری قسم:یہ ہے کہ کسی اچھے کام کو نہ کرنے کی قسم کھائی جائے۔ جیسےآدمی یہ کہے کہ میں دوبارہ غریبوں کی مدد نہیں کروں گا یا اپنے رشتے داروں سے نہیں ملوں گا، تو ایسے آدمی پر فرض ہے کہ وہ اپنی قسم توڑ دے اور اللہ کی قسم کو اچھے کام نہ کرنے کا بہانہ نہ بنائے۔ قرآن مجیدمیں ہے:﴿وَلَا تَجۡعَلُواْ ٱللَّهَ عُرۡضَةࣰ لِّأَيۡمَٰنِكُمۡ أَن تَبَرُّواْ وَتَتَّقُواْ وَتُصۡلِحُواْ بَيۡنَ ٱلنَّاسِۚ وَٱللَّهُ سَمِيعٌ عَلِيمࣱ‏﴾ [البقرة: ۲۲۴] \"اپنے نیک اور عادل ہونے اور لوگوں کے بیچ اصلاح کرنے کے تعلق سے اپنی قسموں کے ذریعے اللہ کو سہارا اور نشانہ مت بناؤ کہ ان کاموں کو چھوڑ دو، اللہ سب کچھ سنتا اورجانتا ہے\"۔\nابوموسیٰ اشعری رضی اللہ عنہ سےمروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لا أَحْلِفُ عَلَی يَمِينٍ فَأَرَی غَيْرَهَا خَيْرًا مِنْهَا إِلا أَتَيْتُ الَّذِي هُوَ خَيْرٌ وَتَحَلَّلْتُهَا». (صحیح البخاری: ۶۶۴۹، وصحیح مسلم ۱۶۴۹/۹).\"میں کوئی قسم کھاتا ہوں، پھر دیکھتا ہوں کہ دوسرا کام اس سے اچھا والا ہے، تو اچھا والا کام ہی کرلیتا ہوں اور اپنی قسم کا کفارہ دے دیتا ہوں\"۔\nقسم کا کفارہ :\nقسم کے کفارے کے بارے میں ارشادباری تعالیٰ ہے:﴿فَكَفَّٰرَتُهُۥٓ إِطۡعَامُ عَشَرَةِ مَسَٰكِينَ مِنۡ أَوۡسَطِ مَا تُطۡعِمُونَ أَهۡلِيكُمۡ أَوۡ كِسۡوَتُهُمۡ أَوۡ تَحۡرِيرُ رَقَبَةࣲۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامࣲۚ ذَٰلِكَ كَفَّٰرَةُ أَيۡمَٰنِكُمۡ إِذَا حَلَفۡتُمۡۚ وَٱحۡفَظُوٓاْ أَيۡمَٰنَكُمۡۚ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمۡ ءَايَٰتِهِۦ لَعَلَّكُمۡ تَشۡكُرُونَ﴾ [المائدة: ۸۹] \"دس غریبوں کو اوسط درجے کاکھانا کھلادو۔ جیسا کہ تم اپنے گھر والوں کو کھلاتے ہویا ان کو کپڑے پہنا دو یا ایک غلام آزاد کرو اورجو ان میں سے کسی کی طاقت نہ رکھتا ہو تو وہ تین دن روزے رکھے۔ یہ تمھاری قسموں کا کفارہ ہے۔ جب کہ تم قسم کھا بیٹھے اور تمھیں چاہیے کہ اپنی قسموں کا دھیان رکھو (جان بوجھ کر کسی گناہ کی قسم نہ کھاؤ)۔ اس طرح اللہ اپنی آیتوں کو تمھارے لیے کھول کھول کر بیان کرتا ہے تاکہ تم شکریہ ادا کرنے والا بن جاؤ\"۔\n§۲- احرام کی حالت میں شکار کرنے کا کفارہ :\nجوشخص حج یا عمرہ کی نیت سے مکہ کا سفر کرے، اس کے لیے شکار کرنا حرام ہے۔ قرآن مجیدمیں ہے: ﴿أُحِلَّ لَكُمۡ صَيۡدُ ٱلۡبَحۡرِ وَطَعَامُهُۥ مَتَٰعࣰ ا لَّكُمۡ وَلِلسَّيَّارَةِۖ وَحُرِّمَ عَلَيۡكُمۡ صَيۡدُ ٱلۡبَرِّ مَا دُمۡتُمۡ حُرُمࣰ اۗ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِيٓ إِلَيۡهِ تُحۡشَرُونَ﴾ [المائدة: ۹۶] \"اے ایمان والو! جب تم احرام کی حالت میں ہو تو شکار نہ کرو اور تم میں جو کوئی جان بوجھ کر شکار کرے گا تو چوپایوں میں سے اسی کے برابر ایک جانور کفارے میں دینا پڑے گا، جس کا فیصلہ تم میں سے دو انصاف پسند اشخاص کریں گے۔ وہ جانور قربانی کے لیے کعبہ پہنچایا جائے گا۔ یا وہ کفارے کی شکل میں محتاجوں کو کھانا کھلائے یا اس کے برابر روزہ رکھے تاکہ اپنی کئے کی سزا چکھے۔ جو پہلے ہوچکا اسے اللہ نے معاف کردیا، لیکن جس کسی نے پھر ایسا کیا تو اللہ اس سے بدلہ لے گا۔اللہ طاقتور اور بدلہ لینے والا ہے۔ تمھارے لیے سمندر میں شکار کرنا اور اسے کھانا حلال ہے، وہ تمھارے لیے اور مسافروں کے لیے کھانے کی چیز ہے۔ لیکن زمینی شکار، جب کہ تم احرا م کی حالت میں ہو، تم پر حرام کیا گیا ہے۔ اللہ سے ڈرتے رہو، جس کے پاس تم کو جمع کیا جائے گا\"۔\n§۳-احرام کی حالت میں سر منڈوانے کا کفارہ:\nحج یا عمرے کی نیت کے بعد احرام کی حالت میں سر کے بال منڈوانے پر کفارہ ادا کرناواجب ہے۔ اگر کسی کے سرمیں کوئی ایسی بیماری ہو یا جوئیں وغیرہ ہوجس کی وجہ سے سر کے بال منڈوانے پڑجائیں تو اس کا کفارہ قرآن مجیدمیں یہ بتایا گیا ہے :﴿فَمَن كَانَ مِنكُم مَّرِيضࣰ ا أَوۡ بِهِۦٓ أَذࣰى مِّن رَّأۡسِهِۦ فَفِدۡيَةࣱ مِّن صِيَامࣲ أَوۡ صَدَقَةࣲ أَوۡ نُسُكࣲۚ﴾ [البقرة: ۱۹۶] \"تم میں سے جو بیمار ہو، یا اس کے سر میں کوئی تکلیف ہو، جس کی وجہ سے وہ سر منڈوالے تو اس پر فدیہ ہے۔ چاہے وہ روزے رکھے، چاہے خیرات دے، چاہے قربانی دے\"۔\nقرآن مجیدمیں اس خیروخیرات کی تفصیل نہیں آئی ہے۔ لیکن ایک صحیح حدیث میں کعب بن عجرة رضی اللہ عنہ کہتے ہیں: «وَقَفَ عَلَيَّ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم بِالْحُدَيْبِيَةِ وَرَأْسِي يَتَهَافَتُ قَمْلا، فَقَالَ: يُؤْذِيکَ هَوَامُّکَ؟ قُلْتُ: نَعَمْن قَالَ: فَاحْلِقْ رَأْسَکَ، أَوْ قَالَ: احْلِقْ، قَالَ: فِيَّ نَزَلَتْ هَذِهِ الآيَةُ:﴿فَمَن كَانَ مِنكُم مَّرِيضࣰ ا أَوۡ بِهِۦٓ أَذࣰى مِّن رَّأۡسِهِۦ فَفِدۡيَةࣱ مِّن صِيَامࣲ أَوۡ صَدَقَةࣲ أَوۡ نُسُكࣲۚ﴾ [البقرة: ۱۹۶] إِلَی آخِرِهَا، فَقَالَ النبی صلی اللہ علیہ وسلم : صُمْ ثَلاثَةَ أَيَّامٍ أَوْ تَصَدَّقْ بِفَرَقٍ بَيْنَ سِتَّةٍ أَوْ انْسُکْ بِمَا تَيَسَّرَ». (صحیح البخاری: ۱۸۱۵، وصحیح مسلم :۱۲۰۱/۸۲-۸۵) \" میرے سر میں جوئیں پڑگئی تھیں جس کی وجہ سے مجھے تکلیف ہوتی تھی، اسی لیے نبی اکرم صلی اللہ علیہ وسلم نے مجھے حکم دیا کہ اپنا سر منڈوا دوں۔ فدیہ میں یہ کہا کہ یا تو تین دن روزے رکھوں یا ایک فرق (تین صاع یعنی ساڑھے سات کلو غلہ)چھ غریبوں کو کھانا کھلاؤں، یا جو بھی میرے لیے آسان ہو اس کی قربانی کروں۔(اونٹ، بکری وغیرہ)\"۔\n§۴- قتل ناحق کا کفارہ :\nکسی کا ناحق قتل بہت بڑاگناہ ہے اور کوئی مسلمان کسی مسلمان بھائی کا قتل کرے، یہ تو اور بھی بڑا گناہ ہے۔ ایسےقاتل کی قرآن اور صحیح حدیثوںمیں شدیدمذمت کی گئی ہے اور سخت عذاب کی وعیدہے۔ ایسےشخص کو دنیامیں تو قتل کرنے کی سزا دی ہی جائے گی۔ آخرت میں بھی اسے جہنم میں ڈالا جائے گا، جو جان بوجھ کر کسی مسلمان بھائی کا خون بہائے۔ البتہ اگر کسی نے دھوکے میں کسی کا قتل کر دیا ہوتو اس کا کفارہ قرآن مجیدمیں یہ بتایا گیا ہے:﴿وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـࣰٔ اۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـࣰٔ ا فَتَحۡرِيرُ رَقَبَةࣲ مُّؤۡمِنَةࣲ وَدِيَةࣱ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوࣲّ لَّكُمۡ وَهُوَ مُؤۡمِنࣱ فَتَحۡرِيرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقࣱ فَدِيَةࣱ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةࣲ مُّؤۡمِنَةࣲۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةࣰ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمࣰ ا﴾ [النساء: ۹۲] \"یہ کسی ایمان والے کا کام نہیں ہے کہ وہ کسی ایمان والےکا قتل کرے سوائے بھول چوک کے۔ اورجو شخص بھول سے کسی ایمان والے کا قتل کر دے تو ایک ایمان والے شخص کو غلامی سے آزاد کرنا ہوگااور اس قتل کئے گئے شخص کے گھر والوں کو خون کے بدلے میں دیت دینی ہوگی۔ ہاں، اگر وہ معاف کردیں تو اور بات ہے اور اگر وہ ان لوگوں میں سے ہے، جو تمھارے دشمن ہوں اور وہ (مرجانے والا) خود ایمان والا ہو،تو ایک ایمان والے شخص کو غلامی سے آزاد کرنا ہوگا۔ اگر وہ ان لوگوں میں سے ہوکہ تمھارے اور ان کے بیچ معاہدہ اور سمجھوتہ ہو، تو اس کے گھر والوں کو خون کے بدلے تمھیں دیت دینی ہوگی اور ایمان والے کو غلامی سے آزاد کرنا ہوگا۔ پھر جو غلام نہ پائے وہ دو مہینہ لگاتار روزے رکھے۔ یہ اللہ کی طرف سے ٹھہرائی ہوئی توبہ ہے۔ اور اللہ علیم وحکیم( سب کچھ جاننے والا،حکمت والا) ہے\"۔\n§۵- ظہار کا کفارہ :\nظہار:ظہرسےہے۔ظہرکامعنی پیٹھ کے ہیں۔شرعی اصطلاح میں ظہارکا مطلب یہ ہے کہ آدمی اپنی بیوی کی پیٹھ کو ماں کی پیٹھ کی مانند کہےیعنی اس کو اپنے لیے حرام کرلے۔یہ چیزاسلام سے پہلے عربوں پائی جاتی تھی۔اگر کوئی شخص اپنی بیوی کو یہ کہ دیتا تھا کہ تم میرے لیے ویسی ہی ہو جیسے میرے لیے میری ماں کی پیٹھ، تو ایسا کرنے سے ان کی شادی ٹوٹی ہوئی مانی جاتی اور بیوی ہمیشہ کے لیے حرام ہو جاتی تھی۔اس لیے اوس بن صامت رضی اللہ عنہ نے جب اپنی بیوی خولہ بنت مالکڤ سے ظہار کیا تو نبی اکرم صلی اللہ علیہ وسلم کےپاس جاکرکہا کہ اس عمر میں ہم دونوں کیسے الگ ہوسکتے ہیں؟ اس پر سورہ المجادلہ نازل ہوئی، جس میں آیاہے کہ ظہار کرنے سے بیوی ماں کے برابر نہیں ہوجاتی۔ ماں تو وہی ہے جس نے تم کوجنا۔ البتہ ایسا کہنا بہت بڑا گناہ ہےاور بیوی اس وقت تک حرام رہے گی جب تک کفارہ ادا نہ کر دیا جائے۔ارشادباری تعالیٰ ہے: ﴿وَٱلَّذِينَ يُظَٰهِرُونَ مِن نِّسَآئِهِمۡ ثُمَّ يَعُودُونَ لِمَا قَالُواْ فَتَحۡرِيرُ رَقَبَةࣲ مِّن قَبۡلِ أَن يَتَمَآسَّاۚ ذَٰلِكُمۡ تُوعَظُونَ بِهِۦۚ وَٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرࣱ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ مِن قَبۡلِ أَن يَتَمَآسَّاۖ فَمَن لَّمۡ يَسۡتَطِعۡ فَإِطۡعَامُ سِتِّينَ مِسۡكِينࣰ اۚ ذَٰلِكَ لِتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦۚ وَتِلۡكَ حُدُودُ ٱللَّهِۗ وَلِلۡكَٰفِرِينَ عَذَابٌ أَلِيمٌ﴾ [المجادلة: ۳-۴] \"جو لوگ اپنی بیویوں سے ظہار کرتے ہیں، پھر کہی ہوئی بات واپس لے لیتے ہیں تو ان کے اوپر آپس میں ایک دوسر ے کو ہاتھ لگانے سے قبل ایک غلام کو آزاد کرنا ہوگا۔ اس طرح تم کو تعلیم دی جارہی ہے، اللہ تمھارے سارے کاموں کو جانتا ہے۔ لیکن جو شخص غلام آزاد نہ کر سکے وہ دو ماہ تک لگاتا ر روزے رکھے، اس سے پہلےکہ وہ ایک دوسرے کوہاتھ لگائیں (جنسی تعلقات قائم کریں )۔لیکن جو اس کی بھی طاقت نہ رکھتا ہو اس پر ساٹھ غریبوں کو کھانا کھلانا ہے۔ یہ اس لیے کہ تم اللہ پر اور اس کے رسول پر ایمان لاؤ۔یہ اللہ کی طے کی ہوئی حدود ہیں اور انکار کرنے والوں کے لیے تکلیف دہ عذاب ہے\"۔\n§۶- رمضان میں روزے کی حالت میں مجامعت کا کفارہ :\nرمضان میں روزے رکھنا فرض ہے،جس کے ذریعے سے روح کی صفائی اور اللہ تعالیٰ کی رضا حاصل ہوتی ہے۔ کیوں کہ صبح سے شام تک صرف اللہ کی رضا حاصل کرنےکے لیےکھانا پینا اورجنسی تعلقات چھوڑ کر ایک روزےدار اپنے بارے میں اللہ کا سچا بندہ ہونے کا ثبوت دیتاہے۔ اس لیے اس حالت میں جنسی تعلق قائم کرنا گناہ عظیم قرار دیا گیا ہے۔اگر کسی نے ایسا کیا تو اسے اپنے کئے پر اللہ تعالیٰ سے معافی مانگنی چاہیے۔اس کےساتھ کفارہ بھی ادا کرنا واجب ہے،جس کی تفصیل ایک صحیح حدیث میں آئی ہے۔ابوہریرہ رضی اللہ عنہ کہتے ہیں:\"ایک شخص نےنبی اکرم صلی اللہ علیہ وسلم کے پاس آکر کہا:میں نے رمضان (روزے کی حالت )میں اپنی بیوی کے ساتھ تعلق قائم کر لیا۔آپ نے فرمایا:ایک غلام آزاد کرو۔اس نے کہا:میرے پاس کوئی غلام نہیں ہے۔ آپ نےفرمایا:پھر دوماہ کے روزے رکھو۔ اس نے کہا: میں اس کی بھی طاقت نہیں رکھتا۔ تو آپ نے فرمایا: تب ساٹھ غریبوں کو کھانا کھلاؤ۔اس نے کہا:میرے پاس اتنی بھی دولت نہیں ہے۔ اسی درمیان ایک شخص نبی اکرم صلی اللہ علیہ وسلم کی خدمت میں سات کلو کھجور لے کر آیا تو آپ نے اس سے فرمایا: یہ لو اور غریبوں کو اپنی طرف سے کھلادو۔اس نے کہا:اے اللہ کے رسول! ان دونوں پہاڑوں کے درمیان کوئی ایسا گھر نہیں ہے جو مجھ سے زیادہ غریب ہو۔آپ ہنس پڑے یہاں تک آپ کے داڑھ کھل گئے۔ آپ نےفرمایا:لے جاؤ اپنے ہی گھر والوں کو کھلا دو\"۔ (صحیح البخاری: ۱۹۳۶، وصحیح مسلم: ۱۱۱۱/۸۱)۔\nیہ کفارہ صرف شوہر پر ہوگا۔ کیوں کہ تعلق اس نے اپنی خواہش سے کیا، نہ کہ بیوی کی خواہش سے۔\nاس حدیث سے جہاں رمضان میں روزے کی حالت میں جنسی تعلق قائم کرنے کے کفارے کا پتا چلتا ہے،وہیں نبی اکرم صلی اللہ علیہ وسلم کے اچھے برتاؤ کا بھی پتا چلتاہے کہ آپ حقیقت میں رحمۃ للعالمین (دنیا کے لیے رحمت ) بناکر بھیجے گئے تھے۔","",{}],[512,"§کلب\nکلب کواردو میں کتاکہتے ہیں۔ اس کی جمع کلاب ہے۔کتاایک نجس اور آوارہ جانور ہے، جو آبادی میں چلتا پھرتا اور مردہ جانور تک کھا لیتا ہے۔ اس لیے آسمانی کتابوں میں اسے کھانا حرام ٹھہرایا گیاہے۔\nکتے کے اندر کچھ ایسی خصوصیات بھی ہیں، جو دوسرے جانوروں میں نہیں پائی جاتیں۔ جیسے: یہ اپنے مالک کا وفادار ہوتاہے۔اس لیے جب اصحاب کہف پہاڑ کے غار میں چھپنے چلے گئے تو اس کے ساتھ ان کا کتا بھی تھا، جیسا کہ قرآن مجیدمیں آیا ہے: ﴿وَتَحۡسَبُهُمۡ أَيۡقَاظࣰ ا وَهُمۡ رُقُودࣱۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَٰسِطࣱ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ﴾ [الکهف: ۱۸] \"تم(انھیں دیکھ کر) سمجھتے کہ وہ جاگ رہے ہیں جب کہ وہ سو رہے ہوتے۔ ہم انھیں دائیں اور بائیں کروٹ دلاتے رہتے اور ان کا کتا چوکھٹ پر اپنے دونوں بازو پھیلا ہوے ہوتا\"۔\nکہف والوں کی تعدادکے بارے میں اختلاف ہوگیا تو لوگ کہنے لگے:﴿سَيَقُولُونَ ثَلَٰثَةࣱ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةࣱ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةࣱ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ﴾ [الکهف: ۲۲] \"کچھ لوگ کہتے ہیں کہ وہ تین تھے، چوتھا ان کا کتا تھا اور کچھ لوگ کہتے ہیں کہ وہ پانچ تھے، چھٹا ان کا کتا تھا۔ یہ بغیر نشانہ دیکھے پتھر (اندھیرے میں تیر) چلانا ہے۔ کچھ لوگ یہ بھی کہیں گے کہ وہ سات تھے اور آٹھواں ان کا کتا تھا\"۔\nکتے کی اسی خصوصیت کی وجہ سے اسلام نے دو حالتوں میں اس کا پالنا جائز بتایا ہے۔\n۱- شکار کے لیے: اگرکتے کو شکار کے لیے سدھایا گیا ہواور اسے شکار کو شکاری تک لانے کی تعلیم دی گئی ہوتواس کا رکھناجائزہے۔قرآن مجیدمیں آیاہے: ﴿يَسۡـَٔلُونَكَ مَاذَآ أُحِلَّ لَهُمۡۖ قُلۡ أُحِلَّ لَكُمُ ٱلطَّيِّبَٰتُ وَمَا عَلَّمۡتُم مِّنَ ٱلۡجَوَارِحِ مُكَلِّبِينَ تُعَلِّمُونَهُنَّ مِمَّا عَلَّمَكُمُ ٱللَّهُۖ فَكُلُواْ مِمَّآ أَمۡسَكۡنَ عَلَيۡكُمۡ وَٱذۡكُرُواْ ٱسۡمَ ٱللَّهِ عَلَيۡهِۖ﴾ [المائدة: ۴] \"وہ تم سے پوچھتے ہیں کہ ان کے لیے کون کون سی چیزیں حلال کی گئی ہیں؟ کہہ دو تمھارے لیے سبھی اچھی صحت بخش چیزیں حلال کی گئی ہیں اور وہ شکار بھی حلال ہے، جس کو تمھارے سدھائے ہوے شکاری جانوروں نے پکڑا ہو۔جنہیں تم اسی طرح سکھاتے ہو جیسے اللہ نےتمھیں سکھایا ہے۔ تو انھوں نے تمھارے لیے جو شکار کیا، اسے کھاؤ اور اس پر اللہ کا نام لو\"۔\nشکار کے لیے تربیت دیے جانے والوں میں کچھ علما کے یہاں کتا بھی شامل ہے۔ تربیت دیے جانے کا مطلب ہے کہ جب اس کو شکار پر چھوڑا جائے تو دوڑ پڑے اور جب بلایا جائے تو واپس لوٹ آئے۔ ایسے سکھائے ہوے جانوروں کالایاہوا شکار دو صورتوں میں حلال ہے۔\nایک یہ کہ کتےکو شکارکے لیےچھوڑتے ہوےبسم اللہ پڑھاگیا ہو یعنی اللہ کا نام لیا گیا ہو، دوسرے یہ کہ وہ شکار کو اپنے مالک کے پاس لائے اور خود نہ کھانا شروع کردے۔ اب اگر وہ شکار مر بھی جائے تو اس کا کھانا حلال ہے، کیوں کہ اس کے تعلق سے شرط وہی ہے جو ذبیحہ کے تعلق سے ہے۔\nعدی بن حاتم رضی اللہ عنہ کہتے ہیں کہ میں نے رسول صلی اللہ علیہ وسلم سے عرض کیا:\" ہم لوگ شکاری قوم کے ہیں۔ ان کتوں کے ذریعے سے شکار کرتے ہیں، تو آپ نے فرمایا: اگر تم نے تربیت دیے ہوے کتے کو اللہ کے نام کے ساتھ شکار کرنے کے لیے چھوڑا،تو اس نے جو شکار کیا اس کو کھاؤ، چاہے وہ مر ہی کیوں نہ جائے۔ ہاں اگر شکاری کتے نے اس میں سے کچھ کھا لیا ہو، تب مت کھاؤ۔ کیوں کہ مجھے شک ہے کہ اس نے اپنے لیے شکارکیا ہے۔ اسی طرح کوئی اور کتا شکار کرنے میں اس کے ساتھ شامل ہوگیا ہو تب بھی نہ کھاؤ\"۔ (صحیح البخاری: ۵۴۸۳، وصحیح مسلم: ۱۹۲۹/۱)\n۲-کتے کو حفاظت کے مقصدسے رکھاگیاہو جیسے: اسے پالتو جانوروں کی حفاظت کے لیے استعمال کیا جائےتو ایک صحیح حدیث میں آیا ہے: عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَنْ اقْتَنَی کَلْبًا لَيْسَ بِکَلْبِ مَاشِيَةٍ أَوْ ضَارِيَةٍ نَقَصَ کُلَّ يَوْمٍ مِنْ عَمَلِهِ قِيرَاطَانِ». (صحیح البخاری: ۵۴۸۰، وصحیح مسلم: ۱۵۷۴/۵۰) \"جس نے کتے کو جانوروں کی حفاظت اور شکار کے علاوہ کسی اور مقصد سے پالا تو اس کے نیک اعمال میں سے ہردن دو قیراط گھٹ جائیں گے\"۔(قیراط وزن کرنے کا ایک پیمانہ ہے جو سونے کے تین گیہوں کے برابر ہوتا ہے۔)\nایک دوسری حدیث میں یہ بھی آیا ہے: \"اور کھیت کی رکھوالی کے لیے\"۔(صحیح مسلم)\nگھر کی رکھوالی کے لیے بھی کتا پالا جاسکتا ہے مگر اس کا گھر کے اندر آنا جانا نہیں ہونا چاہیے۔\nکتےکی ایک بری عادت کی طرف قرآن کریم میں اشارہ کیا گیا ہے، وہ اس کا لالچ اور اس کی حرص ہے۔وہ ہر دم اپنی ناک سے یہ سونگھتا پھرتا ہےکہ کہیں سے کچھ کھانے کے لیے مل جائے۔ اس کی دوسری عادت یہ ہے کہ اگر آپ اسے کچھ کھانے کو دیں تب بھی ہانپتا رہے گا اور نہ دیں تب بھی ہانپتا رہےگا۔کتے کی اسی عادت سے اللہ تعالیٰ اس انسان کی مثال دے رہا ہے، جس کو علم دیا، دنیا بھرکی دولت عطا کی اور لوگوں میں عزت بخشی۔ ایسے انسان کے لیے یہ لازم تھا کہ سچ کو جانتا اور اس کو اختیار کرتا۔ لیکن اس نے ایسا نہیں کیا، بلکہ دولت مندی، مالداری اور علم کے زعم میں اللہ تعالیٰ کی مخالفت کر بیٹھا۔ایسے آدمی کی مثال کتے جیسی ہے، جسے کچھ دو تب بھی ہانپتا ہے اور نہ دو تب بھی زبان کھول کر ہانپتا ہے:﴿وَٱتۡلُ عَلَيۡهِمۡ نَبَأَ ٱلَّذِيٓ ءَاتَيۡنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنۡهَا فَأَتۡبَعَهُ ٱلشَّيۡطَٰنُ فَكَانَ مِنَ ٱلۡغَاوِينَ وَلَوۡ شِئۡنَا لَرَفَعۡنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخۡلَدَ إِلَى ٱلۡأَرۡضِ وَٱتَّبَعَ هَوَىٰهُۚ فَمَثَلُهُۥ كَمَثَلِ ٱلۡكَلۡبِ إِن تَحۡمِلۡ عَلَيۡهِ يَلۡهَثۡ أَوۡ تَتۡرُكۡهُ يَلۡهَثۚ ذَّٰلِكَ مَثَلُ ٱلۡقَوۡمِ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۚ﴾ [الأعراف: ۱۷۵-۱۷۶] \"انھیں اس انسان کا حال پڑھ کر سناؤ جسے ہم نے اپنی نشانیاں دی تھیں، لیکن وہ ان سے نکل بھاگا۔ پھر شیطان اس کے پیچھے لگ گیا اور وہ گمراہوں میں سے ہوگیا اور اگر ہم چاہتے تو ان آیتوں کے ذریعے سے اسے عظمت عطا کر دیتے۔ لیکن وہ تو دنیا کا ہوکر رہ گیا اور اپنی خواہشات کی تکمیل میں لگ گیا، تو اس کی مثال ایک کتے جیسی ہے۔ اگر اس پر رحم کرو تب بھی وہ ہانپتا ہے اور نہ کرو تب بھی وہ ہانپتا ہے۔ یہی مثال ان لوگوں کی ہے جنھوں نے ہماری آیتوں کو جھٹلایا\"۔\nاگر کتےآبادی کے لیے پریشانی کا سبب بن جائیں تو انسانوں کی حفاظت کے لیے ان کو قتل کر دینا جائزہے۔ کیوں کہ پاگل کتوں کی رال میں زہر آجاتا ہے اور اگر وہ کسی کو کاٹ لیں تو اس کی موت واقع ہوسکتی ہے۔\nاسلام کے یہ سبھی قواعداور قوانین انسانوں کے فائدے اور ان کی حفاظت کے لیے بنائے گئے ہیں، وقتاً فوقتاً جن کی مثالیں ملتی رہتی ہیں۔","",{}],[513,"§کلمہ (مکالمہ)\nقرآن مجیدمیں اہل کتاب سے مشترک دینی عقائدکے بارے میں باہمی بات چیت کی دعوت دی گئی ہےاوریہ کہا گیاہے کہ اس کلمہ یامسئلےکی طرف جوہم مسلمانوں اورتم اہل کتاب کے مابین متفق علیہ بات ہے: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةࣲ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـࣰٔ ا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابࣰ ا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ﴾ [آل عمران: ۶۴] \"کہو: اے اہل کتاب جوچیز ہمارے اور تمھارے درمیان عام طور پربرابر ہےاس کی طرف آؤ۔ وہ یہ کہ ہم اللہ تعالیٰ کے سوا کسی کی عبادت (بندگی) نہ کریں اور نہ اس کے ساتھ کسی کو شریک ٹھہرائیں اور نہ ہم میں سے کوئی ایک دوسرے کو اللہ تعالیٰ کےسوا رب بنائے۔ پھر اگر وہ اس سے منہ موڑیں توکہدو:گواہ رہنا ہم تو مسلم (فرماں بردار) ہیں\"۔\nکسی کورب اورمعبود نہ بنانے کا مطلب ہے کہ اللہ تعالیٰ کے سوا کسی کو حلال اور حرام کرنے کا اختیار نہیں جیسا کہ عیسائیوں نے اپنے علماءکو بنا رکھا تھا: ﴿ٱتَّخَذُوٓاْ أَحۡبَارَهُمۡ وَرُهۡبَٰنَهُمۡ أَرۡبَابࣰ ا مِّن دُونِ ٱللَّهِ وَٱلۡمَسِيحَ ٱبۡنَ مَرۡيَمَ وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُوٓاْ إِلَٰهࣰ ا وَٰحِدࣰ اۖ لَّآ إِلَٰهَ إِلَّا هُوَۚ سُبۡحَٰنَهُۥ عَمَّا يُشۡرِكُونَ﴾ [التوبة: ۳۱] \"انھوں نے اللہ کے سوا اپنے مذہبی رہنماؤں اوردرویشوں اور مریم کے بیٹے مسیح کو اپنا رب (معبود) بنا لیاتھا جب ان کو اس کے سوا کوئی حکم نہیں دیا گیا تھا کہ تنہا الٰہ (معبود) کی ہی بندگی (عبادت) کریں جس کے سوا کوئی اور عبادت کے لائق نہیں۔اس کی عظمت کے برخلاف ہے جو یہ شرک کرتے ہیں\"۔\nکبھی کبھی ایسا ہوتا ہے کہ واضح چیز بھی سمجھ میں نہیں آتی۔ اس میں انسان کے اپنے دماغی ٹیڑھ پن کا دخل ہوتا ہے۔ لیکن اسلام ایسی صورت میں بھی نہ سختی کا حکم دیتا اور نہ زور زبردستی کرتا ہے۔ بلکہ مقابل کی کج بحثی کی صورت میں اس سے اچھے ڈھنگ سے بحث ومباحثے کی تعلیم دیتاہے، چنانچہ دعوت کےمختلف مراحل کے بارے میں قرآن مجیدیوں ہدایت دیتاہے: ﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ﴾ [النحل: ۱۲۵] \"حکمت اور موعظت کے ساتھ اپنے رب کی طرف بلاؤ اور ان سے صحیح طریقے سے گفتگو کرو۔بےشک تمھارا رب اس بات کو اچھی طرح جانتا ہے کہ کون اس کی راہ سے بھٹک گیا اور وہ راہ پانے والوں کو بھی اچھی طرح جانتا ہے\"۔\nاسلام کی دعوت قبول کرنے کا معاملہ زوروزبردستی کا نہیں ہے، بل کہ دل ودماغ کےاطمینان کے بعد آدمی اس کےقبول کرنے میں آزادہے۔ اسی بات کا اعلان قرآن مجید میں آیاہے:﴿لَآ إِكۡرَاهَ فِي ٱلدِّينِۖ قَد تَّبَيَّنَ ٱلرُّشۡدُ مِنَ ٱلۡغَيِّۚ فَمَن يَكۡفُرۡ بِٱلطَّٰغُوتِ وَيُؤۡمِنۢ بِٱللَّهِ فَقَدِ ٱسۡتَمۡسَكَ بِٱلۡعُرۡوَةِ ٱلۡوُثۡقَىٰ لَا ٱنفِصَامَ لَهَاۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ﴾ [البقرة: ۲۵۶] \"دین کے بارے میں کوئی زور زبردستی نہیں، ہدایت ضلالت اور جھوٹ سے الگ ہوگئی ہے، اس لیے جو طاغوت کو ٹھکراکر اللہ تعالیٰ پر ایمان لائے اس نے مضبوط سہارا تھام لیا جو کبھی ٹوٹنے والا نہیں۔ اللہ تعالیٰ سمیع وعلیم ( سننے والا اور جاننے والا) ہے\"۔\nان آیات پرغورکرنے سے پتاچلتاہےکہ اسلام سنجیدہ بحث ومباحثہ کاقائل ہے۔مختلف مذاہب والوں کےسامنے دعوت پیش کرنے کا ضابطہ بھی بتادیاگیاہے۔نبی اکرم صلی اللہ علیہ وسلم کی دعوتی زندگی اور آپ کا اسلوب دعوت بھی ہمارے سامنےہے۔مختلف مذاہب کے درمیان اگر گفتگو ہوتو اس کے لیے ضروری ہے کہ ان شرائط کو سامنے رکھیں :\n۱- اللہ جو سب کا رب اورخالق ومالک ہےاورجس کے بارے میں اقوام وملل میں کوئی اختلاف بھی نہیں ہے، صرف اسی کی عبادت اوراس کے ساتھ کسی کو شریک نہ ٹھہرایےجانےکی بات پیش رہنی چاہیے۔قرآن مجیدمیں اللہ تعالیٰ نے بے شمارجگہ اپنی ربوبیت وقدرت کودلیل بناکرانسانوں کو صرف اپنی عبادت کی دعوت دی ہےاورہرطرح کے شرک سے منع کیاہے۔اہل کتاب سے خطاب میں اسی باہمی مشترک بات کی دعوت ہے، جوانبیاکی دعوت کا خلاصہ ہے۔اللہ تعالیٰ نے انس وجن کی پیدایش بھی صرف اپنی عبادت کے لیے کی ہے۔عبادت کے ساتھ شرک کی ہر صورت کو سختی سے منع کیاہے۔\n۲- دین کے قبول کرنے کےمعاملےمیں زبردستی نہ کی جائے۔\n۳-دنیامیں بہت سارے مذہب اورعقیدے کے لوگ ہیں، اس لیے اس بات کی احتیاط ہونی چاہیے کہ ہم مذہبی بات چیت میں ایسااسلوب اختیارکریں،جس سے سامنے والے کو تکلیف پہنچے۔اسلام نے اپنے ماننے والوں کو اس بارے میں واضح پیغام دے رکھا ہے:﴿وَلَا تَسُبُّواْ ٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّواْ ٱللَّهَ عَدۡوَۢا بِغَيۡرِ عِلۡمࣲۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ ثُمَّ إِلَىٰ رَبِّهِم مَّرۡجِعُهُمۡ فَيُنَبِّئُهُم بِمَا كَانُواْ يَعۡمَلُونَ﴾ [الأنعام: ۱۰۸] \"اور گالی مت دو ان کو جن کی یہ لوگ اللہ تعالیٰ کو چھوڑ کر عبادت کرتے ہیں کیونکہ پھر وہ جاہلانہ ضدسے گزر کر اللہ تعالیٰ کی شان میں گستاخی کریں گے۔ہم نے اسی طرح ہر طریقہ والوں کو ان کا عمل مرغوب بنا رکھا ہے۔ پھر اپنے رب ہی کے پاس ان کو جانا ہے سو وہ ان کو بتلا دےگا جو کچھ بھی کیا کرتے تھے\"۔\n۴-غیرمسلموں سے اپنےمذہب کی تبلیغ میں صرف وہی طریقہ استعمال کرنا چاہیے جو کتاب وسنت کی تعلیمات سےثابت ہو۔ظاہر بات ہے کہ اسلام کی حقانیت کو واضح کرنے میں دوسرے مذاہب کے غلط یا منسوخ اعتقادات اور تعلیمات پربھی تنقیدہوگی،لیکن یہ تنقیدحقیقت واقعہ کے اظہاراور عقلی دلائل کی روشنی میں ہونی چاہیے۔اگرباہمی گفتگوسے اگر کوئی فائدہ نہیں ہوتا تو بھی باہمی تعلقات، رواداری اوردنیوی معاملات میں کوئی رکاوٹ نہیں ہونی چاہیے۔ سب کو مل کر ایک اچھے معاشرے کی بنیادرکھنی چاہیے، جس میں امن اور فیصلے کا بول بالا ہو۔کوئی کسی سے خوف زدہ نہ ہو، روزی حاصل کرنے کا سب کو حق ہو یہی اسلام کی تعلیم ہے۔","",{}],[514,"§کوا\nدیکھیے: غراب","",{}],[515,"§کہف غار والے\nدیکھیے: اصحاب کہف","",{}],[516,"§کہيعص\nدیکھیے: الم","",{}],[517,"§کیڑا\nدیکھیے: دابۃ الارض(گھن کا کیڑا)","",{}],[518,"§کینہ\nدیکھیے: حسد","",{}],[519,"§گائے\nدیکھیے: بقرہ","",{}],[520,"§گدھ\nدیکھیے: نسر","",{}],[521,"§گدها\nدیکھیے: حمار","",{}],[522,"§گرجاگھر\nدیکھیے: بِيع","",{}],[523,"§گناہ کبيرہ\nدیکھیے: کبیرہ، کبائر","",{}],[524,"§گھمنڈ\nدیکھیے: تکبر","",{}],[525,"§گھن\nدیکھیے: دابۃ الارض","",{}],[526,"§گھن کا کیڑا\nدیکھیے: دابۃ الارض","",{}],[527,"§لات\nقرآن کریم میں تین بتوں کے نام آئے ہیں، جن کی اسلام سے پہلےزمانۂ جاہلیت میں عرب پوجا کرتے تھے۔ ارشادباری تعالیٰ ہے:﴿أَفَرَءَيۡتُمُ ٱللَّٰتَ وَٱلۡعُزَّىٰ وَمَنَوٰةَ ٱلثَّالِثَةَ ٱلۡأُخۡرَىٰٓ أَلَكُمُ ٱلذَّكَرُ وَلَهُ ٱلۡأُنثَىٰ تِلۡكَ إِذࣰ ا قِسۡمَةࣱ ضِيزَىٰٓ إِنۡ هِيَ إِلَّآ أَسۡمَآءࣱ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّآ أَنزَلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنࣲۚ﴾ [النجم: ۱۹-۲۳] \"کیا تم نے لات اور عزیٰ کو دیکھا؟ اور تیسری(دیوی) منات کی حقیقت پر غور کیا؟ کیا بیٹے تمھارے لیے اور اللہ کے لیے بیٹیاں؟ تب تو بہت بے ڈھنگی اور غیر منصفانہ تقسیم ہوئی۔ حقیقت میں یہ تو صرف نام ہیں، جو تم اور تمھارے اگلوں نے رکھ لیے ہیں۔اللہ نے تو ان کے لیے کوئی ثبوت نہیں اتارا\"۔\nان تین دیویوں میں پہلی لات ہے جسے وہ(معاذ اللہ) اللہ کی بیوی یا بیٹی کہتے تھے۔ حقیقت میں یہ ایک سفید پتھر تھا،جس پر مختلف اقسام کی تصویریں کھودی گئی تھیں۔یہ طائف شہر کے ایک گھر میں رکھا ہوا تھا۔ اس پر چادریں چڑھائی جاتی تھیں۔اس کے پجاری اس کے چاروں طرف بیٹھے رہتے تھے۔ گھر کےچاروں طرف ایک بڑا میدان تھا، جہاں لوگ آکر اس کی زیارت کرتے تھے اور کعبہ کی طرح اس کا بھی طواف کرتے تھے۔ اس کے ماننے والےقریش کو چھوڑکر سارے عربوں پر اپنا اقتدار جتاتے تھے۔\nیاقوت حموی کی رائے ہے کہ لات بنوثقیف کے ایک شخص کا نام تھا۔جو بڑا بہادر اور نڈر تھا۔ جب وہ مرگیا تو لوگوں نے یہ مشہور کردیا کہ اس کی روح ایک متبرک جگہ کی سیرکررہی تھی اور اب اس جگہ کو اس نے اپنی جاے قیام بنالی ہے۔پھر لوگوں نے وہاں ایک پتھر کا بت بنا کر رکھ دیا۔ شروع میں تو سب اس کی عبادت کرتے رہے،۔پھر یہ صرف قبیلۂ ہوزان کا بت رہ گیا۔یہ بھی کہا گیا ہے کہ وہ شخص کعبہ کی زیارت کرنے والوں کو ستو گھول گھول کر پلایاکرتا تھا۔ اس لیے اس کی بڑی عزت کی جاتی تھی۔ عربی میں لات کے معنی ہی ستو گھولنے والے کے ہیں۔\nفتح مکہ کے بعدجب قبیلہ ثقیف نے اسلام قبول کرلیاتورسول اکرم صلی اللہ علیہ وسلم نےمغیربن شعبہ رضی اللہ عنہ کوبھیجا اورانھوں اسےمنہدم کرکے اس میں آگ لگادی،تاکہ ہمیشہ کے لیےوہاں سے بت پرستی ختم ہوجائے۔","",{}],[528,"§لباس\nلباس کو اردو میں کپڑابھی کہتے ہیں۔خود لباس کا لفظ اردو میں عام طور پر عربی ہی کے معنی میں مستعمل ہے۔اللہ تعالیٰ کی نعمتوں میں سے ایک نعمت لباس ہےکہ اس نے انسان کو لباس پہننا سکھایا اور لباس کا پہننا ہماری فطرت میں ڈال دیا۔ اسی لیے جب آدم اور ان کی بیوی حوّانے شیطان کے بہکاوے میں آکراس درخت کا مزہ چکھ لیا جس سے روکا گیا تھا تو ان کی شرم گاہیں ایک دوسرے کے سامنے کھل گئیں اور وہ دونوں اپنے اوپر جنت کے پتوں کو جوڑ جوڑ کر رکھنے لگے۔ (الاعراف: ۲۲، طہ:۱۲۱)\nاللہ تعالیٰ کی رحمتوں اورمہربانیوں میں سے ہے کہ اس نےزمین میں لباس بنانے کے وسائل پیدا کیے۔ ارشاد باری تعالیٰ ہے:﴿يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسࣰ ا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشࣰ اۖ﴾ [الأعراف: ۲۶] \"اے آدم کی اولاد! ہم نے تمھارے لیے لباس اتارا جو تمھاری شرمگاہ کو ڈھانک لیتا ہے اور حفظان وخوبصورتی کا ذریعہ ہوتا ہے\"۔\nیہاں لباس اتارنے کامطلب ہے وسائل پیدا کرنا۔ جیسے زمین سے کپاس اگانا۔ریشم کے کپڑوں سے ریشم بنانا۔ اب جو نئے نئے وسائل پیدا ہوتے جارہے ہیں وہ سب اسی معنی میں داخل ہیں۔ جنت میں بھی جنت والوں کولباس دیا جائے گا جو ریشم کا ہوگا۔(دیکھیے: الحج:۲۳)\n§لباس کے متعلق اسلام کی تعلیمات کا خلاصہ:\n(۱)اسلام میں کوئی مخصوص لباس نہیں ہے۔ بلکہ ہر ملک کے لوگ اپنے ملک کے رواج کے مطابق اور موسم کے اعتبار سے جومناسب لباس ہو اسے استعمال کر سکتے ہیں۔تاہم ضروری ہے کہ وہ لباس مرد کے بدن کو ناف سے لے کر گھٹنے تک ستر ڈھانکنے والا ہو اور عورت کے پورے بدن کو ڈھاکنے والا ہو۔ سوائے چہرے، ہاتھ اور پاؤں کے۔\n(۲)مردکے لیے ٹخنے سے نیچےکوئی لباس نہیں ہونا چاہیے۔ابوہریرہ رضی اللہ عنہ کہتےہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَا أَسْفَلَ مِنْ الْکَعْبَيْنِ مِنْ الإِزَارِ فَفِي النَّارِ». (صحیح البخاری: ۵۷۸۷) \"جس کا لباس ٹخنے سے نیچے ہوگا اس کا وہ حصہ جہنم میں ہوگا\"۔\n(۳)لباس ایسا ہو جس میں تکبراورگھمنڈ نہ پیداہو۔عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نےفرمایا: «لايَنْظُرُ اللَّهُ إِلَی مَنْ جَرَّ ثَوْبَهُ خُيَلاءَ». (صحیح البخاری: ۵۷۸۳، صحیح مسلم: ۲۰۸۵/۴۲) \"جو شخص کپڑوں کو تکبرکے ساتھ زمین پر گھسیٹتا پھرے گا۔ قیامت کے دن اللہ اس کی طرف نہیں دیکھے گا\"۔\n(۴)مردوں کے لیے ریشمی لباس پہننا حرام ہے۔ ایک صحیح حدیث میں مردوں کو مخاطب کرتے ہوےنبی اکرم صلی اللہ علیہ وسلم نےفرمایا: «مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الآخِرَةِ». (صحیح البخاری: ۵۸۳۴، وصحیح مسلم :۲۰۶۹/۱۱بروایت عمر رضی اللہ عنہ ) \"ریشمی لباس نہ پہنو۔ جس نے اسے دنیا میں پہنا وہ جنت میں نہیں پہن پائے گا\"۔\n(۵) عورت ومرد کے لباس میں مشابہت نہیں ہونی چاہیے۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: «لَعَنَ رَسُولُ اللَّهِ صلی اللہ علیہ وسلم الْمُتَشَبِّهِينَ مِنْ الرِّجَالِ بِالنِّسَاءِ وَالْمُتَشَبِّهَاتِ مِنْ النِّسَاءِ بِالرِّجَالِ». (صحیح البخاری: ۵۸۸۵) \"نبی اکرم صلی اللہ علیہ وسلم نےان مردوں پر لعنت بھیجی ہے جو عورتوں کا لباس پہنتے ہیں۔ اسی طرح ان عورتوں پر بھی لعنت بھیجی ہے جو مردوں کا لباس پہنتی ہیں\"۔\n(۶) سفید لباس زیادہ پسندیدہ ہے۔ عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «الْبَسُوا مِنْ ثِيَابِکُمُ الْبَيَاضَ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِکُمْ، وَکَفِّنُوا فِيهَا مَوْتَاکُمْ». (سنن ابی داود: ۳۸۷۸) \"سفید لباس پہنا کرو جو عمدہ ہے اور اسی میں اپنے مردوں کودفن کرو\"۔\n(۷)ایسےشفاف اورباریک کپڑےاستعمال کرنامنع ہے،جس سےجسم کے اعضانظرآئیں۔ ابوہریرہ رضی اللہ عنہ سے مروی حدیث میں نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «نِسَاءٌ کَاسِيَاتٌ عَارِيَاتٌ مُمِيلاتٌ مَائِلاتٌ رُءُوسُهُنَّ کَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ لا يَدْخُلْنَ الْجَنَّةَ وَلا يَجِدْنَ رِيحَهَا وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ کَذَا وَکَذَا». (صحیح مسلم: ۱۲۵/۲۱۲۸) \"وہ عورتیں جو ایسا لباس پہنتی ہیں، جس میں عریانیت ہو، جنت میں نہیں جاسکتیں۔ جب کہ اس کی خوشبو بہت دور سے آتی ہے\"۔\n(۸) باہرنکلتے وقت عورتوں کو پردے سے نکلناواجب ہے۔جیساکہ قرآن مجید کی ہدایت ہے: عورتیں باہر نکلتے وقت اپنی چادروں کے پلّو لٹکا لیا کریں۔(دیکھیں: سورہ الاحزاب:۵۹)\n(۹)عورتیں اپنے بناؤ سنگار کو چھپائے رکھیں۔ کسی پر ظاہر نہ ہونے دیں، سوائے ان لوگوں کے جن کاذکرسورہ النور(آیت: ۳۱) میں آیا ہے اور وہ یہ ہیں: شوہر، باپ، شوہر کے باپ، اپنے بیٹے، شوہر کے بیٹے، بھائی، بھائیوں کے بیٹے، بہنوں کے بیٹے، اپنی جیسی عورتیں (جیسے سہیلیاں یا دائیاں ) اپنے غلام، ماتحت مرد(جیسے نوکر) جو اس حالت کو پار کرچکےہوں جس میں عورتوں کی ضرورت ہوتی ہے، وہ بچے جو عورتوں کے پوشیدہ امور سے متعارف نہ ہوں۔ ان لوگوں کےسامنے بناؤ سنگار کے اظہار میں کوئی حرج نہیں ہے۔\n(۱۰)اس لباس کے ساتھ عورت مرد دونوں کو آنکھیں نیچی رکھنے کا حکم دیا گیا ہے۔ ٹک ٹکی باندھ کر اور غورسےایک دوسرے کودیکھناناجائزاورنا مناسب فعل ہے۔ ارشادباری تعالیٰ ہے: ﴿قُل لِّلۡمُؤۡمِنِينَ يَغُضُّواْ مِنۡ أَبۡصَٰرِهِمۡ وَيَحۡفَظُواْ فُرُوجَهُمۡۚ ذَٰلِكَ أَزۡكَىٰ لَهُمۡۚ إِنَّ ٱللَّهَ خَبِيرُۢ بِمَا يَصۡنَعُونَ وَقُل لِّلۡمُؤۡمِنَٰتِ يَغۡضُضۡنَ مِنۡ أَبۡصَٰرِهِنَّ وَيَحۡفَظۡنَ فُرُوجَهُنَّ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنۡهَاۖ وَلۡيَضۡرِبۡنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّۖ وَلَا يُبۡدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوۡ ءَابَآئِهِنَّ أَوۡ ءَابَآءِ بُعُولَتِهِنَّ أَوۡ أَبۡنَآئِهِنَّ أَوۡ أَبۡنَآءِ بُعُولَتِهِنَّ أَوۡ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ إِخۡوَٰنِهِنَّ أَوۡ بَنِيٓ أَخَوَٰتِهِنَّ أَوۡ نِسَآئِهِنَّ أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُهُنَّ أَوِ ٱلتَّٰبِعِينَ غَيۡرِ أُوْلِي ٱلۡإِرۡبَةِ مِنَ ٱلرِّجَالِ أَوِ ٱلطِّفۡلِ ٱلَّذِينَ لَمۡ يَظۡهَرُواْ عَلَىٰ عَوۡرَٰتِ ٱلنِّسَآءِۖ وَلَا يَضۡرِبۡنَ بِأَرۡجُلِهِنَّ لِيُعۡلَمَ مَا يُخۡفِينَ مِن زِينَتِهِنَّۚ وَتُوبُوٓاْ إِلَى ٱللَّهِ جَمِيعًا أَيُّهَ ٱلۡمُؤۡمِنُونَ لَعَلَّكُمۡ تُفۡلِحُونَ﴾ [النور: ۳۰-۳۱] \"اے نبی! ایمان والے مردوں سے کہو کہ وہ اپنی نگاہیں نیچی رکھیں اور اپنی شرمگاہوں کی حفاظت کریں۔یہ ان کے لیے بہت اچھی بات ہے۔ یقیناً اللہ اس کی خبر رکھتا ہے، جو کچھ وہ کرتے ہیں اوراے نبی! ایمان والی عورتوں سے کہو کہ وہ نگاہوں کو نیچی رکھیں اور اپنی شرم گاہوں کی حفاظت کریں اور اپنی زینت کو نہ ظاہر کریں، مگر جو خود سے ظاہر ہوجائے(جیسے لباس کی زینت) اوروہ اپنی چادریں اپنے گریبانوں پر ڈال لیا کریں اوراپنی زینت اپنے شوہروں،اپنے باپوں،اپنے شوہروں کے باپوں،اپنے بیٹوں،اپنے شوہروں کےبیٹوں، اپنے بھائیوں، اپنے بھائیوں کے بیٹوں،اپنی بہنوں کے بیٹوں، اپنے گھر کی عورتوں، اپنے غلام باندیاں یا مردوں میں سے اپنے تابع (نوکروں)یا ایسے لڑکے جو عورتوں کے پوشیدہ معاملات سے ابھی واقف نہ ہوئے ہوں ان کے سوا اور کسی کے لیے ظاہر نہ کریں۔ اپنے پاؤوں کو اس طرح نہ پٹکیں کہ ان کی پوشیدہ زنیت (زیور) کو لوگ جان لیں۔ لوگو! تم سب اللہ سے توبہ کرو تاکہ تم کامیاب ہو جاؤ\"۔\n(۱۱)اگر کسی کی نگاہ کسی اجنبی پر پڑجائے تو اس کو چاہیے کہ فوراً نگاہ پھیر لے۔ (دیکھیں صحیح مسلم:۲۱۵۹)\n(۱۲) عورتیں محرم کے ساتھ سفرکریں، تنہا سفر نہ کریں: عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «لا تُسَافِرْ الْمَرْأَةُ إِلا مَعَ ذِي مَحْرَمٍ وَلا يَدْخُلُ عَلَيْهَا رَجُلٌ إِلا وَمَعَهَا مَحْرَمٌ». (صحیح البخاری:۱۸۶۲، وصحیح مسلم:۱۳۴۱/۴۲۴). \"کوئی عورت بغیر محرم (یا شوہر) کے سفر نہ کرے۔ کسی ایسی عورت کے ساتھ تنہائی میں نہیں رہنا چاہیے۔ جس کے ساتھ اس کا کوئی محرم(جیسے باپ، بھائی وغیرہ) نہ ہو\"۔\nعقبہ بن عامر رضی اللہ عنہ کہتےہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «إِيَّاکُمْ وَالدُّخُولَ عَلَی النِّسَاءِ فَقَالَ رَجُلٌ مِنْ الأَنْصَارِ يَا رَسُولَ اللَّهِ أَفَرَأَيْتَ الْحَمْوَ قَالَ: الْحَمْوُ الْمَوْتُ». (صحیح البخاری: ۵۲۳۲، صحیح مسلم: ۲۱۷۲/۲۰) \"(نامحرم) عورتوں کے ساتھ تنہائی میں نہ رہو، ایک آدمی نے عرض کیا: اللہ کے رسول!دیور کے بارے میں آپ کا کیا خیال ہے؟آپ نے فرمایا: دیور تو موت ہے\")(یہ دونوں فقرےکسی اورلفظ میں جائیں گے)","",{}],[529,"§لبن\nلبن دودھ کو کہتے ہیں۔ اس کا ذکر قرآن مجیدمیں دو جگہ پر آیا ہے:\n۱-﴿وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةࣰۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثࣲ وَدَمࣲ لَّبَنًا خَالِصࣰ ا سَآئِغࣰ ا لِّلشَّٰرِبِينَ﴾ [النحل: ۶۶] \"تمھارے لیے چوپایوں میں بھی عبرت (اور نشانی) ہے کہ ہم تمہیں ان کے پیٹ میں جو کچھ ہے، اسی میں سے گوبر اور خون کے درمیان سے خالص دودھ پلاتے ہیں، جو پینے والوں کے لئے سہتا پچتا ہے\"۔\n۲-﴿مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرࣱ مِّن مَّآءٍ غَيۡرِ ءَاسِنࣲ وَأَنۡهَٰرࣱ مِّن لَّبَنࣲ لَّمۡ يَتَغَيَّرۡ طَعۡمُهُۥ وَأَنۡهَٰرࣱ مِّنۡ خَمۡرࣲ لَّذَّةࣲ لِّلشَّٰرِبِينَ وَأَنۡهَٰرࣱ مِّنۡ عَسَلࣲ مُّصَفࣰّ ىۖ وَلَهُمۡ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةࣱ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدࣱ فِي ٱلنَّارِ وَسُقُواْ مَآءً حَمِيمࣰ ا فَقَطَّعَ أَمۡعَآءَهُمۡ﴾ [محمد: ۱۵] \"جنت جس کا پرہیزگاروں سے وعدہ کیا جاتا ہے۔ اس کی صفت یہ ہےکہ اس میں پانی کی نہریں ہیں جوپانی بدبو نہیں کرے گا۔ اور دودھ کی نہریں ہیں جس کا مزہ نہیں بدلے گا۔ اور شراب کی نہریں ہیں جو پینے والوں کے لیے (سراسر) لذت ہے اور شہد مصفا کی نہریں ہیں (جو حلاوت ہی حلاوت ہے) اور (وہاں) ان کے لیے ہر قسم کے میوے ہیں اور ان کےرب کی طرف سے مغفرت ہے۔ (کیا یہ پرہیزگار) ان کی طرح (ہوسکتے) ہیں جو ہمیشہ جہنم میں رہیں گے اور جن کو کھولتا ہوا پانی پلایا جائے گا تو ان کی انتڑیوں کو کاٹ ڈالے گا\"۔","",{}],[530,"§لسان عربی\nدیکھیے: عربی زبان","",{}],[531,"§لطیف\nدیکھیے: اسماےحسنی","",{}],[532,"§لعان\nلعان لعنت سے ہےاورلعنت کےمعنی رسوا کرنا، دھتکارنا، خیرسے دورکرنا،وغیرہ ہے۔میاں بیوی ایک دوسرے پر زناکاری کا الزام لگائیں، لیکن دونوں میں سے کسی کے پاس اس پر یقینی دلیل نہ ہو اور دونوں اپنے اوپر عائدالزام کا انکارکرے یامردپیدا ہونے والے بچے کے بارے میں کہہ دے کہ یہ میرا بچہ نہیں ہے اورعورت اس کے اس دعوے کو تسلیم نہ کرے تو ایسی صورت میں دونوں ایک دوسرے پر لعنت بھیج کراس مسئلے کا تصفیہ کریں گے۔ اسی کو شرعی اصطلاح میں لعان کہتے ہیں۔جس کاذکر قرآن مجیدمیں اس طرح آیا ہے:﴿وَٱلَّذِينَ يَرۡمُونَ أَزۡوَٰجَهُمۡ وَلَمۡ يَكُن لَّهُمۡ شُهَدَآءُ إِلَّآ أَنفُسُهُمۡ فَشَهَٰدَةُ أَحَدِهِمۡ أَرۡبَعُ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلصَّٰدِقِينَ وَٱلۡخَٰمِسَةُ أَنَّ لَعۡنَتَ ٱللَّهِ عَلَيۡهِ إِن كَانَ مِنَ ٱلۡكَٰذِبِينَ وَيَدۡرَؤُاْ عَنۡهَا ٱلۡعَذَابَ أَن تَشۡهَدَ أَرۡبَعَ شَهَٰدَٰتِۭ بِٱللَّهِ إِنَّهُۥ لَمِنَ ٱلۡكَٰذِبِينَ وَٱلۡخَٰمِسَةَ أَنَّ غَضَبَ ٱللَّهِ عَلَيۡهَآ إِن كَانَ مِنَ ٱلصَّٰدِقِينَ﴾ [النور: ۶-۹] \"جولوگ اپنی بیویوں پر بدکاری کی تہمت لگائیں اور اان کےپاس خود اپنے سوا کوئی گواہ موجود نہ ہو، تو ان میں سے ایک (شوہر) چار بار اللہ کی قسم کھا کر یہ گواہی دے کہ وہ بالکل سچا ہے اور پانچویں بار یہ گواہی دے کہ اس پر اللہ کی لعنت ہو اگر وہ جھوٹوں میں سے ہو اور عورت سے سزا اس طرح دور کی جا سکتی ہے کہ وہ چار بار اللہ کی قسم کھا کر کہے: یقیناً اس کا شوہر جھوٹ بول رہا ہے اور پانچویں بار کہے کہ اس پر اللہ کا غضب ہو اگر اس کا شوہر سچ بول رہا ہو\"۔\nان آیتوں کا مطلب یہ ہے کہ چار گواہ نہ ہونے کی وجہ سےعورت سزا سے بچ جائے گی اور چونکہ شوہر نے اس کو اپنی آنکھوں سے بدکاری کرتے ہوے دیکھا ہے،اس لیے دونوں لعان کریں گے اور وہ قذف کی سزا سے بچ جائے گا۔ لیکن ایسی صورت میں دونوں کا یکجا رہنا ناممکن ہے۔ اس لیے عدالت کے فیصلے کے مطابق دونوں میں ہمیشہ کے لیے تعلق توڑ دیا جائے گا۔ اس کو اسلام کی زبان میں لعان کہتے ہیں۔ کیونکہ دونوں ہی اپنے آپ کو جھوٹے ہونے کی صورت میں لعنت کا مستحق سمجھتے ہیں۔ جب کہ ان میں سے ایک لازماً جھوٹا ہوگا، جس پر پھٹکار اور لعنت ہوگی،۔ اسلام سے پہلے اور اسلام کے بعد آج تک اس معاملےمیں اس سے اچھا قانون نافذ نہیں کیا جاسکا۔","",{}],[533,"§لقمان\nلقمان کا ذکر قرآن مجیدمیں دو مرتبہ آیا ہے:\n۱-﴿وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدࣱ‏﴾ [لقمان: ۱۲] \"اور ہم نے لقمان کو حکمت عطا کی تاکہ وہ اللہ کا شکر گزار بن جائے اور جو کوئی شکر کرے گا وہ اپنے لیے ہی شکر کرے گا (اپنے لیے مفید پائے گا )اور جو کفر کرے تو حقیقت میں اللہ تعالیٰ بے نیاز اور خود ہی محمود ہے\"۔\n۲-﴿لِي وَلِوَٰلِدَيۡكَ إِلَيَّ ٱلۡمَصِيرُ وَإِن جَٰهَدَاكَ عَلَىٰٓ أَن تُشۡرِكَ بِي مَا لَيۡسَ لَكَ بِهِۦ عِلۡمࣱ فَلَا تُطِعۡهُمَاۖ وَصَاحِبۡهُمَا فِي ٱلدُّنۡيَا مَعۡرُوفࣰ اۖ وَٱتَّبِعۡ سَبِيلَ مَنۡ أَنَابَ إِلَيَّۚ ثُمَّ إِلَيَّ مَرۡجِعُكُمۡ فَأُنَبِّئُكُم بِمَا كُنتُمۡ تَعۡمَلُونَ يَٰبُنَيَّ إِنَّهَآ إِن تَكُ مِثۡقَالَ حَبَّةࣲ مِّنۡ خَرۡدَلࣲ فَتَكُن فِي صَخۡرَةࣲ أَوۡ فِي ٱلسَّمَٰوَٰتِ أَوۡ فِي ٱلۡأَرۡضِ يَأۡتِ بِهَا ٱللَّهُۚ إِنَّ ٱللَّهَ لَطِيفࣱ خَبِيرࣱ يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ وَلَا تُصَعِّرۡ خَدَّكَ لِلنَّاسِ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحࣰ اۖ إِنَّ ٱللَّهَ لَا يُحِبُّ كُلَّ مُخۡتَالࣲ فَخُورࣲ وَٱقۡصِدۡ فِي مَشۡيِكَ وَٱغۡضُضۡ مِن صَوۡتِكَۚ إِنَّ أَنكَرَ ٱلۡأَصۡوَٰتِ لَصَوۡتُ ٱلۡحَمِيرِ﴾ [لقمان: ۱۳-۱۹] \"اور (اے نبی وہ وقت یاد کریں ) جب لقمان نے اپنے بیٹے سے کہا: بیٹا اللہ تعالیٰ کاشریک کسی کو مت بنانا، کیوں کہ شرک بڑا(سخت ) گناہ ہے اور ہم نے آدمی کو اپنے ماں باپ کےلیے (اچھا سلوک کرنے کا ) حکم دیا، ماں نے تو اس کوتھک تھک کر (اپنے پیٹ میں)اٹھایا اور دو برس میں(کہیں) اس کا دودھ چھوٹا (ہم نے آدمی کو یہ حکم دیا ) کہ میرا شکر کرتا رہ اور اپنے ماں باپ کا، آخر تجھ کو (مرنے کے بعد) میرے پاس لوٹ کر آنا ہے۔ اور اگرتیرے ماں باپ زور زبردستی سے یہ کہیں کہ اللہ کےساتھ ان کو شریک کر جن کے شریک ہونے کی تیرے پاس کوئی سند نہیں، تو ان کا کہا مت مان اور دنیا میں ان کے ساتھ دستورکے موافق رہ اور (دین میں ) اس کی راہ پر چل جو میری طرف رجوع ہے۔ پھر میرے ہی پاس تم کو لوٹ کر آنا ہے، میں تم کو جو تم دنیا میں کرتے رہے (اس کا بدلہ دے کر) جتلا دوں گا، بیٹا اگر کوئی علم رائی کے دانے کے برابر ہو پھر (فرض کرو کہ) وہ (ساتوں زمینوں تلے) ایک پتھر پر ہو یا آسمان اور زمین میں (کہیں) ہو تو اللہ تعالیٰ(قیامت کے دن ) حاضر کرے گابےشک اللہ (بڑی )باریک نظر والا خبر دار ہے۔ بیٹا نماز کو درستی سے ادا کرتا رہ اور اچھی بات کرنے کاحکم کرتا رہ اوربری بات سے منع کرتا رہ اور جو آفت تجھ پرآن پڑے اس پر صبرکر۔بےشک یہ بڑےضروری کام ہیں اور لوگوں سے اپنے گال نہ پھلا اورزمین میں اتراتا(اکڑتا ) ہوا مت چل کیوں کہ اللہ تعالیٰ کسی اترانے (اکڑنے)والے شیخی خورےکوپسند نہیں کرتا اوربیچ کی چال چلا کر اوراپنی آواز آہستہ رکھ کیوں کہ گدھوں کی آواز (سب) آوازوں میں بری ہے\"۔\nلقمان یہ کوئی اپنے زمانے کے حکیم اورداناآدمی تھے۔جو توحید کےساتھ ساتھ حکمت و موعظت کی باتیں سنایا کرتے تھے۔جن کو عرب کے لوگ بھی جانتے تھے۔ لیکن صحیح تاریخ سے پتا نہیں چلتا کہ ان کی جائے پیدایش کیا تھی اور یہ کس قوم سے تھے، بعض آثار صحابہ و تابعین سے پتا چلتا ہے کہ یہ حبشی تھے اور کچھ کا خیال ہے کہ ان کا تعلق مصر کے جنوبی حصّے سے تھا،جس کو سوڈان کہتے ہیں۔البتہ اس بات پر جمہور اہل علم کا اتفاق ہے کہ یہ نبی نہیں تھے۔کیوں کہ انبیاے کرام سے متعلق آیات میں جو اسلوب تخاطب ہے وہ ان کے ساتھ نہیں ہے۔قرآن کریم کی اکتیسویں سورہ’سورہ لقمان‘ انھی کےنام سے ہے۔لقمان کی حکمتوں کا کچھ ذکر قرآن میں آگیا ہےاوربعض کا ذکر حدیثوں میں بھی ملتا ہے۔اس کے علاوہ ہمارے پاس کوئی ایسی مستند کتاب نہیں ہے جس میں لقمان کی حکمتوں کا ذکر ہو۔","",{}],[534,"§لہسن\nدیکھیے: ثوم","",{}],[535,"§لواقح\nلواقح: لاقح کی جمع ہے۔ریح لاقح ایسی ہوا کو کہتے ہیں، جس سے درخت باردارہوجائیں اوربارش لانے والی ہواؤں کو بھی لواقح کہتے ہیں۔قرآن کریم میں اس کا استعمال صرف ایک جگہ ہوا ہے: ﴿وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ﴾ [الحجر: ۲۲] \"اور ہم بھیجتے ہیں بوجھل ہوائیں۔ پھر آسمان سے پانی برسا کر وہ تمھیں پلاتے ہیں اور تم اس کا ذخیرہ کرنے والے نہیں ہو\"۔\nقرآن مجیدنےیہاں جس معنی میں اس لفظ کا استعمال کیا ہے وہ بہت بڑا معجزہ ہے۔ اس کی حقیقت کو آج ہم سائنس کی روشنی میں واضح طور پر سمجھ سکتے ہیں۔\nقرآن کریم میں پودوں کا ذکر بار بار آیا ہے۔لیکن جس معجزہ کی طرف قرآن کریم نے سب سے زیادہ اشارہ کیا ہے وہ پودوں کا جنسی ملاپ ہے،جس کو آج سائنسی تحقیق نےبڑی اہمیت کا حامل بتایا ہے۔ کیونکہ قرآن کے نزول کےوقت لوگوں کو اس سے زیادہ کوئی علم نہیں تھا کہ وہ کھجور کے درختوں میں تلقیح کریں،جس کی وجہ سےزیادہ پیداوار ہو۔تاہم آج کی سائنس نےیہ ثابت کردیا ہےکہ کھجوروں کے علاوہ بھی پودے مختلف قسم کےجنسی ملاپ سےگزرتے ہیں اور ہر پودے کااپنا جوڑا ہوتا ہے۔ جو تلقیح کےعمل سے گزرتا ہے۔ جن کو ہوائیں اڑا کر لے جاتی ہیں اور ان سے جسمانی ملاپ کرنے کےبعد پھول پتیاں یا پھل نکلنے شروع ہو جاتے ہیں۔\nقرآن کریم نے اس سائنسی حقیقت کی طرف بڑے واضح انداز میں اشارہ کردیا ہے:\n۱- ﴿سُبۡحَٰنَ ٱلَّذِي خَلَقَ ٱلۡأَزۡوَٰجَ كُلَّهَا مِمَّا تُنۢبِتُ ٱلۡأَرۡضُ وَمِنۡ أَنفُسِهِمۡ وَمِمَّا لَا يَعۡلَمُونَ﴾ [یس: ۳۶] \"پاک ہے وہ ذات جس نے سب کے جوڑے پیدا کیے،خواہ زمین جو چیزیں اگاتی ہے،ان میں سے بھی اور خواہ خود ان کے نفوس ہوں اور خواہ ان چیزوں میں سے ہوں جن کو تم نہیں جانتے\"۔\n۲-﴿وَمِن كُلِّ ٱلثَّمَرَٰتِ جَعَلَ فِيهَا زَوۡجَيۡنِ ٱثۡنَيۡنِۖ﴾ [الرعد: ۳] \"اور ہر ایک قسم کے پھلوں کی دودو قسمیں بنائیں\"۔\n۳- ﴿وَأَرۡسَلۡنَا ٱلرِّيَٰحَ لَوَٰقِحَ فَأَنزَلۡنَا مِنَ ٱلسَّمَآءِ مَآءࣰ فَأَسۡقَيۡنَٰكُمُوهُ وَمَآ أَنتُمۡ لَهُۥ بِخَٰزِنِينَ﴾ [الحجر: ۲۲] \"اور ہم ہی بارش لانے والی ہوائیں بھیجتے ہیں۔ پھر آسمان سے پانی برساکر وہ تمھیں پلاتے ہیں اور تم اس کا ذخیرہ کرنے والےنہیں ہو \"۔\nیعنی یہ ہوائیں پھولوں اور دوسرے پودوں کےجنسی ذرات(یعنی پھول کےدرمیان ننھےننھےذرات)کو لےکر اڑتی پھرتی ہیں اور جب کسی مادہ جاندارپودے کے رحم میں ڈال دیتی ہیں تو اس سے پھول پتیاں اور پودے نکل پڑتے ہیں۔یہ وہ معجزہ ہے جس کو قرآن ذکر کرکے بتانا چاہتا ہےکہ یہ سب کچھ اس رب کی عطا کردہ ہیں جس نے اس کائنات کوپیدا کیا۔ پس تمھیں چاہیے کہ تم اس پر ایمان لاؤ۔","",{}],[536,"§لوط علیہ السلام\nلوط علیہ السلام ابراہیم علیہ السلام کےبھائی حاران کےبیٹے تھے۔ وہ ابرہیم علیہ السلام کی نبوت پر ایمان لائے۔ ابھی وہ اپنے شہر اُرمیں ہی تھے کہ ان کے والد کی وفات ہوگئی اور ان کے دادا، ابراہیم علیہ السلام کے والدآذر نے ان کی دیکھ بھال کی ذمہ داری لے لی۔لیکن جب ابرہیم علیہ السلام نے اپنی دعوت کا آغاز کیا اور بتوں کی عبادت سےلوگوں کو منع کیا تو لوگوں نے ان کی شدت سے مخالفت کی۔ طرح طرح کی سزائیں دیں اور ان کو جان سے مار ڈالنے کی کوشش کی۔لیکن االلہرحیم و کریم نے انھیں محفوظ رکھااور ان کو ہجرت کا حکم دیا،اس لیےحکم الٰہی سےہجرت کرگئے۔ لوط علیہ السلام بھی ان کے ساتھ نکل پڑے۔ قرآن مجیدمیں آیا ہے:﴿فَـَٔامَنَ لَهُۥ لُوطࣱۘ وَقَالَ إِنِّي مُهَاجِرٌ إِلَىٰ رَبِّيٓۖ إِنَّهُۥ هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ﴾ [العنکبوت: ۲۶] \"پس لوط ایمان لائے اورکہا: میں اپنے رب کی طرف ہجرت کرتا ہوں، بلاشبہ وہ عزیزوحکیم(بڑا ہی غالب اور حکمت والا) ہے\"۔\nپھرلوط علیہ السلام ابرہیم علیہ السلام کے ساتھ مصر گئے۔وہاں سے دونوں کافی مال ودولت لے کر فلسطین واپس آئے۔دونوں کےپاس بکریاں اور دوسرے جانور بہت تھے۔اسی وجہ سے ابرہیم علیہ السلام تو حبرون ہی میں ٹھہر گئے اور لوط علیہ السلام کو ابرہیم علیہ السلام نےدین کی تبلیغ اوربھیڑ بکریاں چرانےکے لیے اردن کےشہر سدوم اور عمورہ بھیج دیا۔ یہاں کے لوگ مختلف برائیوں میں گھرے ہوے تھے۔ کچھ کا ذکر قرآن مجیدمیں آیا ہے۔ ان میں سے ایک یہ کہ یہ لوگ عورتوں کو چھوڑ کر مردوں سے اپنی خواہشیں پوری کرتے تھے۔ (النمل:۵۵)\nدوسری یہ کہ وہ آنے والے مسافروں کو لوٹ لیا کرتے تھے۔ (العنکبوت:۲۹)\nتیسری یہ کہ یہ لوگ برائی چھپ کر نہیں، بلکہ کھلے عام کرتے تھے۔ (العنکبوت:۲۹)\nلوط علیہ السلام نے ان کو ان برائیوں سے منع کیا۔ ارشادباری تعالیٰ ہے:﴿أَلَا تَتَّقُونَ إِنِّي لَكُمۡ رَسُولࣱ أَمِينࣱ فَٱتَّقُواْ ٱللَّهَ وَأَطِيعُونِ﴾ [الشعراء: ۱۶۱-۱۶۳] \"تم لوگ (اللہ)سے کیوں نہیں ڈرتے! یقیناًمیں تمھارا امانت دار رسول ہوں۔ تم اللہ سے ڈرو اور میری اطاعت کرو\"۔\nمگر ان لوگوں نے نہ تو بت پرستی ترک کی اور نہ برائیوں سے بازآئے۔ بلکہ انھوں نے خودلوط علیہالسلام کو ہی ڈرا یا اوردهمکایا۔اس سلسلے میں قرآن مجیدمیں ارشادہے:﴿قَالُواْ لَئِن لَّمۡ تَنتَهِ يَٰلُوطُ لَتَكُونَنَّ مِنَ ٱلۡمُخۡرَجِينَ﴾ [الشعراء: ۱۶۷] \"انھوں نے کہا: اے لوط! اگر تو ہمیں روکنے سے باز نہ آیا تو ہم تجھے (اپنے شہر سے) نکال دیں گے\"۔\nقرآن مجیدمیں دوسری جگہ لوط علیہ السلام کاقصہ اس طرح آیا ہے:﴿وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ وَأَنتُمۡ تُبۡصِرُونَ أَئِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةࣰ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمࣱ تَجۡهَلُونَ فَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوٓاْ ءَالَ لُوطࣲ مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسࣱ يَتَطَهَّرُونَ﴾ [النمل: ۵۴-۵۶] \"لوط کو بھی بھیجا، جب اس نے اپنی قوم سے کہا:تم برائی کا کام اس طرح کرتے ہو کہ لوگ تمھیں دیکھ رہےہوتے ہیں۔ کیا تم عورتوں کو چھوڑ کر مردوں سے اپنی خواہشیں پوری کرتے ہو؟ تم تو بڑے جاہل اوراحمق لوگ ہو۔اس پر اس کی قوم کا جواب اس کے علاوہ کچھ نہیں تھا کہ انھوں نے کہا: لوط کے گھر والوں کو اپنے شہر سے نکال باہر کرو۔ یہ لوگ بڑے پاک صاف بنتے ہیں\"۔\nبلکہ ایک وقت ایسا بھی آگیا جب لوط علیہ السلام کی قومنےان سےعذاب الٰہی لانےکامطالبہ کیا: ﴿ٱئۡتِنَا بِعَذَابِ ٱللَّهِ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ﴾ [العنکبوت: ۲۹] \"لے آ ہم پر اللہ کا عذاب اگر تو سچا ہے\"۔\nبالآخر جب یہ لوگ حد سے آگے بڑھ گئےتو اللہ کا عذاب آہی گیا۔اس سلسلے میں قرآن مجیدمیں ارشاد ہے:\n۱- ﴿وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرࣰ اۖ فَسَآءَ مَطَرُ ٱلۡمُنذَرِينَ﴾ [النمل: ۵۸] \"ہم نے ان لوگوں پر بری(طرح) بارش کی۔ وہ کیا ہی بری بارش تھی دھمکائے ہوئے لوگوں پر\"۔\n۲-﴿إِنَّا مُنزِلُونَ عَلَىٰٓ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِ رِجۡزࣰ ا مِّنَ ٱلسَّمَآءِ بِمَا كَانُواْ يَفۡسُقُونَ﴾ [العنکبوت: ۳۴] \"یقیناً ہم اس بستی والوں پر آسمان سے عذاب اتارنے والے ہیں کیونکہ یہ لوگ برائی کرتے ہیں\"۔\n۳- ﴿فَأَخَذَتۡهُمُ ٱلصَّيۡحَةُ مُشۡرِقِينَ فَجَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهِمۡ حِجَارَةࣰ مِّن سِجِّيلٍ﴾ [الحجر: ۷۳-۷۴] \"پس سورج نکلتے نکلتے انھیں ایک بڑے زور کی آواز نے پکڑ لیا۔بالآخر ہم نے اس شہر کو اوپر تلے کر دیا اور ان لوگوں پر کنکر والے پتھر برسائے\"۔\n۴- ﴿وَإِنَّ لُوطࣰ ا لَّمِنَ ٱلۡمُرۡسَلِينَ إِذۡ نَجَّيۡنَٰهُ وَأَهۡلَهُۥٓ أَجۡمَعِينَ إِلَّا عَجُوزࣰ ا فِي ٱلۡغَٰبِرِينَ ثُمَّ دَمَّرۡنَا ٱلۡأٓخَرِينَ وَإِنَّكُمۡ لَتَمُرُّونَ عَلَيۡهِم مُّصۡبِحِينَ وَبِٱلَّيۡلِۚ أَفَلَا تَعۡقِلُونَ﴾ [الصافات: ۱۳۳-۱۳۸] \"یقیناً لوط بھی رسولوں میں سے تھا۔ یاد کرو جب ہم نے اسے اور اس کے گھر والوں کو بچا یا سوائے ایک بڑھیا کے جو پیچھےرہ جانے والوں میں تھی۔پھر ہم نے دوسروں کو تہس نہس کردیا اور تم دن کو ان کی بستیوں کے قریب سے گزرتے ہو اور رات کو بھی پھربھی تم لوگ عقل سے کام نہیں لیتے\"۔\nیہ بڑھیاعورت لوط علیہ السلام کی بیوی تھی، جو ان پر ایمان نہیں لائی تھی اور جب اللہ کا عذاب آیا تو یہ بھی بستی والوں کے ساتھ ہلاک ہوگئی۔ قرآن کریم اس سلسلے میں کہتا ہے:﴿وَلَمَّا جَآءَتۡ رُسُلُنَآ إِبۡرَٰهِيمَ بِٱلۡبُشۡرَىٰ قَالُوٓاْ إِنَّا مُهۡلِكُوٓاْ أَهۡلِ هَٰذِهِ ٱلۡقَرۡيَةِۖ إِنَّ أَهۡلَهَا كَانُواْ ظَٰلِمِينَ قَالَ إِنَّ فِيهَا لُوطࣰ اۚ قَالُواْ نَحۡنُ أَعۡلَمُ بِمَن فِيهَاۖ لَنُنَجِّيَنَّهُۥ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ﴾ [العنکبوت: ۳۱-۳۲] \"جب ہمارے فرشتے ابراہیم کے پاس خوش خبری لے کر پہنچے تو انھوں نے کہا: ہم اس بستی کے لوگوں کو ہلاک کرنے والے ہیں۔ یقیناً اس بستی کے لوگ ظالم ہیں۔(ابرہیم نے) کہا:وہاں تو لوط موجود ہیں۔انھوں نے کہا:جو بھی وہاں ہے ہم خوب جانتے ہیں۔ ہم اسے اور اس کے گھروالوں کو بچالیں گے، سوائے اس کی بیوی کے وہ پیچھے رہ جانے والوں میں ہوگی۔وہ بچنے والوں میں نہیں ہوگی۔ بلکہ وہ ان لوگوں میں سے ہوگی جو ضائع ہونے والے ہیں، کیونکہ وہ لوط پر ایمان نہیں لائی تھی\"۔\nتورات میں ہے کہ جب لوط علیہ السلام اپنے اہل وعیال کو لے کر صبح سویرے قریب کی ایک بستی ضْغرمیں پہنچے تو سدوم اور عمورہ پر آگ اور گندھک برسنے لگی اور پوری بستی تہ و بالا ہوگئی۔ اس کی بیوی نے پیچھے مڑ کر دیکھا اور نمک کا ستون بن گئی۔ (بائبل-پیدائش: ۹ا :۲۳ـ۲۶)\nکچھ علماءکی رائے ہے کہ بحرمیت(بحر مردار)جسے بحر لوط بھی کہتے ہیں اسی عذاب کی وجہ سے بنا ہے۔ کیونکہ یہ عام سمندر سے چار سو میٹر گہرا ہے۔ ایسا لگتا ہےکہ (بستی) زمین کو الٹ پلٹ کرنے سے یہ گڈھا بن گیا۔ کیوں کہ اسی سمندر کے کنارے قوم لوط کے کچھ کھنڈر ملے ہیں۔ (دیکھیے:قصص الانبیاء: نجار:۱۱۳:۴)\nیہ ہے ان قوموں کا دردناک انجام جو اللہ تعالیٰ سے بغاوت کرتی ہیں۔اس کی عبادت کو چھوڑ کر دیوی، دیوتاؤں اور االلہ کی پیداکی ہوئی چیزوں کی پوجا پاٹ (عبادت)کرتی ہیں۔ان سے اپنی ضرورتیں طلب کرتی ہیں۔اس کے بتائے ہوےراستےکو چھوڑ کر اپنے نفس کی پیروی کرتی ہیں۔ اللہ کے بھیجے ہوئے نبیوں اور رسولوں کا مذاق اڑاتی ہیں اور ان کو اپنی بستیوں سے نکالنے کی دھمکی دیتی ہیں اور مختلف طریقوں سے ان کو ستاتی ہیں۔نتیجتاً اللہ کا غصہ بھڑک اٹھتا ہے اور اس کےحکم سے بستیاں کی بستیاں تہس نہس کردی جاتی ہیں۔چنانچہ عقل مندوں کے لیےاس طرح کے واقعات میں واضح عبرت وموعظت ہے۔\nقرآن کریم نے نبیوں اوررسولوں کا جو تفصیلی تذکرہ کیا ہے،اس سے اس کا مقصد لوگوں کو متنبہ کرنا اور انھیں نصیحت کرنی ہے۔ارشادباری تعالیٰ ہے:﴿لَقَدۡ كَانَ فِي قَصَصِهِمۡ عِبۡرَةࣱ لِّأُوْلِي ٱلۡأَلۡبَٰبِۗ مَا كَانَ حَدِيثࣰ ا يُفۡتَرَىٰ وَلَٰكِن تَصۡدِيقَ ٱلَّذِي بَيۡنَ يَدَيۡهِ وَتَفۡصِيلَ كُلِّ شَيۡءࣲ وَهُدࣰ ى وَرَحۡمَةࣰ لِّقَوۡمࣲ يُؤۡمِنُونَ﴾ [یوسف: ۱۱۱] \"بلاشبہ ان کی کہانیوں میں عقل اور سمجھ رکھنے والوں کے لیے ایک سبق ہے۔ یہ کوئی گھڑی ہوئی بات نہیں ہے۔ بلکہ یہ تصدیق ہے ان کتابوں کی جو اس سے پہلے کی ہیں، تمام چیزوں کو کھول کھول کربیان کرنے والا ہے اورایمان دار لوگوں کے ہدایت و رحمت ہے\"۔","",{}],[537,"§لیلۃ القدر\nلیل اور لیلہ کا مطلب رات ہے،رمضان کے آخری عشرےکی طاق راتوں میں سے ایک رات میں اللہ رب العزت کی رحمت وبرکت اورمغفرت کانزول ہوتاہے۔اس لیے اس رات کولیلۃ القدرکہتے ہیں۔اس طرح سے قدرکی رات کا مطلب عظمت ومنزلت والی رات ہےاور قدر کاایک مطلب قضا وقدراورتقدیرہےاور اس اہم رات میں اللہ تعالیٰ اس سال کے احکام اوربندوں پراپنے فیصلے کو مقدر کرتاہے۔ اس مبارک رات کو شب قدربھی کہتے ہیں۔ یہی وہ مبارک رات ہے، جس میں قرآن مجیدکو اللہ تعالیٰ نے لوح محفوظ سے بیت العزة (جو پہلے آسمان پر ہے) پر نازل کیا۔ پھر وہاں سے ضرورت کے مطابق جبریل علیہ السلام کے ذریعے نبی اکرم صلی اللہ علیہ وسلم پر تئیس سالوں تک تھوڑا تھوڑا اترتا رہا۔\nلیلۃ القدر کی اہمیت وفضیلت یہ ہےکہ اس رات کی عبادت ایک ہزارمہینوں سے بھی افضل ہے۔ اس رات اللہ تعالیٰ کےحکم سے فرشتے اور جبریل علیہ السلام زمین پر اترتے ہیں،تاکہ ان کاموں کو پورا کیا جاسکے جن کا فیصلہ اللہ تعالیٰ نے کردیا ہے۔ یہ مبارک رات صبح صادق تک رہتی ہے۔ چونکہ (سورہ البقرة: ۱۸۵) میں اس بات کی طرف اشارہ کر دیا گیا ہے کہ قرآن کے نزول کی ابتدا رمضان میں ہوئی۔ اس لیے یہ مبارک رات رمضان میں ہی ہوگی۔ صحیح حدیثوں میں تفصیلی طور پر بتادیا گیا ہے کہ یہ مبارک رات رمضان کی آخری دس راتوں میں سے کوئی ایک طاق رات ہے۔ اس کو بالجزم طور پر نہ بتانے کی وجہ یہ ہے کہ لوگ ان پانچ راتوں میں اس کو پانے کی کوشش کریں۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «مَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ». (صحیح البخاری: ۱۹۰۱، وصحیح مسلم: ۷۶۰/۱۷۵) \"جو شخص اس مبارک رات میں ثواب کی نیت سے عبادت کرے گا۔ اللہ اس کے سارے پچھلے گناہ (صغیرہ) مٹادے گا\"۔\nاسی لیے رمضان کے آخری دس دنوں میں عبادت کو رسول اکرم صلی اللہ علیہ وسلم بڑی اہمیت دیتے تھے اور امہات المومنین کوبھی عبادت کے لیے بیدارکرتے تھے۔ام المومنین عائشہ ڤکہتی ہیں: «کَانَ النَّبِيُّ صلی اللہ علیہ وسلم إِذَا دَخَلَ الْعَشْرُ شَدَّ مِئْزَرَهُ وَأَحْيَا لَيْلَهُ وَأَيْقَظَ أَهْلَهُ». (صحیح البخاری: ۲۰۲۴، صحیح مسلم: ۱۱۷۴/۷)۔ \"جب رمضان کا آخری عشرہ آتا تھا تو نبی اکرم صلی اللہ علیہ وسلم اپنی کمر کس لیتے اورپوری رات عبادت میں گزارتے تھے۔ اپنے گھر والوں کو بھی جگاتے تھے۔ (تاکہ وہ بھی اس مبارک رات کا فائدہ اٹھا سکیں)\"۔\nام المومنین عائشہ ڤ نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: «أَرَأَيْتَ إِنْ عَلِمْتُ أَيُّ لَيْلَةٍ لَيْلَةُ الْقَدْرِ مَا أَقُولُ فِيهَا؟ قَالَ: قُولِي: اللَّهُمَّ إِنَّکَ عُفُوٌّ کَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي». (سنن الترمذ: ۳۵۱۳، سنن ابن ماجہ:۳۸۵۰ امام ترمذی کہتے ہیں: یہ حدیث حسن صحیح ہے) \" اے اللہ کے رسول! اگر مجھے یہ مبارک رات مل جائے تو میں کیا دعا کروں؟ آپ نے فرمایا: کہو: اے اللہ! تو معاف کرنے والا ہے اور معافی کو پسند کرتاہے، اس لیے مجھے معاف کردے\"۔","",{}],[538,"§مال غنیمت\nدیکھیے: غنیمت","",{}],[539,"§ماہواری\nدیکھیے: حیض","",{}],[540,"§متعالی\nدیکھیے: اسماےحسنی","",{}],[541,"§متکبر\nدیکھیے: اسماےحسنی","",{}],[542,"§متین\nدیکھیے: اسماےحسنی","",{}],[543,"§مجاہدہ\nمجاہدہ کا مطلب پوری قوت صرف کرنا۔ اسی سے آتاہے کہ’جاہدوا فی اللہ حق جہادہ‘ (اللہ کے راستے میں پوری کوشش کروجیساکہ کوشش کاحق ہے۔دشمن کے خلاف جنگ کو جہاد اور مجاہدہ کہتے ہیں۔دینی جدوجہد اور کوشش کے معنی مجاہدے کا لفظ قرآن کریم میں استعمال ہوا ہے۔ اللہ تعالیٰ کا فرمان ہے کہ جو شخص مجاہدہ(تلاش حق) کرتا ہے،اللہ تعالیٰ اسے حق کا راستا ضروردکھاتا ہے۔قرآن مجیدمیں ہے: ﴿وَٱلَّذِينَ جَٰهَدُواْ فِينَا لَنَهۡدِيَنَّهُمۡ سُبُلَنَاۚ وَإِنَّ ٱللَّهَ لَمَعَ ٱلۡمُحۡسِنِينَ﴾ [العنکبوت: ۶۹] \"اور جن لوگوں نے ہمارے لیے کوشش کی ہم اُن کو ضرور اپنے رستے دکھا دیں گے۔ اور اللہ تعالی تو نیکو کاروں کے ساتھ ہے\"۔\nیہاں اسلامی تاریخ سے ایک ایسے شخص کی کہانی دی جا رہی ہے، جو راہ حق کی تلاش میں نکلا اور اس نے اس راہ کو پانے کے سلسلے میں بڑی دقتوں اور پریشانیوں کا سامنا کیا۔بڑی مصیبتیں برداشت کیں۔ بالآخر وہ اپنے مقصد میں کامیاب ہوا اور راہ حق کو پالیا۔\nسلمان فارسی رضی اللہ عنہ بیان کرتے ہیں:میں ایران کا باشندہ تھا، میرے والد مندر کے ذمہ دار تھے۔ ان کےحکم سے میں مندر کےاندر آگ جلائے رکھتا تھا۔ میری یہ کوشش ہوتی تھی کہ وہ آگ کبھی بجھنے نہ پائے۔ جس کی وجہ سے میرے والد مجھ سے بہت پیار کرتے تھے۔یہاں تک کہ مجھے گھر سے نکلنے نہیں دیتے تھے۔ ایک بار میں اپنے والد کے حکم سے کسی کام سے گھر سے باہر نکلا اور تھوڑی دور ہی چلا تھا کہ ایک گرجا گھر سے گھنٹہ بجنے کی آواز آئی۔ مجھے بڑا تعجب ہوا کہ آخر یہاں یہ کیسی آواز ہے؟ جو اس سے پہلے میں کبھی بھی نہیں سنی اور نہ ہی کبھی سننے کا موقع ہی ملا۔\nمیں اس گرجا گھر میں داخل ہوگیا اور وہاں ہورہی پوجا پاٹ کو غور سے دیکھنے لگا۔ شام ہونے تک میں وہیں ٹھہرا رہا اور شام ہونے پر واپس گھر چلا آیا۔ میرے والے نے دیر ہوجانے اور دیر سے گھر آنے کے سبب مجھ سے پوچھا کہ آخر تم کہاں چلے گئے تھے؟ میں نے کہا کہ میں گرجا گھر چلا گیا تھا، جہاں پر عیسائیوں کی پوجا پاٹ ہورہی تھی جو مجھے بڑی پسند آئی۔ لہٰذا میں اسے دیکھتا رہا اور اسی میں دیر ہوگئی۔ یہ سننا تھا کہ میرے والد نے مجھے زنجیر سے جکڑ دیا اور کہا کہ ان کے مقابلے میں تمھارا اپنا دین بہت ہی اچھا ہے۔ لیکن ان کی بات کا میرے اوپر کوئی اثر نہیں ہوا کیوں کہ عیسائیوں کا دین مجھے بھا چکا تھا۔ اس لیے میں نے عیسائی پادری کو کہلا بھیجا کہ میں اس کے دین کے بارے میں مزید جانکاری حاصل کرنا چاہتا ہوں۔اس نے جواب میں کہلا بھیجا کہ ہمارا بڑا گرجا گھر ملک شام(سوریا) میں ہے۔ وہاں سے تمھیں عیسائی مذہب کے بارے میں مزید جانکاری حاصل ہوسکے گی۔ میں نے انھیں کہلا بھیجا کہ جب بھی کوئی قافلہ شام سے آئے تو مجھےاس کے بارے میں خبر کریں۔ میں ان کے ساتھ ملک شام جاؤں گا۔آخر کا وہ دن آہی گیا کہ میں نے اپنے پاؤں کی بیڑیاں کاٹ ڈالیں اور بھاگ کھڑا ہوا اور ملک شام سے آنے والےقافلے کے ساتھ ملک شام چلا گیا۔ وہاں پہنچ کر میں وہاں کے بڑے گرجا گھر کے بڑے پادری کی خدمت میں حاضر ہوا اور اس کے پاس رہنے لگا۔ وہ مجھ سے بڑا خوش رہا کرتا تھا۔ لیکن میں نے اندازہ لگایا کہ وہ شخص انتہائی برا آدمی ہے۔ لوگوں سے صدقہ و خیرات لےکر اس کے مستحقین پر خرچ نہیں کرتا بل کہ وہ اس میں سے زیادہ تر کو چھپا لیتا ہے۔ جب اس کی وفات ہوگئی اور لوگ اس کے کفن دفن کے لیے آئے تو میں نے اس کی اس بری عادت کے بارے میں بتادیا۔ لوگوں نے اس کا ثبوت مانگا تو میں انھیں لےکر ایک کوٹھری میں گیا۔ جہاں اس نے سونے چاندی کے ڈھیر لگا رکھے تھے۔ یہ دیکھ کر لوگوں کو بڑا غصہ آیا۔ اور انھوں نے اس کو سولی پر لٹکا دیا اور اسے پتھر مارنے لگے۔پھر اس کی جگہ ایک دوسرا پادری متعین ہوا جو پہلے والے پادری کے مقابلے میں اچھا تھا۔ وہ دنیا بیزار اور آخرت کا طلب گار تھا۔ میں اس کی خدمت میں لگ گیا۔ جب اس کے مرنے کا وقت قریب آیا تو میں نے اس سے کہا کہ اے پادری جی آپ جانتے ہیں کہ میں آپ سے کتنی عقیدت رکھتا ہوں اب آپ اس دنیا سے رخصت ہونےوالے ہیں۔ بتائیے کہ آپ کے نہ رہنے پر میں کیا کروں اور کہاں جاؤں؟ اس نے کہا اے بیٹے! لوگ بدل گئے ہیں۔ آج اس دنیا میں مجھے کسی ایسے پادری کے بارے میں معلوم نہیں جو مجھ جیسا ہو۔ ہاں! ملک عراق کے موصل شہر میں ایک پادری ایسا ہے جس کے پاس تم جا سکتے ہو۔ پس میرے نہ رہنے پر تم اس کے پاس چلے جانا۔ تم اسے میرے ہی جیسا پاؤگے۔\nاس کے مرجانے کے بعد میں اس کے بتائے ہوے کے مطابق ملک عراق کے موصل شہر میں اس پادری کے پاس چلا گیا ہے۔ اور میں نے اسے وہ سب باتیں بتائیں جو پادری نے کہی تھیں اور یہ بھی بتایا کہ مجھے اسی نے آپ کے پاس بھیجا ہے۔ وہ بڑا خوش ہوا۔ اپنی خدمت میں رکھ لیا۔ اسے بھی میں نے ویسا ہی پایا جیسا کہ وہ پادری تھا اور جیسا اس نے بتایا تھا۔ وہ بڑا ہی اچھا، سچا اورخلیق شخص تھا۔ میں اس کی خدمت میں وقت گزارتا رہا یہاں تک کہ اس کی بھی وفات کا وقت قریب آگیا۔ تو میں نے اس سے کہا کہ اے محترم پادری جی آپ جانتے ہیں کہ میں آپ سے کتنی عقیدت رکھتا ہوں، اب آپ اس دنیا سے رخصت ہونے والے ہیں۔ بتائیے آپ کے نہ رہنے پر میں کیا کروں اور کہاں جاؤں؟ اس نے کہا: اے بیٹے! آج اس دنیا میں ویسے لوگ نہیں رہ گئے ہیں جیسے ہم لوگ ہیں اور جیسا تم چاہتے ہو۔ ہاں! میرے نہ رہنے پر تم نصیبین چلے جانا۔(نصیبین ترکی کا ایک شہر ہے جو ملک شام(سوریا) کی سرحد پر واقع ہے اس کو ترکی زبان میں یوں [Nusaybin]لکھتے ہیں)چنانچہ میں اس کی وفات کے بعد نصیبین چلا گیا۔ وہاں پہنچ کر میں نے وہاں کےگرجا گھر کے بڑے پادری کے پاس گیا اور میں نے اسے وہ سب باتیں بتائیں جو پادری نے کہی تھیں اور یہ بھی بتایا کہ مجھے اسی نے آپ کے پاس بھیجا ہے۔ وہ بڑا خوش ہوا۔ اپنی خدمت میں رکھ لیا۔ اسے بھی میں نے ویسا ہی پایا جیسا کہ اس سے پہلے کے دو پادری تھے اور جیسا اس کے بارے میں بتایا گیا تھا وہ ویسا ہی تھا۔ وہ بڑا ہی اچھا، سچا اورصاحبِ اخلاق شخص تھا۔ میں اس کی خدمت میں وقت گزارتا رہا یہاں تک کہ اس کی بھی وفات کا وقت قریب آگیا۔\nتو میں نے اس سے بھی کہا کہ اے پادری جی آپ جانتے ہیں کہ میں آپ سے کتنی عقیدت رکھتا ہوں اب آپ اس دنیا سے رخصت ہونے والے ہیں۔ بتائیے کہ آپ کے نہ رہنے پر میں کیا کروں اور کہاں جاؤں؟ اس نے کہا: میرے نہ رہنے پر تم عموریہ چلے جانا۔ وہاں کے پادری کو بھی تم میرے جیسا پاؤگے۔ (عموریہ بھی ترکی کا ایک شہر ہے جو ملک شام(سوریا) کی سرحد پر واقع ہے۔اس کو ترکی زبان میں bamorionلکھتے ہیں)\nچنانچہ اس کےمرجانے کے بعد میں اس کی ہدایت کے مطابق عموریہ چلا گیا ہے۔وہاں پہنچ کر میں وہاں کے پادری کے پاس پہنچا اور اس سے ساری باتیں بتائیں اور اس کی خدمت میں رہنے لگا۔ وہاں پر رہتےہوے میں نے تھوڑی بہت تجارت بھی کی۔ یہاں تک کہ میں بہت ساری گایوں کا مالک بن گیا۔ اسی طرح وقت گزرتا رہا یہاں تک کہ اس کی بھی وفات کا وقت قریب آگیا۔تو میں نے اس سے بھی کہا کہ آپ کو میری ساری کہانی معلوم ہے اب بتائیے کہ آپ کے نہ رہنے پر میں کہاں اور کس کے پاس جاؤں؟اس نے کہا کہ اے بیٹے اس وقت اس دنیا میں ایسا کوئی آدمی نہیں ہے کہ جس کے پاس جانے کا میں تمھیں مشورہ دوں۔ لیکن میری بات تم دھیان سےسنو: اب ایک نبی کے آنے کا وقت بہت قریب آگیاہے،جو ابراہیم کے دین ومذہب پر ہوگا۔جو ملک عرب میں پیدا ہونے والا ہے۔ پھر وہ ایک ایسی جگہ ہجرت کرکے جائے گا، جو کھجور کےدرختوں سے بھرا ہوگا۔اس نبی کی کچھ علامتیں و نشانیاں اور پہچان کی چیزیں ہیں جنھیں دھیان میں رکھنا۔ ایک چیز یہ ہوگی کہ وہ ہدیہ، تحفہ والی چیزیں تو کھائے گا، البتہ صدقہ و خیرات میں دی گئی چیزیں نہیں کھائے گا۔ دوسری سب سے اہم نشانی اس کی یہ ہوگی کہ اس کے دونوں مونڈھوں کے درمیان ایک نشان ہوگا جو اس کےنبی ہونے کی نشانی (مہر نبوت) ہوگی۔ اب اگر تم وہاں کا سفر کرسکتے ہو تو میرے نہ رہنے پر وہاں چلے جانا اور اس نبی کی تلاش میں رہنا۔ اس کے بعد اس پادری کی بھی وفات ہوگئی۔ پھر اس کے بعد میں کچھ دنوں تک عموریہ میں ہی ٹھہرا رہا۔ اسی دوران مجھے یہ خبر لگی کہ ملک عرب سے کچھ لوگ تجارت کے سلسلے میں عموریہ آئے ہوے ہیں۔ تو میں نے ان سے ملاقات کی اور ان سے یہ خواہش ظاہر کہ میرے پاس کچھ بکریاں اور گائیں ہیں جسے وہ لے لیں اور مجھےاپنے ساتھ ملک عرب لے چلیں۔ انھوں نے میری یہ پیشکش قبول کر لی۔ لیکن جب وہ لوگ وادیٔ قریٰ (جو شام اور مدینہ کے بیچ میں واقع ہے) پہنچے تو ایک یہودی کے ہاتھ مجھے بیچ دیا۔میں اس یہودی کے پاس رہنے لگا۔ یہ جگہ کھجوروں سے بھری ہوئی تھی۔ میں سوچنے لگا کہ کہیں یہ وہی جگہ تو نہیں؟ جہاں مجھے جانا ہے اور جس کے بارے میں پادری نے مجھے بتایا تھا کہ وہ نبی ہجرت کرکے آئے گا۔ابھی میں یہ سوچ ہی رہا تھا کہ اس یہودی کے چچا کا بیٹا وہاں آیا جو مدینہ کا رہنے والا تھا۔ اس نے مجھے خرید لیا اور وہ مجھے لےکر مدینہ آگیا۔مدینہ پہنچتے ہی میری آنکھیں اچانک چمک اٹھیں اور مجھے کامل یقین ہوگیا کہ یہ وہی جگہ ہے جس کے بارے میں پادری نے خبر دی تھی اور مجھ سے کہا تھا کہ تم وہاں چلے جانا۔ میں اسی طرح غلامی کے دن گزار رہا تھا۔ مجھے اپنے مالک کے کام کاج سے بہت کم فرصت ملتی تھی۔\nایک دن کی بات ہے کہ میرے مالک کے چچا کا ایک لڑکا آیا اور اس سے کہنے لگا کہ میں سنتا ہوں کہ لوگ کہہ رہے ہیں کہ قبا میں مکہ کا ایک آدمی آیا ہوا ہے جو یہ کہہ رہا ہے کہ میں نبی ہوں۔ ان کی آپس کی یہ باتیں سن کر مجھے جھرجھری آگئی۔ میں نے مالک کے چچا کے لڑکے سے کہا کہ ابھی تم کیا کہہ رہے تھے؟ یہ سننا تھا کہ میرے مالک نے مجھے زور سے ڈانٹا اور کہا کہ تم اپنے کام سے کام رکھو اور کام پر دھیان دو۔ان سب باتوں کے چکر میں نہ پڑو۔\nایک دن میں چپکے سے رات کے وقت اس نبی کے پاس پہنچ گیا اور ان سے کہا: کیا آپ اور آپ کے ساتھی ہجرت کر کے آئے ہیں؟ آپ یقینی طور پر ضرورت مند ہوں گے؟ میں کچھ چیزیں اپنے ساتھ لایا ہوں جو میں آپ کو صدقہ و خیرات کے طور پر دینا چاہتا ہوں۔ آپ اسے قبول کر لیجیے۔ اس کے بعد میں نے وہ چیزیں آپ کے سامنے رکھ دیں۔ نبی نے وہ چیزیں اپنے ساتھیوں کو دے دیں اور ان سے کہا کہ تم انھیں کھالواور خود اس سے دور رہے اور اس میں سے کچھ بھی نہ کھایا۔ میں نے اپنے دل میں کہا کہ چلو آج ایک بات کا امتحان تو ہوہی گیا کہ آپ صدقہ و خیرات کی چیزیں نہیں کھاتے ہیں۔پھر نبی مدینہ میں داخل ہوگئے۔ تو دوبارہ ایک دن میں ان کی خدمت میں حاضر ہوا اور میں نے ان سے کہا کہ میں آپ کو دیکھا کہ آپ صدقہ و خیرات کی چیزیں نہیں کھاتے ہیں اس لیے میں آپ کے پاس کچھ چیزیں بطور ہدیہ وتحفہ لایا ہوں آپ اسے قبول کر لیجیے۔ چنانچہ انھوں نے اسے قبول کرلیا اور اس میں سے تھوڑا بہت کھایا اور بقیہ اپنے صحابہ میں تقسیم کردیا۔ میں نے اپنے دل میں کہا کہ یہ دوسری نشانی بھی سچ نکلی جو پادری نے آپ کے بارے میں بتائی تھی۔\nپھر میں تیسری بار آپ سے ملنے آیا تو آپ جنت البقیع کے اندر کسی کو دفن کرنے کے بعد بیٹھے ہوے تھےاور آپ کا جسم اطہر دو چادروں میں لپٹا ہوا تھا۔ میں نے آپ کو سلام کیا اور آپ کی پیٹھ کی طرف کچھ ٹٹولنے لگا۔آپ نے اپنی پیٹھ سےچادر ہٹا لی۔ یہ دیکھتے ہی میں آپ سے لپٹ کر رونے لگا۔ مہر نبوت کو بوسہ دینے لگا۔آپ نے بڑے پیار سے مجھے اپنے پاس بٹھایا اور پوچھا کہ کیا بات ہے مجھے بتاؤ؟\nمیں نے شروع سے لےکر آخر تک کی ساری کہانی ان کو سنائی اور بتایا کہ میں نے آپ کی تلاش میں کیا کچھ نہیں کیا اور آج میں اپنے آپ کو انتہائی خوش قسمت سمجھتا ہوں کہ اللہ تعالیٰ نے مجھے حق تک پہنچا دیا۔میری یہ کہانی سن کر خود اللہ کے رسول اور آپ کے صحابۂ کرام بے حد متاثر ہوے۔\nیہ کہانی سلمان فارسی کی ہے جو آپ کی کوششوں اور جدو جہد سے غلامی سے رہائی پائے۔ اسلام میں آپ کو بڑا مقام حاصل ہے اور آپ کا بڑا درجہ ہے۔ کسی نے سچ کہا ہے کہ جو کوئی بھی کوشش اور جدو جہد کرے گا وہ ایک نہ ایک دن حق کو پاہی لے گا۔","",{}],[544,"§مجلس مشاورت\nدیکھیے: شوری","",{}],[545,"§مجمع البحرین\nمجمع البحرین کےمعنیٰ دو سمندروں کا سنگم۔اس سنگم کا ذکرقرآن مجید میں موسیٰ علیہ السلام کے قصے میں آیا ہے،جب وہ خضر علیہ السلام سے ملنے کےلیے نکل پڑ تے ہیں:﴿وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبࣰ ا﴾ [الکهف: ۶۰] \"جب موسیٰ نے اپنے خدمت گار سے کہا کہ میں چلتا ہی رہوں گا،یہاں تک کہ دو سمندروں کے سنگم پر پہنچ جاؤں خواہ مجھے برسوں چلنا پڑے\"۔\nان د وسمندروں کا سنگم کہاں ہے؟مفسرین نے جو خیالات ظاہر کئے ہیں ان میں زیادہ صحیح خیال یہ ہے،جس کے مطابق کہا جاسکتا ہے کہ یہ سنگم صحرائے سینا کا جنوبی حصہ ہے۔ جہاں عقبہ نامی خلیج اور سویس نامی خلیج آپس میں ملتی ہیں۔ پھر دونوں بحراحمر میں مل جاتی ہیں۔یہ واقعے اس وقت کا ہے جب بنی اسرائیل صحرائےسینا میں رہنے لگے تھے تو ایک دن موسیٰ علیہ السلام تقریر کرنے کھڑے ہوے اس وقت آپ سے پوچھا گیاکہ:سب سے بڑا عالم کون ہے؟ توآپ نے جواب دیا: میں۔ یہ بات اللہ کو پسندنہیں آئی اور اس نے کہا:تم سے زیادہ عالم میرا ایک بندہ مجمع البحرین میں ہے۔تم اس کے پاس جاؤ۔(مزید معلومات کےلیے ملاحظہ فرمائیں:صحیح بخاری: ۴۷۲۷، ۴۷۲۶)۔ نیز مزید تفصیلات کےلیے ملاحظہ فرمائیں : موسیٰ)","",{}],[546,"§مجوس\nمجوس کا ذکر قرآن مجیدمیں صرف ایک بار ہوا ہے: ﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ شَهِيدٌ﴾ [الحج: ۱۷] \"جو لوگ ایمان لائے اور جو یہودی بنے اور صابئی اور عیسائی اور مجوس اور جن لوگوں نے شرک کیا ان سب کے درمیان قیامت کے دن اللہ فیصلہ کردے گا۔بلاشبہ ہر چیز پر االلہ گواہ ہے\"۔\nاکثر علماء نے مجوس کے معنیٰ آتش پر ست بتایا ہے۔ان کو پارسی بھی کہتے ہیں۔ان کا تعلق ایران سے تھا۔چھٹی صدی قبل مسیح میں ان میں نبوت کا دعویٰ کرنے والا شخص زرتشت پیدا ہوا،جس نے دو معبودوں کا تصور پیش کیا۔ایک بھلائی کا معبود یزداں اور دوسرا برائی کا معبود جسے اہرمن کہا گیا۔ان کی مذہبی کتا ب سپاتیرہے۔جب ایران میں اسلام کی روشنی پھیلی تو مجوسیوں کے ذریعے پھیلایا ہوا اندھیرا چھٹ گیا۔اب پارسی بہت تھوڑی تعداد میں ہندوستان میں پائے جاتے ہیں۔\nقرآن مجید کی اس آیت میں بتایا گیاہے کہ یہ چھے گروہ ایمانوالے،یہودی،صابی،نصاریٰ، مجوس اورمشرک اب تک آپس میں سچائی کےلیے لڑرہے تھے۔اب قیامت کے دن ہی اللہ فیصلہ کرے گا کہ کون صحیح راہ پر ہے۔اس آیت میں دنیا میں پائے جانے والے مذاہب کو چھ حصوں میں تقسیم کیا گیا ہے۔ مذہبی تاریخ کے قارئین کےلیے یہ ایک اہم موضوع ہے۔اس کی بنیاد پر وہ اس پر تحقیق کر سکتے ہیں۔اسلامی شریعت میں مجوسیوں کے ساتھ وہی برتاؤکیا جائے گا جیسامشرکوں کے ساتھ کیا جاتاہے۔لیکن جزیہ کے بارے میں وہ اہل کتاب کی طرح ہیں، جیساکہ صحیح احادیث میں آیا ہے۔","",{}],[547,"§مجیب\nدیکھیے: اسماےحسنی","",{}],[548,"§مجید\nدیکھیے: اسماےحسنی","",{}],[549,"§مچھر\nدیکھیے: بعوضہ","",{}],[550,"§مچھلی\nدیکھیے: حوت","",{}],[551,"§محاربہ\nمحاربہ کےمعنیٰ ہیں: کسی گروہ یا تنظیم کےذریعے ملک میں فساد بر پاکرنا، لوگوں کو لوٹنا، ان کو قتل کرنا،ان کی عورتوں کی عزت برباد کرنا، گھروں کو آگ لگانا۔ ایسے لوگوں کو محارب کہتے ہیں۔ قرآن کریم میں انھی لوگوں کی سزا کےبارے میں ارشادہے:﴿إِنَّمَا جَزَٰٓؤُاْ ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ وَيَسۡعَوۡنَ فِي ٱلۡأَرۡضِ فَسَادࣰ ا أَن يُقَتَّلُوٓاْ أَوۡ يُصَلَّبُوٓاْ أَوۡ تُقَطَّعَ أَيۡدِيهِمۡ﴾ [المائدة: ۳۳] \"جو اللہ اور اس کے رسول سے لڑیں اور زمین میں فسادبرپا کرتے پھریں ان کی سزا یہی ہے کہ وہ قتل کردیے جائیں یا سولی پر چڑھا دیے جائیں یا مخالف جانب سے ان کے ہاتھ پاؤں کاٹ دیے جائیں یا انھیں جلاوطن(شہر بدر) کردیا جائے۔ یہ تو ہوئی ان کی دُنیوی ذلت وخواری اور آخرت میں ان کے لیے بڑا بھاری عذاب ہے\"۔\nیہ سخت عذاب حقیقت میں دوسروں کے لیے عبرت ہے۔ کیوں کہ ایک بار نبی اکرم صلی اللہ علیہ وسلم کے وقت ایسا ہی ایک واقعے ہوا تھاجس پر یہ آیت نازل ہوئی اور پھر کبھی بھی ایسا واقعے نہ ہوا۔\nاس واقعےکے بارے میں انس بن مالک رضی اللہ عنہ کہتے ہیں: \"عکل اور عرینہ قبیلے کے کچھ لوگ مسلمان ہوکر مدینہ آئے، مگر مدینہ کا موسم ان کو راس نہیں آیا۔ وہ لوگ بیمار پڑ گئے۔ اس پر نبی اکرم صلی اللہ علیہ وسلم نے ان سے کہا:اگر تم لوگ چاہو تو مدینہ کے باہر جو زکاۃکے اونٹ پلے ہوے ہیں، وہاں چلے جاؤ اور ان کے پیشاب اور دودھ کا استعمال کرو۔ انھوں نے ایسا ہی کیا۔ نتیجۃً ان کی صحت اچھی ہوگئی۔ پھر انھوں نے اونٹوں کے چروا ہے کو قتل کردیا اور اونٹوں کا ریوڑ لے کر بھاگ نکلے۔ جب اس کی خبرنبی اکرم صلی اللہ علیہ وسلم کو ملی تو آپ نے کچھ لوگوں کو بھیجا، تاکہ انھیں پکڑ کر لایا جائے۔ پکڑے جانے پر ان کے ہاتھ پاؤں کاٹ دیے گئے۔ آنکھوں میں گرم لوہے کی سلائی پھیردی گئی۔ انھیں سورج کی تپتی ہوئی دھوپ میں چھوڑ دیا گیا۔ وہ پانی مانگتے تھے تو پانی نہیں دیا گیا۔ ابو قلابہ راوی حدیث کہتے ہیں:ایسا اس لیے کیا گیا کہ ان لوگوں نے چوری کی، قتل کیا اور اسلام لے آنے کے بعد کفر کیا (مرتد ہو گئے) اور اللہ اور رسول سے محاربہ کیا، حتی کہ ان کی موت واقع ہوگئی\"۔(صحیح البخاری: ۲۳۳، وصحیح مسلم: ۱۶۷۱/۹)\nاس ایک واقعے کے بعد پھر کسی کو اس طرح کے فساد کی ہمت نہیں ہوئی۔ اس واقعے نے کتنی جانوں کو بچا لیا۔ تاہم فساد کرنے والے پکڑے جانے سےپہلےاگرآپ نے آپ کو حکومت کے حوالے کردیں تو ان کی سزا معاف کی جاسکتی ہے۔قرآن کریم میں ہے:﴿إِلَّا ٱلَّذِينَ تَابُواْ مِن قَبۡلِ أَن تَقۡدِرُواْ عَلَيۡهِمۡۖ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏﴾ [المائدة: ۳۴] \"ہاں! جو لوگ اس سے پہلے توبہ کرلیں کہ تم ان پر قابو پالو، تو یقین مانوکہ اللہ تعالیٰ غفورورحیم(بہت بڑی بخشش اور رحم وکرم والا) ہے\"۔\nیہ معافی صرف اس سزا تک محدود ہے، جس کا تعلق سلطنت (مملکت) سے ہے۔تاہم جس کا تعلق کسی فرد سے ہو، چاہے وہ قتل ہو یا لوٹ مار، جب تک وہ معاف نہ کردے، معاف نہیں کیا جائے گا، کیوں کہ سلطنت (مملکت) کو یہ اختیار نہیں ہے کہ لوگوں کے حقوق کو معاف کردے۔","",{}],[552,"§محتاجی\nدیکھیے: فقر","",{}],[553,"§محل\nدیکھیے: قصر","",{}],[554,"§محمد رسول اللہ صلی اللہ علیہ وسلم کی صاحبزادیاں\nدیکھیے: بنات النبی صلی اللہ علیہ وسلم","",{}],[555,"§محمد رسول اللہ صلی اللہ علیہ وسلم\nاسلام سے پہلےعربوں میں مختلف خیالات ونظریات کے لوگ پائے جاتے تھے۔ان کو دو گروہوں میں تقسیم کیا جاسکتا ہے۔ایک دہریہ جو اللہ تعالیٰ کے وجود ہی کاانکار کرتے تھے اور کہتے تھے کہ ہماری اس زندگی کے بعد کوئی اور زندگی نہیں ہے۔ہم تو صرف اس زندگی میں ہی کھائیں پئیں گے اور پھر مر جائیں گے۔نہ ہمیں دوبارہ اٹھایا جائے گا اور نہ ہی ہم سے ہمارے اعمال کا بدلہ لیا جائے گا۔\nدوسرا گروہ مذہبی لوگوں کا تھا۔یہ بھی دو حصوں میں بٹاہوا تھا۔ایک گروہ جوایک االلہپر یقین رکھتے تھےاورجن کو ’حنفیہ‘کہا جاتاتھا۔لیکن یہ صرف چند لوگ تھے۔دوسرا گروہ ان کا تھا جو بتوں کی پوجا کرتے تھے۔ان کاعقیدہ تھا کہ فرشتے اورآبا و اجداد کی روحیں، مذہبی طاقت ہیں۔ان کی عبادت سے اللہ کوخوش کیا جاسکتاہے۔اسی لیےانھوں نے ان کی مورتیاں بنا رکھی تھیں، جن کے سامنے وہ اپنا سر جھکاتے تھے۔ ان سے اپنی ضرورتوں کے سامان مانگا کرتے تھے۔ یہ یقین رکھتے تھے کہ یہ مورتیاں اللہ کے پاس ہماری سفارش کریں گی۔\nزمانۂ جاہلیت کےان بتوں میں مشہوربت ہبل، ود،سواع،یغوث، یعوق، نسر، عزیٰ، لات اور منات کے تھے۔اسی طرح ابراہیم علیہ السلام اور مریم علیہا السلام کی مورتیاں بھی بنا رکھی تھیں۔بلکہ ان کو کعبہ میں رکھا ہواتھا۔\nایسےحالات میں محمد صلی اللہ علیہ وسلم کو اللہ تعالیٰ نےاپنارسول بنا کر بھیجا۔تاکہ لوگوں کو بتوں کی پر ستش سے روک کر ایک اللہ کی عبادت کی دعوت دیں اورمنحرف لوگوں کو صحیح مذہب کا راستا دکھائیں۔\nمحمد صلی اللہ علیہ وسلم کی زندگی کو ہم دو حصوں میں منقسم کرسکتے ہیں۔\nپہلا حصہ آپ کی پیدایش سے شروع ہوتا ہے اور نبوت ملنے تک چالیس سال کی عمر تک پھیلاہوا ہے۔دوسرا حصہ آپ کی نبوت کے بعد ۴۰سال کی عمر سے شروع ہوکرآپ کی وفات پر ختم ہوتاہے۔\n§نبی کریم صلی اللہ علیہ وسلم کی زندگی کا پہلا حصہ:\nآپ کی مبارک سیرت وکردار پر کچھ لکھنے سے پہلے یہاں کچھ عرب ملک اور شہر مکہ کے اس وقت کے حالات پر روشی ڈالنا بہتر ہوگا۔عرب کی سرزمین شام سے لےکر یمن اور بحر احمر سے لےکرخلیج عرب تک پھیلی ہوئی ہے۔ یہاں کے رہنے والوں کی نسل کاسلسلہ اسماعیل بن ابراہیم علیہما السلام سے شروع ہوتا ہے۔ نبی اکرم محمد صلی اللہ علیہ وسلم اسماعیل علیہ السلام کی اولادمیں سے تھے۔\nآپ کی پیدایش۲اربیع الاول یا۹ربیع الاول، پیر،مطابق ۲۰یا۲۲ اپر یل ا۵۷ء مکہ میں ہوئی۔آپ کے والد عبداللہ کا آپ کی پیدایش سے پہلے ہی انتقال ہوچکا تھا۔صحیح احادیث میں آیا ہے: عرباض بن ساریہ سلمی رضی اللہ عنہ کہتے ہیں کہ میں نےرسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا:«رُؤْيَا اُمّي الَّتِي رَأَتْ أَنَّهُ خَرَجَ مِنْهَا نُورٌ أَضَاءَتْ لَهُ قُصُورُ الشَّامِ». (مسند احمد: ۲۷ا/۴، ۱۷۱۶۳، المستدرک للحاکم: ۶۰۰/۲) \"میری ماںکاخواب جنھوں نے دیکھا کہ ان کے جسم سے ایک ایسی روشنی نکلی جس سے شام تک کےمحلات جگمگانے لگے\"۔اس خواب میں نبی اکرم صلی اللہ علیہ وسلم کی پیدایش اور اس کے بعد آپ کے ذریعے سے جو خیرعام ہونے والا تھا، اس کی بشارت دی گئی تھی۔\nجب آپ کی ولادت ہوئی تو عرب کی قدیم روایات کے مطابق آپ کوایک قریبی گاؤں میں بھیج دیا گیا، جہاں آپ نے حلیمہ سعدیہ کا دودھ پیا اور دیہات کی کھلی فضا میں پر ورش پاتے رہے۔لیکن یہاں ایک ایسا معجزہ رونماہو ا جس سے گھبراکر حلیمہ نے آپ کو آپ کی والدہ آمنہ کے پاس واپس بھیج دیا۔ صحیح مسلم میں اس کی تفصیل انس بن مالک رضی اللہ عنہ اس طرح بیان کرتےہیں کہ\"رسول اللہ صلی اللہ علیہ وسلم کچھ بچوں کے ساتھ کھیل رہے تھے کہ اسی اثنا میں جبرئیل علیہ السلام آئے اور آپ کو زمین پرگرا کر آپ کے سینے کو چاک کیا اور اس میں سے آپ کادل نکال کر زم زم کے پانی سے، جسے وہ ایک سونے کے برتن میں لائے تھے دھویا،پھر اس کو اپنی جگہ پر واپس رکھ دیا\"۔(صحیح مسلم: ۲۶۱/۲۶۱)\nاس وقت آپ پانچ سال کے تھے۔اس معجزے کے ذریعے سے اللہ تعالیٰ نے آپ کے دل سے ہر طرح کی گندگی کو نکال کراسےپاک وصاف کردیا اور ایک طرح سے آپ کو مستقبل میں دی جانے والی نبوت کےلیے ابتدا ہی سے تیار کیا جانے لگا۔ابھی۶سال کے بھی نہیں ہوے تھے کہ آپ کی والدہ بھی وفات پاگئیں۔یتیم پیدا ہوے تھے۔اب ماں کی طرف سے بھی یتیم ہوگئے۔تب آپ کے دادا عبدالمطلب نے آپ کی پرورش وپرداخت کی ذمہ داری اٹھائی۔ آٹھ سال کی عمرمیں دادا کا بھی انتقال ہوگیا۔انھوں نے اپنے ایک دوسرے بیٹے ابو طالب کو آپ کا سرپر ست بنایا۔ابو طالب کو آپ سے بہت پیارتھا۔وہ ہر طرح سےآپ کا خیال رکھتے تھے۔تجارتی سفر میں بھی آپ کو ساتھ رکھتے تھے۔آپ بھی ان کی ہر طرح سے خدمت کرتے تھے۔صحیح بخاری اور صحیح مسلم میں ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \" ہر وہ نبی جس کو اللہ نے مبعوث فرمایا اس نے بکری چرائی۔ آپ کے اصحاب نے عرض کیا: کیا آپ نے بھی بکری چرائی ہے؟ فرمایا: ہاں، میں چند قیراطوں کے عوض مکہ والوں کی بکریاں چرایا کرتا تھا\"۔(صحیح البخاری: ۲۲۶۲)\nاس سے واضح ہوتا ہے کہ ابو طالب کی معاشی حالت کچھ اچھی نہیں تھی،اس لیے نبی اکرم صلی اللہ علیہ وسلم بکریاں چراکر ان کی مدد کرتے تھے۔\nابھی آپ ۲۵سال کےایک نوجوان تھے کہ آپ کی شہرت پورےقریش میں پهیل گئی کہ آپ بڑے سچے، صاحبِ اخلاق،امانت داراور اعلیٰ کردار کی شخصیت ہیں۔قریش کی ایک چالیس سالہ مال داربیوہ خدیجہ کی پیش قدمی سے آپ کی ان سے شادی ہوگئی۔وہ دو بار بیوہ ہوچکی تھیں۔شادی کے بعد آپ خدیجہ کے گھر میں رہنے لگے،جو مروہ پہاڑی سے تھوڑے فاصلےپر تھا۔ ہجرت کرنے تک آپ اسی گھر میں رہے۔(محمد صلی اللہ علیہ وسلم کی شادیوں کی تفصیلات کےلیے ملاحظہ فرمائیں: محمد صلی اللہ علیہ وسلم کی ازواج)\nنبی اکرم صلی اللہ علیہ وسلم شروع ہی سے بڑے امین وصادق،انصاف پسند اور معاملہ فہم تھے۔جب آپ کی عمر ۳۵سال کی ہوئی تو قریش نے دوبارہ تعمیرکعبہ کا منصوبہ بنایا۔حجراسودکو اس کے اپنے مقام پر دوبارہ رکھنے کے مسئلے پر قریش کے مابین سخت اختلاف ہوگیا۔ بات قتل وقتال تک پہنچ گئی۔اس موقعے پر آپ کی اسی اچھی شہرت نے سب کو اس بات پرآمادہ کیا کہ اس جھگڑے کا فیصلہ آپ ہی فرمائیں۔اس واقعے سے آپ کی شخصیت پر اچھی خاصی روشنی پڑتی ہے :مجاہد کہتےہیں کہ میرے مولیٰ عبداللہ بن سائب نے مجھےبتایاکہ قریش کےمابین حجراسودکو اس کی جگہ پر دوبارہ نصب کرنے سےمتعلق اختلاف ہوگیا۔ قریب تھاکہ ان کے درمیان تلواریں اٹھ جائیں۔ایک آدمی نے کہا کہ دروازے سے جو شخص پہلے داخل ہو اس کو اس مسئلے میں فیصلے کے لیے حکم بناؤ۔ہوا یہ کہ پہلے داخل ہونے والے رسول اللہ صلی اللہ علیہ وسلم تھے۔لوگ پکاراٹھے کہ یہ امین آپہنچے۔ آپ کو لوگ زمانۂ جاہلیت میں امین کے لقب سے پکارتے تھے۔ لوگوں نے کہا کہ اے محمد! ہم آپ کے فیصلے سے راضی ہیں۔آپ نے اس کا حل یہ نکالاکہ ایک چادرمنگا کر اسے بچھادی۔ اپنے ہاتھوں سے حجراسود کو اس میں رکھ دیا اور ہرقبیلے کے نمایندوں سے کہا کہ سب لوگ چادرکا ایک ایک کنارہ پکڑلیں۔ چنانچہ انھوں نے ایسے ہی کیا اور حجر اسود کو اٹھایا۔ پھر رسول اکرم صلی اللہ علیہ وسلم نے اس کو اپنے ہاتھوں سے لے کر اس کی اصل جگہ پررکھ دیا۔ (مسند احمد: ۴۲۵/۳، المستدرک للحاکم: ۴۵۸/۳)\nاس طرح آپ کی اس حکمت عملی سے ایک جنگ ٹل گئی۔اس معاملے سے جہاں آپ کی حکمت ودانائی اورذہانت وفطانت کا پتا چلتا ہے، وہیں یہ بات بھی ثابت ہوجاتی ہےکہ آپ نبوت سے پہلے ہی معاشرہ میں انصاف پسند اور غیر جانبدار مشہور ہوچکے تھے۔\nچالیس سال کی عمرمیں نبی اکرم صلی اللہ علیہ وسلم کو ایسے خواب دکھائی دینے لگے جو جلد ہی سچ ثابت ہوجاتے تھے۔گویااس طرح آپکو بتایا جارہاتھا کہ آپ پر وحی کا نزول ہونے والا ہے۔اب آپ کو جب بھی موقع ملتا آپ’حرا‘نامی پہاڑ پرچلے جاتے اور اللہ کے ذکر و اذکار میں مصروف ہوجاتے۔ بیشتروقت تنہا رہتے۔ جب آپ اپنی قوم کو دیکھتے، جو بتوں کی پر ستش میں لگی ہوئی تھی تو آپ کو بہت تکلیف ہوتی تھی۔آپ چاہتے تھےکہ لوگ شرک اور بت پر ستی چھوڑ کر ایک اللہ کی عبادت کریں، جس نے ان کو اور ساری دنیا کو پیداکیا ہے۔\n§نبی اکرم صلی اللہ علیہ وسلم کی زندگی کا دوسرا حصہ:\nجب آپ کی عمر۴۰سال ہوئی تو پیر کے دن رمضان المبارک میں ایک معجزے کا ظہور ہوا۔آپ غارحرامیں اللہ کی یاد میں مشغول تھے کہ جبرئیل علیہ السلام نے آکر کہا: میں اللہ کا فرشتہ ہوں اور اسی کےحکم سے آپ کے پاس وحی لےکر آیا ہوں۔ اس لیے آپ پڑھیے۔آپ نےکہا: میں پڑھنا نہیں جانتا۔تب انھوں نے پوری طاقت سے آپ کو بھینچا پھر چھوڑ دیا اور کہا:پڑ ھیے۔ آپ نےکہا: میں پڑھنا نہیں جانتا۔جبرئیل علیہ السلام نے پھر آپ کو بھینچااور چھوڑ دیا، پھر کہا:پڑھیے۔ آپ نے کہا: میں پڑ ھنا نہیں جانتا۔تیسری بار فرشتے نے کہا: ﴿ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ﴾ [العلق: ۱-۵] \"پڑ ھو اپنےرب کے نام سے، جس نے انسان کو جمے ہوے خون کے لوتھڑے سے پیدا کیا، پڑھوتمھارا رب بہت عظیم ہے، جس نے قلم کے ذریعے علم دیا،انسان کو وہ علم دیا جسے وہ نہیں جانتاتھا\"۔\nیہپہلی وحی تھی۔آپ فوراً گھر لوٹ آئے۔آپ کا دل ڈرسے کانپ رہا تھا۔ گھر آتے ہی خدیجہڤ سےکہا:مجھے کمبل اڑھادو۔مجھے کمبل اڑھادو۔آپ کوکمبل اڑھادیا۔جب گھبراہٹ ختم ہوگئی توآپ نے سارا واقعہ خدیجہڤکو سنایااور یہ بھی کہا کہ مجھے اپنی جان کا خوف ہے۔خدیجہ نے کہا:ایسا ہرگز نہیں ہوسکتا۔اللہ کی قسم اللہ تعالیٰ آپ کوہرگز ذلیل ورسوا نہیں کرے گا، اس لیے کہ آپ صلہ رحمی کرتےاور رشتوں کو جوڑتے ہیں۔ناداروں اور بے سہارا لوگوں کاسہارا بنتےہیں۔غریبوں اور مسکینوں کی مددکرتےہیں۔مہمانوں کی خاطرتواضع کرتے ہیں اورمصائب ومشکلات میں لوگوں کے کام آتے ہیں، تو پھر اللہ تعالیٰ آپ کو کیسے برباد ہونے دے گا؟پھر خدیجہڤ آپ کو اپنے چچازاد بھائی ورقہ بن نوفل کے پاس لےکر گئیں، جو زمانۂ جاہلیت میں نصرانیت قبول کر چکے تھے۔عبرانی زبان لکھتے تھے اورانجیل کوعبرانی زبان میں لکھتے تھے۔اس وقت وہ کافی بوڑھے اور اندھے ہوگئے تھے۔خدیجہڤ نے کہا: اے میرے چچازاد بھائی ذرااپنے بھتیجے کی بات سنیے۔ورقہ نے پوچھا: آپ نے کیا دیکھا ہے؟ نبی اکرم صلی اللہ علیہ وسلم نے ورقہ کو جو کچھ دیکھا تھا اسے بتایاتوورقہ نےآپ سے کہا:یہ تو وہی فرشتہ ہے، جو موسیٰ علیہ السلام کے پاس آیا تھا۔کاش کہ میں اس وقت میں مضبوط جوان ہوتا،کاش کہ میں اس وقت زندہ ہوتا،جب آپ کی قوم آپ کویہاں سےنکال باہرکرےگی۔آپ نے حیرت سے پوچھا: کیا مجھےیہ لوگ یہاں سے نکال دیں گے؟ورقہ بن نوفل نے کہا: ہاں۔ پھر کہا:کوئی آدمی ایسانہیں گزراجو وہ پیغام لےکر آیا ہو جوآپ لے کر آئےہیں اور اس کی مخالفت نہ ہوئی ہو۔اگرمجھے آپ کا وہ دن ملا تو میں آپ کی بھرپور تائیدکروں گا۔ اس کے کچھ عرصہ بعد ورقہ کا انتقال ہوگیا۔پھروحی کا سلسلہ منقطع ہوگیا۔(چھے مہینے تک وحی نہیں آئی، جس کی وجہ سے آپ بہت زیادہ غمزدہ تھے۔یہ ایک طرح سے آپ کا امتحان تھاکہ وحی جو اللہ کی جانب سےآتی ہے اور وہ وسوسے جو شیطان کی جانب سے قلب میں ڈالے جاتے ہیں دونوں میں فرق کرسکیں)۔پھر چھے مہینے کےبعد وحی آئی،جو یہ تھی:﴿يَٰٓأَيُّهَا ٱلۡمُدَّثِّرُ قُمۡ فَأَنذِرۡ وَرَبَّكَ فَكَبِّرۡ وَثِيَابَكَ فَطَهِّرۡ وَٱلرُّجۡزَ فَٱهۡجُرۡ وَلَا تَمۡنُن تَسۡتَكۡثِرُ وَلِرَبِّكَ فَٱصۡبِرۡ﴾ [المدثر: ۱-۷] \"اے اوڑھ لپیٹ کر لیٹنے والے! اٹھو اور لوگوں کو ان کی گمراہی سے ڈراؤ اور اپنے رب کی کبریائی بیان کرو اور اپنے کپڑ ے پاک رکھو اور گندگی سےدور رہو، اور زیادہ وصول کرنے کےلیے احسان نہ کرواور آپ نے ر ب کےلیے صبر سے کام لو\"۔(صحیح البخاری: ۳۳۹۲،صحیح مسلم: ۴۰۳)\nاب آپ کے کندھوں پر بھٹکتی ہوئی انسانیت کو صحیح راستا دکھانے کی بھاری ذمہ داری ڈال دی گئی۔ یہاں سےآپ کی نبوت ورسالت شروع ہوتی ہے۔اس کے دو دور ہیں۔ایک دورمکی،جو آپ صلی اللہ علیہ وسلم کی ۴۰کی عمر سے ۵۳سال کی عمر یعنی تیرہ سال پرمحیط ہے۔دوسرا دور مدنی ہے جو۵۳سال کی عمر سے ۶۳سال کی عمر (دس سال) تک جوآپ کی وفات پر ختم ہوتا ہے۔\n§مکی دور:\nجب نبی اکرم صلی اللہ علیہ وسلم نے مذہب اسلام کی دعوت شروع کی توعورتوں میں سب سے پہلے ایمان لانے والی آپ کی وفا کی پیکرشریک حیات خدیجہ ڤ تھیں، جنھوں نے آپ کی بھر پور مدد کی۔پھر علی رضی اللہ عنہ نےدس سال کی عمرمیں ایمان قبول کیاجو آپ کے چچا ابو طالب کے لڑکے تھے۔زیادہ عمر کے ایمان لانے والوں میں ابو بکر رضی اللہ عنہ تھے،جن کی عمر اس وقت اڑتیس سال تھی۔غلاموں میں زید بن حارثہ رضی اللہ عنہ نےسب سے پہلے اسلام قبول کیا۔(صحیح البخاری: ۷۰ا اور ا۸۳)\nتین سال تک آپ خفیہ طور سے اسلام کی دعوت دیتے رہے اور لوگ اسلام میں داخل ہوتے رہے۔اس کے بعد اللہ تعالیٰ نےآپ کویہ حکم دیا:﴿وَأَنذِرۡ عَشِيرَتَكَ ٱلۡأَقۡرَبِينَ﴾ [الشعراء: ۲۱۴] \"اور اپنے قریبی رشتہ داروں کو اللہ سے ڈراؤ\"۔\nیعنی اپنےقریبی رشتہ داروں کو اسلام کی دعوت دو اور ان کو پیش آنے والے عذاب سے خبردار کرو۔وہ یہ ہے کہ مرنےکے بعد آنے والی زندگی میں صرف اسلام پر قائم رہنے سے ہی جنت میں داخل ہوسکتے ہیں،دوسری حالت میں وہ ہمیشہ کےلیے جہنم میں ڈال دیے جائیں گے۔عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں: \"+وَأَنْذِرْ عَشِيرَتَکَ الأَقْرَبِينَ\" کے نازل ہونے کے بعد آپ صفا نامی پہاڑی پر چڑھ گئے اور وہاں کھڑے ہوکر پکارا:یا صباحاہ۔یہ سن کر قریش کے لوگ اکٹھا ہوگئے۔پھر آپ نے ایک ایک گروہ کو پکار پکار کہا:اگر میں تم سے یہ کہوں کہ اس پہاڑی کے عقب سے تم پر حملہ ہونےوالا ہے تو کیا تم میری بات کو سچ مانوگے؟لوگوں نے کہا:ہم نے آپ کو کبھی جھوٹ بولتے ہوے نہیں پایا ہے۔ (اس لیے آپ کی بات پر یقین کریں گے) تو آپ نے ان کو مخاطب کرتے ہوے کہا: میں تم کو اللہ کے عذاب سے متنبہ کرتاہوں\"۔(صحیح البخاری:۴۹۷۱، وصحیح مسلم: ۲۰۸، ۳۵۵)\nیہ باتیں سن کریہ لوگ بہت جھنجلائےاور کہنے لگے: اسی لیے تم نے ہمیں جمع کیا تھا؟ان میں ابولہب بھی تھا، جو آپ کا چچا تھا۔اس نے کہا: تم برباد ہو،کیا تم نے ہمیں اسی لیے اکٹھا کیا تھا؟وہ جب تک زندہ رہا آپ کا دشمن بنا رہا۔اس کی بیوی بھی آپ کے راستے میں ہمیشہ کانٹے بچھاتی رہی۔جس کے جواب میں اللہ تعالیٰ نے قرآن مجیدمیں سورہ لہب نازل کی:﴿تَبَّتۡ يَدَآ أَبِي لَهَبࣲ وَتَبَّ مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ سَيَصۡلَىٰ نَارࣰ ا ذَاتَ لَهَبࣲ وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ فِي جِيدِهَا حَبۡلࣱ مِّن مَّسَدِۭ﴾ [المسد: ۱-۵] \"ابو لہب کے دونوں ہاتھ ٹوٹ گئے،وہ خود بھی برباد ہوگیا،نہ اس کی دولت اس کے کام آئی نہ کچھ وہ جواس نے کمایا تھا۔وہ جلد ہی بھڑکتی ہوئی آگ میں داخل ہوگا اوراس کی عورت بھی جو ایندھن لادنے والی ہے۔اس کی گردن میں کھجور کے ریشوں کی مضبوط رسی پڑ ی ہوگی\"۔\nاب نبی اکرم صلی اللہ علیہ وسلم نے اعلانیہ اسلام کی دعوت دینی شروع کردی اورلوگوں کے سامنے مختلف موقعوں پر یہ تقریر کرنے لگے کہ اس دنیا کا خالق ومالک اورقادرمطلق تو صرف ایک اللہ ہے، اس کو چھوڑکر کسی اور کی عبادت کرنا، کسی اور سےمدد مانگنا، کسی اور کے سامنے سر جھکاناسب حرام ہے اور اللہ تعالیٰ نےمجھ کو آخری نبی اوررسول بنا کر بھیجا ہے۔ میرےنبی اوررسول ہونے پر ایمان لائے بغیر کوئی کامیابی اورنجات حاصل نہیں کرسکتا۔\nایک طرف آپ پوری قوت سے اسلام کی دعوت دے رہےتھے تو دوسری جانب قریش پوری طاقت سے آپ کی مخالفت پر اتر آئے تھے۔\nقرآن کریم مسلسل نازل ہوتارہا،جس میں وقت کے مطابق مناسب اورٹھیک ٹھیک احکام دیے جارہے تھے اور خودقرآن مجید لوگو ں کے دلوں میں اترتا جارہاتھا اور ان کو متحد ہوکر نئے معاشرے کی بنیاد رکھنے کےلیے تیار کر رہا تھا۔آپ کی بات اب مکہ سے باہر نکل کردوسرےعلاقوں میں پھیلنے لگی اور لوگ گروپ بنا کرآتے، قرآن سنتے اور اسلام قبول کرلیتے۔ دوسری جانب قریش آپ کے خلاف جھوٹا پروپیگنڈا کرنے اورغلط اور جھوٹی باتیں پھیلانے میں لگےرہے۔کبھی کو آپ شاعر کہا توکبھی ساحر وکاہن اورکبھی آسیب زدہ۔عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں:ضماد مکہ آیا، اس کا تعلق ازد شنوءہ سے تھا اور وہ جن وآسیب جھاڑتا تھا، اس نے مکہ کے بیوقوفوں کو کہتے سنا کہ محمد مجنون(آسیب زدہ) ہیں تو اس نے کہا : میں اس آدمی کو دیکھ لیتا، تو اچھا ہوتا، شاید اللہ تعالیٰ اسے میرے ہاتھوں سے شفا دے، تو اس نے آپ سےملاقات کی اور کہا: اے محمد! میں جن و آسیب اتارتا ہوں اور جسے اللہ تعالیٰ چاہتا ہے میرے ہاتھوں شفا دیتا ہے۔ کیا آپ مجھ سے جھاڑ پھونک کرانا چاہتے ہیں؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمام تعریفیں اللہ کے لیے ہیں۔ ہم اس کی حمدوثنا بیان کرتے ہیں۔ اس سے مدد طلب کرتے ہیں۔ اللہ جسے ہدایت دیتا ہے،اسے کوئی گمراہ کرنے والا نہیں اور جسے گمراہ کرتا ہے،اسے کوئی ہدایت دینے والا نہیں۔، میں گواہی دیتا ہوں کہ اللہ کے سوا کوئی حقیقی معبود نہیں۔ وہ تنہا ہے،کوئی اس کا شریک نہیں اور محمد اللہ کے بندے اور اس کے رسول ہیں \"۔\nضمادنے کہا: اپنے یہ کلمات دہرائیے تو رسول اللہ صلی اللہ علیہ وسلم نے انھیں تین بار دہرایا۔ضماد نے کہا: میں نے کاہنوں کی بات سنی ہے۔جادوگروں کی بات سنی ہے۔ شاعروں کی بات سنی ہے، مگر آپ کے ان کلمات کی طرح نہیں سنا ہے۔یہ (بلاغت میں ) سمندر کی تہہ تک پہنچے ہوئے ہیں۔پھرضماد نے کہا: اپنا ہاتھ لایے،تاکہ میں اسلام پر آپ سے بیعت کروں۔ضمادنے آپ کےہاتھ پر بیعت کی۔اس پرآپ نے فرمایا: کیا یہ بیعت اپنی قوم کی طرف سے بھی کر رہے ہو؟ اس نے کہا: اپنی قوم کی طرف سے بھی۔آپ نے ایک فوجی ٹولی(سریہ) بھیجا جس کاگزر ضماد کے قبیلے سے ہوا تو لشکرکے سردار نے لشکر سے کہا: کیا تم لوگوں نے ان کا کوئی سامان بھی لیا ہے؟قوم کے ایک آدمی نے کہا: میں نے ان کا طہارت حاصل کرنے کا ایک برتن لیا ہے، تو انھوں نے کہا: اسے لوٹا دو۔ اس لیے کہ یہ ضماد کی قوم ہے۔ (صحیح مسلم:۴۶/۸۶۸)\nابوذر رضی اللہ عنہ کے قبول اسلام کاواقعہ بھی کچھ ایسے ہی ہے،اس کےلیے ملاحظہ فرمائیں: (صحیح البخاری: ۷۳ا وصحیح مسلم: ۹۲۳ا/۴)\nقرآن اور اس کی تعلیم لوگوں کے دلوں میں گھر کررہی تھی اور مکہ کے کفار مختلف طریقوں سے لوگوں کو اس سے دور رکھنے کی کوشش کررہے تھے۔یہاں تک کہ جب ان کی کوئی چال کامیاب ہوتی نہ دکھائی دی تو انھوں نے نبی اکرم صلی اللہ علیہ وسلم اور آپ کے ساتھیوں کو جو اسلام قبول کرچکے تھے، ایذا پہنچانے کی ٹھان لی۔\nایک وقت ایسا آیا کہ آپ کعبہ کےپاس نماز ادا کر رہے تھے۔ مکہ کے کچھ کفار وہاں پہنچ گئے۔جب آپ سجدے میں گئے توانھوں نے اونٹ کی اوجھڑی اور اس کا خون وغیرہ آپ پر ڈال دیا،جس کی وجہ سے آپ سجدے سے نہیں اٹھ پارہے تھے۔اس کی اطلاع آپ کی چھوٹی صاحبزادی فاطمہ ڤ کو ہوئی تو وہ دوڑی ہوئی آئیں اور آپ کے اوپر سے گندگی کو صاف کیا۔نبی اکرم صلی اللہ علیہ وسلم کو اس سے بڑی تکلیف ہوئی، آپ نے نماز کے بعد قریش کو تین بار بدعا دی اور خاص طور سے عمروبن ہشام،عتبہ بن ربیعہ،ولید بن عتبہ،امیہ بن خلف،عقبہ بن ابی معیط اور عمارہ بن ولید کی تباہی و بربادی کی دعا دی۔\nعبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ بدر کے میدان میں میں نے ان سب کو قتل ہوتے ہوے دیکھا۔بعد میں ان سب کو ایک کنوئیں میں ڈال دیا گیا۔\nاسی طرح نبی اکرم صلی اللہ علیہ وسلم نے ان کو بت پر ستی اور شرک سے منع کیا۔ ایک اللہ کی عبادت کرنے کےلیے بلایا اور یہ بھی بتادیا کہ اگر تم نے میری بات نہیں مانی تو تمھیں سخت اور اذ یت ناک عذابوں سے دوچار ہونا پڑ ے گا۔\nکفار مکہ نبی اکرم صلی اللہ علیہ وسلم کو اور آپ کے کمزورساتھیوں کو مختلف طرح سے تکلیفیں پہنچاتے رہے،نئے مسلمانوں کو طرح طرح سے ستاتے رہے،جن کے حالات پڑ ھ کر رونگٹے کھڑے ہوجاتے ہیں۔کسی کو عرب کےتپتے ریگستانوں میں تیز دھوپ میں لٹادیتےاور سینے پر گرم پتھر رکھ دیتے۔کسی کے گلے میں لوہے کی گرم گرم سلاخیں ڈال دیتے۔بلال رضی اللہ عنہ کو تو بچوں کے حوالے کردیتے،جو گلے میں رسی ڈال کر مکہ کی گلیوں میں ان کوایسے گھماتے تھے جیسے کوئی بھیڑاور بکری لیے پھرتاہے۔یہ سب ہونے کے باوجود کسی نے بھی مذہب اسلام کو نہیں چھوڑا۔ نبی اکرم صلی اللہ علیہ وسلم آپ نے ساتھیوں کے ساتھ یہ برتاؤ دیکھ کر غمزدہ ہوتے تھے۔آخر میں آپ نے فیصلہ کیا کہ کچھ مسلمانوں کو حبشہ(ایتھوپیا)بھیج دیا جائے۔ کیوں کہ آپ نے وہاں کے بادشاہ نجاشی کے بارے میں سن رکھا تھا کہ وہ نیک خو اور انصاف پسند ہے۔\nلیکن مکہ کے اسلام مخالفین نے مکہ چھوڑنے والے مسلمانوں کا حبشہ تک تعاقب کیااور وہاں کے بادشاہ کو ان کے خلاف بھڑکایا۔بادشاہ نے مسلمانوں کو اپنے دربار میں بلایا اور ان سے مختلف طرح کے سوالات پوچھے۔ایک سوال یہ بھی تھا کہ تم لوگ عیسیٰ علیہ السلام کے بارے میں کیا خیال رکھتے ہو؟ مہاجروں نے جعفر بن ابو طالب کو اپنا نمایندہ بنایا۔انھوں نے سورہ مریم تلاوت کر کے سنائی، جس میں بتایا گیاہے کہ عیسیٰ علیہ السلام اللہ کے بندے ہیں۔انھوں نے لوگوں کو اللہ ہی کی عبادت کرنے کا پیغام دیا۔اس میں اس بات کی تردید کی گئی ہے کہ اللہ نے کسی کو اپنا بیٹا بنایا ہے۔اس کے علاوہ بھی آپ نے اسلام کی تعلیم مختصراً پیش کی۔یہ سن کربادشاہ نجاشی رو پڑ ا،یہاں تک کہ اس کی داڑھی آنسوؤں سے ترہو گئی اور اس کے پاس جو پادری بیٹھے تھے وہ بھی روپڑ ے۔پھر نجاشی نے کہا:اللہ کی قسم!یہ روشنی اسی شمع سے نکلی ہےجس کو لےکر موسیٰ علیہ السلام آئے تھے۔تم میری سلطنت میں اطمینان سےرہو، تمھیں یہاں کسی طرح کی پر یشانی نہیں ہوگی۔صحیح حدیثوں سے یہ بھی معلوم ہوتا ہے کہ خود بادشاہ نجاشی نے بھی خفیہ طریقے سے اسلام قبول کر لیا اورمحمد صلی اللہ علیہ وسلم کے نبی ہونے کی تصدیق کی۔\nجب حبشہ سے مسلمانوں کو واپس لانے میں کفار مکہ ناکام رہے تو انھوں نے ایک اور چال چلی۔ انھوں نے بنو ہاشم سےکہہ دیا کہ جب تک تم محمدکا قتل نہیں کردیتے یا ان کو ہمارے سپر د نہیں کردیتے تمھارا ہر طرح سے معاشرتی بائیکاٹ کیا جائے گا۔یہ بڑا ہی دشوار کن مرحلہ تھا،مگر بنو ہاشم نے آپ کو نہیں چھوڑا۔آپ کے چچا ابوطالب بنو ہاشم کو لےکر ایک گھاٹی میں چلے گئے،جہاں وہ بکریاں چراکر اپنی زندگی گذارتے تھے۔کھانے پینے کی کوئی چیز ان کو میسر نہیں تھی۔صحیح حدیثوں میں آیا ہے کہ وہاں انھیں درخت کے پتے بھی چبانے پڑ ے تھے۔تین سال تک وہ اس سماجی بائیکاٹ کا شکار رہے۔قرآن نازل ہورہاتھا اور اللہ تعالیٰ مسلمانوں کو پورے صبر و تحمل کے ساتھ ان پر یشانیوں کو برداشت کرنے کا حکم دےرہاتھا۔تین سال گزرجانے کے بعد خود مکہ والوں میں پھوٹ پڑ گئی اور انھوں نے خود ہی اس سماجی بائیکاٹ کوختم کردیا۔نبی اکرم صلی اللہ علیہ وسلم نے ایک بارمکہ والوں کو بددعا بھی دی جس کی وجہ سے ایسی خشک سالی پڑ ی کہ لوگوں کو مردار کھانا پڑ ا۔ابو سفیان جو مکہ کے سرداروں میں سے تھے اور اس وقت تک مسلمان نہیں ہوے تھے، نبی اکرم صلی اللہ علیہ وسلم کے پاس بھاگتے ہوے آئے اور آپ سے خشک سالی ختم ہونے کی دعا کرائی۔آپ کی دعا سے خشک سالی ختم ہوگئی اور آسمان میں جو دھواں دکھائی دے رہاتھا، جس کو دیکھ کر مکہ والے خوفزدہ ہورہے تھے۔ وہ چھٹ گیا۔لیکن وہ پھر بھی مسلمان نہیں ہوے۔\nابو طالب کی وفات:\nسماجی بائیکاٹ ختم ہونے کے کچھ دنوں بعدآپ کے چچاابوطالب کی وفات ہوگئی۔وہ آپ کے بہت بڑے ہمدرداور مدد گارتھے۔ابوطالب کی وجہ سے کفارمکہ آپ کو کسی طرح کا نقصان پہنچانے سے بچتے تھے۔لیکن ان کی وفات کے بعد اب وہ آزاد ہوگئے تھے اور اب تو اورمزیدآپ کو اور آپ کے ساتھیوں کو ستانے لگے۔\n§ام المومنین خدیجہ ڤ کی وفات:\nچچا ابو طالب کی وفات کے کچھ عرصے کے بعد خدیجہ ڤ کی بھی وفات ہوگئی۔اہلیہ کی وفات سے آپ بہت زیادہ غمزدہ ہوگئے۔چچااوراہلیہ کی موت کی وجہ سے اس سال کو غم کا سال کہاگیا۔\nمکہ سے باہر اسلام کی اشاعت:\nجب محمد صلی اللہ علیہ وسلم نے دیکھا کہ مکہ والے آپ کے تئیں زیادہ سخت ہوگئے ہیں تو آپ نے مکہ سے باہر اسلام کی تبلیغ کا پر وگرام بنایا اورمکہ سےجنوب سب سے نزدیک شہر طائف چلے گئے، جہاں بنوثقیف کا قبیلہ آباد تھا۔آپ نے ان کو اسلام کا پیغام سنایا۔لیکن انھوں نے آپ کو پتھر مارے،جس کی وجہ سے آپ کے پاؤں سے خون بہنے لگا۔آپ بہت غمزدہ ہوے۔یہاں تک کہ اللہ تعالیٰ کی جانب سے یہ پیغام آیا کہ اگر آپ کہیں تو پہاڑ چلنے لگیں اور مکہ والوں اور اس کے قرب و جوار میں رہنے والوں کو کچل کر رکھ دیں۔ لیکن آپ کے دل میں ان لوگوں سے بدلہ لینے کا کوئی جذبہ نہیں تھا۔بلکہ آپ نے دعا کی اے اللہ!ان کو صحیح راستا دکھا۔صحیحین کی حدیث سے یہ بھی معلوم ہوتا ہے کہ آپ نے کہا: (اے اللہ)مجھے یقین ہے کہ ان کی اولاد میں سے ایسے لوگ پیدا ہوں گے جو صرف تیری ہی عبادت کریں گے اور کسی بھی طرح کا شرک نہیں کریں گے۔ (صحیح البخاری: ۳۲۳۱، و کتب سیرت)\nطائف میں دس دن گزارنے کے بعد آپ مکہ واپس لوٹ آئے۔اللہ نے آپ کواطمینان قلب کےلیےساتوں آسمان کا سفر کرایا۔وہ اس طرح کہ آپ کو مکہ سے پہلے بیت المقدس لے جایا گیا۔پھر وہاں سے آپ کو آسمان کی سیر کرائی گئی۔آپ نے اس سفر میں بہت کچھ دیکھا۔(مزید تفصیل کے لیے ملاحظہ فرمائیں: سورہ بنی اسرائیل، نیز دیکھیں: صحیح البخاری: ۳۲۰۷، صحیح مسلم: ۶۴ا)\nاسی سفرمعراج میں مسلمانوں پر پانچ وقت کی نماز فرض کی گئی۔آپ نے جنت و جہنم کو دیکھا۔ آپ سے پوچھا گیا :کیا آپ نے اللہ کو بھی دیکھا ہے؟جواب دیا:وہ تو ایک نور ہے۔اسے کیسے دیکھا جاسکتاہے؟ یعنی اللہ تعالیٰ نے اس سفر کے ذریعےنبی اکرم صلی اللہ علیہ وسلم کو وہ سب کچھ دکھا دیا جو ہماری آنکھوں سے اوجھل ہیں۔جس سے آپ کا دل خوشی سے جھوم اٹھااورآپ زیادہ استقامت کے ساتھ اسلام کی تبلیغ و اشاعت میں مصروف ہوگئے۔ (سفرمعراج کے لیے دیکھیے: اسراء)\n§مدینہ میں اسلام کی دعوت:\nیوں تو اسلام کا چرچا مدینہ میں پہنچ چکا تھا۔لیکن نبی اکرم صلی اللہ علیہ وسلم حج کےموقع پر مکہ آنے والے قبائل کے سرداروں سےملتےاوران تک اسلام کا پیغام پہنچاتے۔نبوت کے دسویں سال میں آپ نے عقبہ نامی مقام پر مدینہ سے آئے ہوے حاجیوں سے ملاقات کی۔ان کو اسلام کا پیغام سنایا،جس کو سن کر وہ لوگ مسلمان ہوگئے۔کیوں کہ انھوں نے مدینہ کے یہودیوں سے سن رکھا تھا کہ آخری نبی آنے والا ہے۔جب انھوں نے نبی اکرم صلی اللہ علیہ وسلم کی باتیں سنیں تو ان کو یقین ہوگیا کہ آپ وہی نبی ہیں، جن کے بارے میں یہودی بتایا کرتے تھے۔دوسرے سال آپ نے پھر حج کے موقع پر حاجیوں کے سامنے اسلام کا پیغام پیش کیا۔اس بار مدینہ سے۷۲افراد حج پر آئے تھے وہ سب مسلمان ہوگئے اورانھوں نے ہر طرح سےآپ کی تائیداورتحفظ کاوعدہ کیا اور مدینہ واپس چلے گئے۔جہاں ان لوگوں نے اسلام کی تبلیغ شروع کردی اور نبی اکرم صلی اللہ علیہ وسلم کے مدینہ آنے کاانتظار کرنے لگے۔لیکن آپ اپنی ہجرت کے سلسلےمیں اللہ تعالیٰ کےحکم کے منتظرتھے۔ ابوموسیٰ اشعری کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں نے خواب میں دیکھا کہ میں مکہ سے ایسے مقام پر ہجرت کرکے جارہا ہوں، جو کھجوروں کے باغات سے بھرا ہوا ہے۔میں نےسوچاکہ شاید یہ یمامہ (ریاض،نجد) یا ہجر(احساء) نام کا مقام ہے، پھر دیکھا تو یہ یثرب (مدینہ کا قدیم نام)ہے\"۔ (صحیح البخاری: ۳۶۲۲ وصحیح مسلم: ۲۲۷۲/۲۰)\nکفار مکہ کے پیٹ میں درد ہونے لگا کہ کہیں ایسا نہ ہوکہ مکہ سے باہر محمد صلی اللہ علیہ وسلم کے ماننے والوں کی تعداد بڑھ جائے اور بعد میں ہمارے لیے مسئلہ بن جائے۔ اس لیے انھوں نے یہ طریقہ سوچا کہ کیوں نہ محمدہی کاخاتمہ کردیاجائے۔اس لیےقریش کے سارے خاندان جیسے بنی نوفل،بنی عبد شمس،بنی عبدالدار، بنی اسعد، بنی مخزوم،بنی سہم اور بنی جمح دارالندوة میں اکٹھا ہوے۔یہ فیصلہ کیا گیا کہ ہر خاندان سےایک ایک نوجوان لیا جائے۔انھیں چمکتی ہوئی تلوار تھمادی جائے اور صبح ہوتے ہی تمام جوان محمدپر ٹوٹ پڑ یں اور ان کو قتل کردیں۔اس طرح ہم ان سےنجات پاجائیں گےاور بنو ہاشم ہم سے بدلہ نہیں لے پائیں گے۔ہم سب مل کر ان کو اس قتل کے تاوان میں کچھ مال دے دیں گے۔اللہ تعالیٰ نے ان کی اس سازش کی اطلاع نبی اکرم صلی اللہ علیہ وسلم کو دےدی۔قرآن کریم میں اس واقعے کاتذکرہ اس طرح آیاہے: ﴿وَإِذۡ يَمۡكُرُ بِكَ ٱلَّذِينَ كَفَرُواْ لِيُثۡبِتُوكَ أَوۡ يَقۡتُلُوكَ أَوۡ يُخۡرِجُوكَۚ وَيَمۡكُرُونَ وَيَمۡكُرُ ٱللَّهُۖ وَٱللَّهُ خَيۡرُ ٱلۡمَٰكِرِينَ﴾ [الأنفال: ۳۰] \"اور(وہ وقت یاد کرو)جب کفار تمھارے ساتھ چالیں چل رہے تھے کہ تم کو قید کریں، یا تمھیں قتل کردیں،یا تمھیں شہر سے باہرنکال دیں۔وہ اپنی چال چل رہے تھے اوراللہ اپنی چال چل رہا تھا اور اللہ سب سے بہترین چال چلنے والا ہے\"۔\nآپ کو حکم دیا گیا کہ آپ بھی مدینہ ہجرت کرجائیں۔آپ نے علی رضی اللہ عنہ کو بلایااور کفار مکہ کی جو امانتیں آپ کے پاس تھیں ان کو علی رضی اللہ عنہ کے حوالے کیا اور حکم دیا کہ میرے جانے کے بعد ان کے مالکوں تک پہنچا کر تم بھی مدینہ آجانا۔آپ نے علی رضی اللہ عنہ کو اپنے بستر پر لٹادیا اور سورہ یٰسین تلاوت کرتے ہوے گھر سے باہر نکل گئے۔جب آیت: ﴿وَجَعَلۡنَا مِنۢ بَيۡنِ أَيۡدِيهِمۡ سَدࣰّ ا وَمِنۡ خَلۡفِهِمۡ سَدࣰّ ا فَأَغۡشَيۡنَٰهُمۡ فَهُمۡ لَا يُبۡصِرُونَ﴾ [یس: ۹] \"اور ہم نے ان کے آگے ایک دیوار کھڑی کردی اور ایک دیوار ان کےپیچھے۔پھر ان پر پر دہ ڈال دیا جس کی وجہ سے ان کو کچھ دکھائی نہیں دیتا\" تو دیکھاکہ کفار جو آپ کو قتل کرنے کےلیے آپ کے دروازہ پر اکٹھا ہوے تھے اونگھ رہے تھے۔\nآپ نے ایک مٹھی مٹی اٹھاکران کی طرف پھینک دی۔پھر وہ نیند سے نہیں اٹھ سکے۔جب آپ وہاں سے نکل گئے تو کسی نے آکر ان لوگوں کو بتایا کہ محمد صلی اللہ علیہ وسلم تو نکل گئے۔ یہ لوگ گھر کے اندر داخل ہوے تو دیکھا کہ وہاں علی رضی اللہ عنہ سورہے ہیں۔آپ ابو بکر رضی اللہ عنہ کے گھر گئے اور وہاں سے دونوں مدینہ کےلیے نکل پڑ ے۔یہ۲۰جون۶۲۲م،پیر کادن تھا۔اسی روز سے(عمر رضی اللہ عنہ کے زمانے میں) مسلمانوں نے اپنا ہجری کیلنڈر شروع کیا۔\nجب کفار مکہ کو آپ کے بچ کر نکل جانےکی خبر ملی تو وہ آپ کی تلاش میں لگ گئے۔ آپ ان سے بچنے کےلیے غار ثور نامی پہاڑ میں چھپ گئے۔کفار مکہ آپ دونوں کو تلاش کرتے ہوے اس غار تک پہنچ گئے، لیکن یہ دیکھ کر کہ غار کے منہ پر تومکڑی نے جالا لگا رکھا ہے وہ واپس لوٹ گئے۔ (مسند احمد۳۴۸/ا)\nیہ آپ صلی اللہ علیہ وسلم کی حفاظت کےلیے ایک معجزہ تھا،جس کی وجہ سے کفار آپ کو غار میں تلاش کیے بغیر لوٹ گئے۔ اس طرح دونوں (نبی اکرم صلی اللہ علیہ وسلم اور ابوبکر رضی اللہ عنہ ) غار میں تین دن تک چھپے رہے۔ اس دوران وہ لمحہ بھی آیا جب دشمن غار کے دہانے تک پہنچ گئے۔ ابوبکر رضی اللہ عنہ کہتے ہیں: میں نے گھبرا کرکہا: اے اللہ کےنبی! «لَوْ أَنَّ أَحَدَهُمْ نَظَرَ تَحْتَ قَدَمَيْهِ لأَبْصَرَنَا، فَقَالَ: مَا ظَنُّکَ يَا أَبَا بَکْرٍ بِاثْنَيْنِ اللَّهُ ثَالِثُهُمَا؟». (صحیح البخاری: ۳۶۵۳ وصحیح مسلم: ۲۳۸۱/۱) \" اگر یہ لوگ اپنے پیروں کے نیچے غار میں جھانکیں گے تو ہم دیکھ لیے جائیں گے۔ نبی اکرم صلی اللہ علیہ وسلم نے کہا: ابوبکر! ہم دو ہی نہیں ہیں، بلکہ ہمارے ساتھ ہمارا اللہ بھی ہے\"۔\nقرآن کریم کی سورہ التوبہ کی آیت ۴۰میں بھی اس کا تذکرہ اس طرح آیا ہے:﴿إِلَّا تَنصُرُوهُ فَقَدۡ نَصَرَهُ ٱللَّهُ إِذۡ أَخۡرَجَهُ ٱلَّذِينَ كَفَرُواْ ثَانِيَ ٱثۡنَيۡنِ إِذۡ هُمَا فِي ٱلۡغَارِ إِذۡ يَقُولُ لِصَٰحِبِهِۦ لَا تَحۡزَنۡ إِنَّ ٱللَّهَ مَعَنَاۖ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيۡهِ وَأَيَّدَهُۥ بِجُنُودࣲ لَّمۡ تَرَوۡهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُواْ ٱلسُّفۡلَىٰۗ وَكَلِمَةُ ٱللَّهِ هِيَ ٱلۡعُلۡيَاۗ وَٱللَّهُ عَزِيزٌ حَكِيمٌ﴾ [التوبة: ۴۰] \"اگر تم اس کی مدد نہ بھی کروگے تو(اس کا کچھ بھی نہیں بگڑے گا)اللہ نے اس کی مدد اس وقت کی، جب دشمنان اسلام نے اسے نکال دیا تھا۔وہ دو میں سےایک تھا (دوسرے ابوبکر تھے)۔ جب وہ دونوں غار میں تھے، جب وہ آپ نے ساتھی سے کہہ رہاتھا: فکر مت کرو، اللہ ہمارے ساتھ ہے، تو اللہ نے اس پر اپنی جانب سے اطمینان نازل فرمایا اور اس کی مدد ایسی افواج سے کی جنھیں تم نے دیکھا نہیں اور کفر کرنے والوں کو نیچا کردیا اور اللہ کی بات اونچی رکھی اور اللہ عزیزوحکیم(نہایت ہی طاقتور اور حکمت والا) ہے\"۔\nجب قریش کو پورا یقین ہوگیا کہ محمد صلی اللہ علیہ وسلم اپنے ساتھی ابوبکر رضی اللہ عنہ کےساتھ مکہ سے نکلنے میں کامیاب ہوگئے تو انھوں نے اعلان کردیا کہ جو کوئی ان دونوں کو قتل کردے گایا زندہ پکڑ لائے گا اس کو سواونٹ انعام میں دیے جائیں گے۔یہ سن کر ایک دشمن سراقہ بن مالک آپ کو پکڑنے کےلیے نکل پڑا۔ جب وہ ان دونوں کے قریب پہنچا تو اس کے گھوڑے کے آگے کے دونوں پاؤں زمین میں دھنس گئے، جس سے وہ زمین پر گر پڑا۔پھر وہ اٹھ کرچلایا:میں سراقہ بن مالک ہوں۔میں آپ کو کوئی نقصان نہیں پہنچانا چاہتا، نہ آپ کا برا چاہتاہوں۔ کیوں کہ مجھے معلوم ہوگیا ہے کہ محمد صلی اللہ علیہ وسلم کا مذہب پهیل کر رہےگا۔نبی اکرم صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ سے کہا: اس سے پوچھو کیا چاہتا ہے؟ جب ابوبکر رضی اللہ عنہ نے اس سےپوچھا تو اس نے کہا:مجھے آپ لکھ کر دے دیں۔نبی اکرم صلی اللہ علیہ وسلم نے ابوبکر رضی اللہ عنہ سے فرمایاکہ لکھ کردے دو۔تو انھوں نے اسے سلامتی اور امان نامہ لکھ کردے دیا،جسے لےکر وہ واپس چلا گیا۔ (صحیح البخاری: ۳۹۰۶)\nپھر جب نبی اکرم صلی اللہ علیہ وسلم حنین اور طائف کی جنگی مہم سے واپس آرہے تھے تو سراقہ نے وہ تحریر مسلمانوں کو دکھائی اور اسلام قبول کر لیا۔\nمدینہ والوں کو پتا چل گیا تھا کہ نبی اکرم صلی اللہ علیہ وسلم مکہ سے نکل چکے ہیں۔اس لیے وہ روزانہ مدینہ سے باہر آپ کا انتظار کرتے اور جب دھوپ تیز ہوجاتی تو واپس لوٹ جاتے۔ایک دن ایسا ہوا کہ جب سب لوگ اپنے گھروں میں چلے گئے تو اللہ کے نبی صلی اللہ علیہ وسلم قبا میں داخل ہوے۔وہاں چودہ دن قیام فرمایا۔ اسلام کی سب سے پہلی مسجد آپ نے یہیں تعمیر کرائی جس کا ذکر قرآن مجیدمیں بھی آیا ہے۔(سورہ التوبہ:۰۸ا)\n§مدنی دور:\nنبوت کے تیرہ سال بعد۵۳سال کی عمر میں آپ صلی اللہ علیہ وسلم مدینہ پہنچے۔مدینہ کا ہرشخص خواہش مند تھا کہ آپ اس کےیہاں اقامت فرمائیں۔آپ کےلیے یہ فیصلہ کرنا مشکل ہوگیا کہ کس کی دعوت کو قبول کریں اور کس کی نامنظور کردیں۔اس لیے آپ نے فرمایا: میری اونٹنی کو چھوڑ دو۔یہ اللہ کے حکم سے جہاں بیٹھ جائے گی،میں وہیں قیام کروں گا۔ (ابن ہشام:۴۹۵/ا لبدایہ والنہایہ:۲۰۰/۳)\nاونٹنی گھومتی ہوئی ابوایوب انصاری رضی اللہ عنہ کے دروازہ پر رک گئی۔ آپ اس سے اترے اور وہاں ٹھہر گئے۔وہاں ایک کھلیان تھا، جہاں لوگ کھجوریں خشک کیا کرتے تھے۔ آپ نے پوچھا: یہ کھلیان کس کا ہے؟ بتایا گیا کہ بنو نجار کے دو یتیم بچوں کا ہے۔آپ نے اس زمین کو خرید کر وہاں مسجد بنانے کا حکم دیااور مسلمانوں کے ساتھ خود بھی مسجد کی تعمیر میں ہاتھ بٹایا۔مدینہ والوں نے مکہ سے آنے والے مہاجرین کی پوری مدد کی،جس کی وجہ سے ان کا نام انصار(مدد گار) پڑ گیا۔\nآپ نے مہاجروں کی پر یشانیاں اس طرح دور فرمائی کہ مکہ سے آنے والوں کو مدینہ والوں کو سونپ دیا اور کہا:جاؤ آج سے تم دونوں بھائی بھائی ہو۔مدینہ والے انصارکہلائے اور مکہ والے مہاجر(اللہ کی راہ میں گھر بار چھوڑنے والے) کہلائے۔ انصار نے بڑی خوش دلی سے انھیں اپنا بھائی بنا لیا۔وہ انھیں اپنےاپنے گھر لے گئے اور اپنا گھر،سامان اور کھجور کےکھیت سب کا نصف اپنے مہاجر بھائی کو سونپنے کےلیے تیار ہوگئے۔تاریخ میں یہ بھی درج ہےکہ انس بن مالک رضی اللہ عنہ کہتے ہیں:\"رسول اللہ نے قریش اور انصار کے درمیان بھائی چارہ کروایا۔ اس سلسلے میں سعد بن ربیع اور عبدالرحمن بن عوف کے درمیان مواخات کرائی، سعد بن ربیع کی دو بیویاں تھیں، انھوں نے اپنے مہاجر بھائی سے کہا کہ ان دونوں میں سے تمھیں جو پسند ہو میں اسے طلاق دیتا ہوں، تم اس سے شادی کرلو۔ لیکن عبدالرحمن نے دعا دےکر کہاکہ مجھے تو تم بس بازار کا راستا دکھادو اور پھر وہ تجارت کرنے لگے۔بعد میں انھوں نے اپنی کمائی سےایک انصاری خاتون سے شادی کرلی\"۔(صحیح البخاری: ۵۰۷۲)\nنبی اکرم صلی اللہ علیہ وسلم نے جب ان کے جسم پر زعفرانی رنگ دیکھا تو پوچھا: یہ کیاہے؟ جواب دیا: ایک انصاری خاتون سے شادی کی ہے۔آپ نے فرمایا: پھر تو تم کو ولیمہ کرنا چاہیے،خواہ وہ ایک بکری ہی کیوں نہ ہو۔\nاس طرح انصار نے ایک ایسا نمونہ پیش کیا جو ہر دور کے لوگوں کےلیےمشعل راہ ہے۔قرآن نے اس کی ستایش اس طرح کی ہے:﴿وَٱلَّذِينَ تَبَوَّءُو ٱلدَّارَ وَٱلۡإِيمَٰنَ مِن قَبۡلِهِمۡ يُحِبُّونَ مَنۡ هَاجَرَ إِلَيۡهِمۡ وَلَا يَجِدُونَ فِي صُدُورِهِمۡ حَاجَةࣰ مِّمَّآ أُوتُواْ وَيُؤۡثِرُونَ عَلَىٰٓ أَنفُسِهِمۡ وَلَوۡ كَانَ بِهِمۡ خَصَاصَةࣱۚ وَمَن يُوقَ شُحَّ نَفۡسِهِۦ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ﴾ [الحشر: ۹] \"جو لوگ ان سے پہلے سے اس گھر(مدینہ)میں آباد ہیں اور ایمان رکھتے ہیں، وہ ان سے محبت کرتے ہیں، جو ہجرت کرکے ان کے یہاں آئے اور اپنے دلوں میں اس سے کوئی کھٹک نہیں پاتے جو کچھ ان کو دیا جائے اور انھیں خود پر ترجیح دیتے ہیں، خواہ خود انھیں ضرورت کیوں نہ ہو اورجو دل کی لالچ اور بخل سے بچا لیے جائیں وہی کامیابی حاصل کرنے والے ہیں\"۔\nمہاجر بھائی بھی لالچی نہیں تھے۔انھوں نے ان کے برتاؤاور حسن سلوک کا بہتر بدلہ دیا۔\n§مدینہ کے یہودیوں کے ساتھ معاہدہ:\nمدینہ میں عرب اور یہودی قبائل آباد تھے۔اسلام عربوں میں بڑی تیزی سے پهیل رہاتھا۔بلکہ اگر یہ کہا جائے تو زیادہ صحیح ہے کہ کوئی ایسا گھر نہیں تھا جس میں کوئی شخص مسلمان نہ ہوگیا ہو۔\nاب یہ خوف بھی تھاکہ کفار مکہ عرب کے دوسرے لوگوں کو نبی اکرم صلی اللہ علیہ وسلم اور مسلمانوں کے خلاف بھڑکاکر جنگ نہ چھیڑ دیں۔اس لیے نبی اکرم صلی اللہ علیہ وسلم نے مدینہ کے یہودیوں کے ساتھ ایک معاہدہ کیا،وہ یہ کہ خارجی حملہ کی صورت میں وہ مسلمانوں کی مدد کریں گے اور اسلام کی بڑھتی ہوئی طاقت سے ان کو کوئی نقصان نہیں پہنچے گا۔ اگر مدینہ پرکسی نے چڑھائی کی تو مسلمان ان کی حفاظت کریں گے۔\n§غزوۂ بدر:\nبدراس مقام کا نام ہےجومدینہ سے ۸۰میل جنوب مغرب کی جانب ہے۔مسلمانوں اور کفار کے درمیان پہلی لڑائی اسی مقام پر سن ۲ھ کو ہوئی۔کفار مکہ نے اسلام اور مسلمانوں کو ختم کرنے کےلیے ایک بڑی فوج تیاری کی۔ نبی اکرم صلی اللہ علیہ وسلم (۳۱۳)صحابہ کی مختصرفوج کولے کردشمن سے مقابلے کے لیے آگے بڑھے۔بدرمیں دونوں فوجوں میں مقابلہ ہوا،جس میں مسلمانوں کو قریش کے مقابلے میں شان دارفتح حاصل ہوئی اور دشمن کوبھاری جانی اور مالی نقصان اٹھانا پڑا۔جہاں اس لڑائی نےقریش کوحواس باختہ کردیااوران کی مسلمانوں کے خلاف سرگرمیاں پہلے سےتیز ہوگئیں،دوسرے عرب قبائل کوبھی چوکنا کردیااور اسلام کی بڑھتی ہوئی طاقت سے لوگ حیران وپریشان ہوگئےاور اپنے لیے اسے حقیقی خطرہ محسوس کرنے لگے۔\n§غزوۂ اُحد:\nاُحد، مدینہ کے نزدیک ایک پہاڑی کا نام ہے۔اس جنگ کی وجہ مشرکین مکہ کی یہ بدقسمتی تھی کہ بدر میں ان کےجوسترآدمی مارے گئے تھے اور جن میں ان کےبڑے بڑےسرداربھی تھے،ان کابدلہ لینے کے لیے سن ۳ھ میں انھوں نے مدینہ پر حملے کے ارادے سےپیش قدمی کی۔ان کےلشکرنے اُحدکے قریب آکرپڑاؤ ڈالا۔ان سے مقابلے کے لیےنبی اکرم صلی اللہ علیہ وسلم مسلمانوں کی فوج لے کرآگے بڑھے اور وہاں پرلڑائی ہوئی۔اس لڑائی میں مسلمانوں کو بہت زیادہ نقصان ہوا۔خود نبی اکرم صلی اللہ علیہ وسلم بھی زخمی ہوے۔لیکن کفارواپس چلے گئے اورمدینہ میں محفوظ رہا۔\nنبی اکرم صلی اللہ علیہ وسلم ۰ا سال تک مدینہ میں رہے۔اس درمیان آپ کو کئی لڑائیاں لڑنی پڑ یں جن میں بدر، احد،خندق،حدیبیہ،خیبر،فتح مکہ،حنین اور تبوک کی جنگیں مشہور ہیں۔ہجرت کے دسویں سال آپ نےفریضۂ حج ادا کیا۔آپ کے ساتھ ایک لاکھ سےاوپر مسلمانوں نےحج کیا۔آپ نے۹ذی الحجہ کو میدان عرفات میں ایک تاریخی خطبہ دیا، جس میں آپ نے نہایت اہم احکام وفرامین جاری فرمائے۔ ان میں سے کچھ یہ ہیں :\n۱-عربی اور غیر عربی(جن کو عجمی کہتے ہیں )میں کوئی فرق وامتیاز نہیں۔ ہم سب ایک آدم کی اولاد ہیں۔ آدم کو اللہ تعالی نے مٹی سے بنایا۔امتیازی حیثیت کی بنیادتقویٰ ہے۔\n۲-مسلمان آپس میں بھائی بھائی ہیں۔\n۳-اپنے غلاموں کے ساتھ اچھا برتاؤ کرو۔ جو خود کھاؤ وہی ان کو کھلاؤ۔ جو خود پہنو وہی ان کو بھی پہناؤ۔\n۴-عورتوں سےبرتاؤ کے بارے میں اللہ تعالیٰ سے ڈرو۔تمھارا ان پر اور ان کا تم پر حق ہے۔\n۵-میں تمھارے لیے دو چیزیں چھوڑے جا رہا ہوں۔تم ان کو مضبوطی کےساتھ پکڑے رہو گے تو کبھی بھی صحیح راستےسےنہیں بھٹکوگے۔ان میں سے ایک اللہ کی کتاب قرآن اور دوسری نبی کی سنت ہے۔\nپھر آپ نےلوگوں سے خطاب کر کے فرمایا: تم سے اللہ تعالیٰ کےیہاں میرے بارے میں پوچھا جائےگا تو کیا کہوگے؟لوگوں نے جواب دیا: ہم یہی کہیں گے کہ آپ نے اللہ تعالیٰ کا پیغام ہم تک پہنچا دیا۔پھر آپ نے آسمان کی جانب انگلی اٹھا کرفرمایا:اے اللہ!تو گواہ رہنا۔اللہ نے آپ کو جس کام کےلیے منتخب فرمایا تھا اسے آپ نے پورا فرمادیا۔ آپ کا لایا ہوا مذہب جزیرۂ نما عرب سے نکل کر قریبی ممالک میں پهیل گیا اور اللہ تعالیٰ نے بھی مذہب اسلام کےمکمل ہونے کا اعلان فرمادیا: ﴿ٱلۡيَوۡمَ أَكۡمَلۡتُ لَكُمۡ دِينَكُمۡ وَأَتۡمَمۡتُ عَلَيۡكُمۡ نِعۡمَتِي وَرَضِيتُ لَكُمُ ٱلۡإِسۡلَٰمَ دِينࣰ اۚ﴾ [المائدة: ۳] \"آج میں نے تمھارے لیے تمھارا دین مکمل کردیااور تم پر اپنی نعمت پوری کردی اور میں نے تمھارے لیے دین اسلام کو پسند کیا\"۔\nاس آیت کے نزول سے کچھ لوگوں کو یقین ہوگیا کہ اب آپ ہم سے وداع فرمانے والے ہیں (دیکھئے: تفسیر البغوی) اور ایسا ہی ہوا۔حج سے آنے کے بعد آپ بیمار ہوگئے۔۲ا ربیع الاول ااھ مطابق سن ۶۴۲ء کو آپ کی ام المومنین عائشہ کےگھرمیں وفات ہوئی۔وہیں پرآپ کو دفن کیا گیا۔\nآپ کی وفات سےپہلےپورا قرآن لکھا جاچکا تھا۔ بہت سےمسلمانوں نے اسے حفظ بھی کرلیا تھا۔ قرآن اس وقت ہمارے سامنے جس شکل میں موجود ہے یہ وہی ہے جس کو نبی اکرم صلی اللہ علیہ وسلم چھوڑکر گئے تھے۔آج بھی دنیا بھر میں لاکھوں مسلمان ہیں جن کو قرآن حفظ ہے۔\nاب آیئے اختصار کے ساتھ یہ معلوم کریں کہ کہ قرآن کریم آپ کے بارے میں کیا کہتا ہے:\n۱-آپ کو اللہ نے رسول بنا کر بھیجا:﴿هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ وَلَوۡ كَرِهَ ٱلۡمُشۡرِكُونَ﴾ [الصف: ۹] \"وہی ہے جس نے آپ نے رسول محمدکو صحیح رہنمائی اور صحیح دین کے ساتھ بھیجا تاکہ وہ اسے دوسرے دین پر فوقیت دے، خواہ مشرکوں کو کتنا ہی برا کیوں نہ لگے\"۔\nنیزفرمایا:﴿إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرࣰ ا وَنَذِيرࣰ اۖ وَلَا تُسۡـَٔلُ عَنۡ أَصۡحَٰبِ ٱلۡجَحِيمِ﴾ [البقرة: ۱۱۹] \"ہم نے تمھیں سچے دین کے ساتھ(مومنون کےلیے) خوش خبری دینے والا (انکار کرنے والوں کےلیے) ڈرانےوالا بنا کر بھیجا ہے۔ اور تم سے بھڑکتی ہوئی آگ والوں ( جہنمی لوگوں ) کے بارے میں کچھ بھی نہیں پوچھا جائے گا\"۔\nمزیدفرمایا:﴿إِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولࣰ ا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولࣰ ا﴾ [المزمل: ۱۵] \"ہم نے تمھاری طرف ایک رسول بھیجا جو تم پر گواہ ہوگا جیسا کہ ہم نے فرعون کی طرف ایک رسول بھیجا تھا\"۔\n۲-محمد صلی اللہ علیہ وسلم آخری نبی بنا کر بھیجے گئے ہیں۔اس لیے آپ کے بعد کوئی نبی نہیں آئے گا۔اب قیامت تک دنیا کی فلاح کا ایک ہی ذریعے آپ پر ایمان لانا اور آپ کے احکام پر عمل کرنا ہے،کیوں کہ اللہ نے پوری دنیا کےلیے آپ کو آخری رسول بنا کر بھیجا ہے۔قرآن کریم میں ہے: ﴿مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدࣲ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمࣰ ا﴾ [الأحزاب: ۴۰] \"محمد تمھارے مردوں میں سے کسی کے باپ نہیں ہیں، لیکن وہ اللہ کے رسول اورنبیوں کے خاتم ہیں اور اللہ ہر چیز کا علم رکھنے والا ہے\"۔\nقرآن نے ’خاتم‘لفظ استعمال کیا ہے، جس کے معنیٰ مہر(seal) کےبھی ہوتے ہیں اور آخری بھی۔ اس طرح آپ آخری نبی ہیں اور آپ کےجانے کے بعد اللہ نے نبیوں کے سلسلے پرمہر لگادی۔اس لیے اب کوئی نبی نہیں آئے گا۔نبی اکرم صلی اللہ علیہ وسلم نے اس کا اعلان کردیا کہ میرے بعد کوئی نبی نہیں آئے گا۔\n۳-اللہ تعالیٰ نے آپ کےاعلیٰ کردار کی تعریف فرمائی ہے۔آپ نبوت سے پہلے اپنی قوم میں امین (امانت دار) کہلاتے تھے۔نبوت کے بعد آپ کے کردار میں مزید بلندی آئی۔ قرآن کریم آپ کےبارے میں بیوقوف کافروں کےاس پروپیکنڈے کی تردیدکرتاہےکہ آپ آسیب زدہ تھے۔ ساتھ ہی آپ کےاعلیٰ کرداراور بلنداخلاق کی بھی شہادت دیتاہے: ﴿نٓۚ وَٱلۡقَلَمِ وَمَا يَسۡطُرُونَ مَآ أَنتَ بِنِعۡمَةِ رَبِّكَ بِمَجۡنُونࣲ وَإِنَّ لَكَ لَأَجۡرًا غَيۡرَ مَمۡنُونࣲ وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمࣲ فَسَتُبۡصِرُ وَيُبۡصِرُونَ بِأَييِّكُمُ ٱلۡمَفۡتُونُ﴾ [القلم: ۱-۶] \"گواہ ہے قلم اور جو اس سے لکھتے ہیں۔تم اپنے رب کی مہربانی سے آسیب زدہ نہیں ہو۔ یقینا تمھارے لیے ایسا بدلہ ہے جو کبھی ختم نہیں ہوگا اور بلاشبہ تم اعلیٰ کردار کے مالک ہو اور تم اور یہ کفار جلد ہی دیکھ لیں گے کہ تم میں سے کون وہم میں پڑ ا ہوا ہے\"۔\n۴-آپ صلی اللہ علیہ وسلم کے ہاتھ پر بیعت کرنا اللہ سے بیعت کرنا ہے:﴿إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ أَيۡدِيهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَٰهَدَ عَلَيۡهُ ٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمࣰ ا﴾ [الفتح: ۱۰] \"جو لوگ تم سے بیعت کرتے ہیں وہ االلہ سےبیعت کرتے ہیں، اللہ کا ہاتھ ان کے ہاتھوں پر ہے۔اب جس نے(اس بیعت)کو توڑ دیا تو وہ توڑکر اپنا ہی برا کرے گا اورجس نے اسے پورا کیا جس کا عہد اللہ سے کیا ہے اسے وہ بہت بڑا بدلہ دے گا\"۔\nعرب کے لوگ جب کسی بات کا عہد وپیمان کرتے تھے تو ایک دوسرے کا ہاتھ پکڑ کرحلف لیتے تھے، جس کو بیعت کہتے ہیں۔ پھر اس کو توڑنا بہت برا سمجھتے تھے۔اس آیت میں اسی کی جانب اشارہ کیا گیاہے۔ جو لوگ محمد صلی اللہ علیہ وسلم کے ہاتھ پر بیعت کرتے ہیں وہ حقیقت میں اللہ سے بیعت کرتے ہیں۔اس لیے اس کو توڑنے سے بچنا چاہیے۔اس میں جہاں بیعت کی اہمیت بتائی گئی ہے وہیں نبی اکرم صلی اللہ علیہ وسلم کے منصب کی جانب اشارہ کیا گیا ہے۔\n۵-آپ صلی اللہ علیہ وسلم وحی کے مطابق مذہب کی تبلیغ کرتے تھے:\nارشادباری تعالیٰ ہے :﴿وَٱلنَّجۡمِ إِذَا هَوَىٰ مَا ضَلَّ صَاحِبُكُمۡ وَمَا غَوَىٰ وَمَا يَنطِقُ عَنِ ٱلۡهَوَىٰٓ إِنۡ هُوَ إِلَّا وَحۡيࣱ يُوحَىٰ﴾ [النجم: ۱-۴] \"قسم ہے تارے کی جب وہ نیچے آیا۔تمھارا ساتھی نہ تو بھٹکا ہے اورنہ راہ سے ہٹا ہے اورایسا نہیں کہ جو چاہتاہے کہہ دیتا ہے۔وہ تو بس وحی ہوتی ہے جو اس پر کی جاتی ہے\"۔\nاورفرمایا:﴿قُلۡ مَا كُنتُ بِدۡعࣰ ا مِّنَ ٱلرُّسُلِ وَمَآ أَدۡرِي مَا يُفۡعَلُ بِي وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّ وَمَآ أَنَا۠ إِلَّا نَذِيرࣱ مُّبِينࣱ‏﴾ [الأحقاف: ۹] \"میں تو صرف اس کی پیروی کرتا ہوں جو میری جانب وحی کی جاتی ہے اورمیں کھلا کھلا ڈرانے والا ہوں\"۔\nمزیدارشادہے:﴿قُلۡ أَيُّ شَيۡءٍ أَكۡبَرُ شَهَٰدَةࣰۖ قُلِ ٱللَّهُۖ شَهِيدُۢ بَيۡنِي وَبَيۡنَكُمۡۚ وَأُوحِيَ إِلَيَّ هَٰذَا ٱلۡقُرۡءَانُ لِأُنذِرَكُم بِهِۦ وَمَنۢ بَلَغَۚ أَئِنَّكُمۡ لَتَشۡهَدُونَ أَنَّ مَعَ ٱللَّهِ ءَالِهَةً أُخۡرَىٰۚ قُل لَّآ أَشۡهَدُۚ قُلۡ إِنَّمَا هُوَ إِلَٰهࣱ وَٰحِدࣱ وَإِنَّنِي بَرِيٓءࣱ مِّمَّا تُشۡرِكُونَ﴾ [الأنعام: ۱۹] \"آپ کہیے کہ سب سے بڑی چیز گواہی دینے کے لئے کون ہے، آپ کہیے کہ میرے اور تمھارے درمیان اللہ گواہ ہے اور میرے پاس یہ قرآن بطور وحی کے بھیجا گیا ہے تاکہ میں اس قرآن کے ذریعہ سے تم کو اور جس جس کو یہ قرآن پہنچے ان سب کو ڈراؤں کیا تم سچ مچ یہی گواہی دو گے کہ اللہ تعالیٰ کے ساتھ کچھ اور معبود بھی ہیں،آپ کہہ دیجئے کہ میں تو گواہی نہیں دیتا۔ آپ فرما دیجئے کہ بس وہ تو ایک ہی معبود ہے اور بیشک میں تمھارے شرک سے بیزار ہوں \"۔\nنیزفرمایا:﴿قُلۡ إِنَّمَآ أَنَا۠ بَشَرࣱ مِّثۡلُكُمۡ يُوحَىٰٓ إِلَيَّ أَنَّمَآ إِلَٰهُكُمۡ إِلَٰهࣱ وَٰحِدࣱۖ فَمَن كَانَ يَرۡجُواْ لِقَآءَ رَبِّهِۦ فَلۡيَعۡمَلۡ عَمَلࣰ ا صَٰلِحࣰ ا وَلَا يُشۡرِكۡ بِعِبَادَةِ رَبِّهِۦٓ أَحَدَۢا﴾ [الکهف: ۱۱۰] \"آپ کہ دیجئے کہ میں تو تم جیسا ہی ایک انسان ہوں (ہاں) میری جانب وحی کی جاتی ہے کہ سب کا معبود صرف ایک ہی معبود ہے، تو جسے بھی اپنے رب سے ملنے کی آرزو ہو اسے چاہیے کہ نیک اعمال کرے اور اپنے رب کی عبادت میں کسی کو شریک نہ کرے\"۔\n۶-آپ صلی اللہ علیہ وسلم کو اللہ تعالیٰ نے سارےانس وجن اورساری دنیا کےلیے نبی بنا کر بھیجا: ﴿وَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةࣰ لِّلنَّاسِ بَشِيرࣰ ا وَنَذِيرࣰ ا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ﴾ [سبأ: ۲۸] \"اور(اے محمد) ہم نے تو تمھیں ساری دنیا کےلیے خوش خبری دینے والا اور متنبہ کرنے والا بنا کر بھیجا ہے۔لیکن اکثر لوگ نہیں جانتے\"۔\nنبی اکرم صلی اللہ علیہ وسلم نےخود وضاحت فرمائی ہےکہ پہلے انبیااپنی اپنی قوموں کی رہنمائی کے لیے بھیجے جاتے تھے اور میری نبوت ورسالت ساری اقوام کے لیے ہے۔جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: «کَانَ النبی يُبْعَثُ إِلَی قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَی النَّاسِ عَامَّةً». (صحیح البخاری: ۳۳۵، وصحیح مسلم: ۵۲۱/۳) \"(مجھ سے پہلے)نبی صرف اپنی قوم کےلیے بھیجے جاتے تھے لیکن مجھے سارے انسانوں کےلیے بھیجا گیا ہے\"۔\nابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «أُرْسِلْتُ إِلَی الْخَلْقِ کَافَّةً وَخُتِمَ بِيَ النبيونَ». (صحیح مسلم: ۵۲۳) \"میں ساری دنیا کے انسانوں کےلیے بھیجا گیا ہوں اور میرے ذریعے نبوت ختم کردی گئی\"۔\nاسی لیے مذہب اسلام اپنانے کےبعدمسلمانوں کے درمیان ایک دوسرے سے کوئی امتیاز نہیں ہوتا۔رنگ، نسل،قبیلہ، زبان اورملک کے الگ ہونے کا اسلامی معاشرہ پر کوئی اثر نہیں پڑ تا۔ایک مسلمان کسی بھی مسلمان لڑکی سےاسلامی قانون کی روشنی میں شادی کرسکتا ہے۔ مسجد میں سب ایک صف میں کھڑے ہوکر نماز پڑھتےہیں۔ہر شخص قرآن وحدیث اوراسلامی فقہ کا عالم بن سکتا ہے۔ خلاصہ یہ کہ مسلمانوں کے مابین تقویٰ اوراسلام کی پابندی کی بنیادکےعلاوہ ایک دوسرے میں کوئی تفریق و امتیازکی کوئی دوسری بنیادنہیں رہ جاتی۔مسلم معاشرے میں اگرکہیں رنگ ونسل اورزبان اور ملک کی بنیادپرکوئی فرق و امتیاز پایا جاتاہے تو وہ اسلامی تعلیمات کے خلاف اورغیرمسلم اقوام سے متاثرہونے کی وجہ سےہے۔\n۷-نبی اکرم صلی اللہ علیہ وسلم کےمعجزے: یوں تو نبی اکرم صلی اللہ علیہ وسلم کے ہاتھوں بہت سارے معجزے ظاہر ہوے جن کی تفصیل حدیثوں میں آئی ہےجیسے:\nچاند کے دو ٹکڑے ہوجانا۔ (صحیح البخاری: ۴۸۶۴اور صحیح مسلم: ۲۸۰۰)اس کاذکرقرآن کریم میں بھی ہے۔\nنبی اکرم صلی اللہ علیہ وسلم کی انگلیوں سے پانی کے چشمے بہنا۔ (صحیح البخاری: ۳۵۷۹)\nغزوۂ خندق میں دو تین آدمیوں کا کھانا ایک ہزار آدمیوں کےلیے کافی ہوجانا۔ (صحیح البخاری :ا۰ا۴)\nسائب بن یزید جو بچپن سے ہی کسی مرض میں مبتلا تھے، ان کی خالہ انھیں لےکر نبی اکرم صلی اللہ علیہ وسلم کے پاس آئیں۔ آپ نے اللہ سے دعا کی جس سے سائب بن یزید ہمیشہ کےلیے صحت مند ہوگئےاور پھر کبھی بیمار نہیں پڑ ے یہاں تک کہ۹۴سال کی عمر تک زندہ رہے۔ (صحیح البخاری:۹۰ا، صحیح مسلم: ۲۳۴۵)۔\nاس طرح کے بہت سارےمعجزوں کا ذکرحدیث کی کتابوں میں آیا ہے۔لیکن یہاں ایک ایسے معجزے کا ذکر کیا جارہاہے جو قیامت کے دن تک رہنے والا ہے۔وہ ہے قرآن مجیدکامعجزہ۔کیوں کہ اس سےپہلےبتایاجاچکاہےکہ جب غار حرا میں جبرئیل علیہ السلام قرآن کی وحی لےکر آئے اور نبی اکرم سےکہا: پڑ ھ تو آپ نے جواب دیا: میں پڑھنا نہیں جانتا۔ اس کی تصدیق قرآن مجیدبھی کرتا ہے کہ آپ کو پڑھنا لکھنا نہیں آتا تھا: ﴿قُلۡ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُمۡ جَمِيعًا ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ لَآ إِلَٰهَ إِلَّا هُوَ يُحۡيِۦ وَيُمِيتُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِيِّ ٱلۡأُمِّيِّ﴾ [الأعراف: ۱۵۸] \"کہو: اے لوگو! میں تم سب کی جانب اس اللہ کا رسول بنا کر بھیجا گیا ہوں، جو آسمانوں اور زمین کا مالک ہے۔اس کے سوا کوئی پر ستش کے لائق نہیں۔وہی زندگی دیتا ہے اور وہی موت دیتا ہے۔اس لیے اللہ اور اس کے رسو ل پر جو اُمّی ہیں ایمان لاؤ\"۔\nاُمّی کےایک معنیٰ ناخواندہ کے بھی ہیں۔ جس کو پڑھنا لکھنا نہ آتا ہو۔نبی اکرم صلی اللہ علیہ وسلم جس شہر اور معاشرہ میں پیدا ہوےتھے وہ اُمّی لوگ تھے۔اس لیے آپ بھی اُمّی رہ گئے۔پھر ایسے شخص پر قرآن جیسی عظیم کتاب کا اترنا اتنا بڑا معجزہ ہےجس کی دنیا میں کوئی مثال نہیں ہے۔اس لیے قرآن نے خود بار بار چیلنج کیا ہے کہ اگر تم کواس کے اللہ کی جانب سے ہونے میں شبہ ہے تو اس جیسی کوئی دوسری کتاب لاکر دکھاؤ: ﴿قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضࣲ ظَهِيرࣰ ا﴾ [الإسراء: ۸۸] \"کہہ دوکہ اگر انسان اور جن اس بات کےلیے جمع ہوجائیں کہ اس قرآن جیسی کوئی کتاب لائیں تو وہ اس جیسی کتاب نہیں لاسکیں گے خواہ وہ آپس میں ایک دوسرے کے معاون و مدد گار کیوں نہ بن جائیں\"۔\nکفار و مشرکین ایسی کتاب لانے سےعاجزو لاچار رہے۔جب کہ وہ اپنے کوعربی زبان کابڑا ماہر سمجھتے تھے۔\nپھر قرآن نے دوبارہ چیلنج کیا کہ اگر مکمل قرآن جیسی کوئی کتاب نہیں لاسکتے تواس جیسی دس سورتیں ہی لاکر دکھا دو:﴿أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِعَشۡرِ سُوَرࣲ مِّثۡلِهِۦ مُفۡتَرَيَٰتࣲ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ﴾ [ہود: ۱۳] \"کیا یہ کہتے ہیں کہ اس نے اسے خود ہی گھڑ لیا ہے۔کہہ دو: اچھا تو تم اس جیسی گھڑی ہوئی دس سورتیں لے آو ٔ اور اللہ کے سوا جس کسی کو بلا سکتے ہو بلا لواگر تم سچے ہو\"۔\nجب وہ دس سورتیں لانے میں بھی عاجزولاچار رہے تو اللہ تعالیٰ نےانھیں تیسری بار چیلنج کیا:\n۱- ﴿أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ فَأۡتُواْ بِسُورَةࣲ مِّثۡلِهِۦ وَٱدۡعُواْ مَنِ ٱسۡتَطَعۡتُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ﴾ [یونس: ۳۸] \"کیا یہ لوگ کہتے ہیں کہ اس نے اسے خود سے گھڑلیا ہے؟کہو اگر تم سچے ہو ایک ہی سورة اس جیسی بنا کر لے آؤ اور اللہ کے علاوہ جس کو بلا سکتے ہو بلا لو\"۔\n۲- ﴿وَإِن كُنتُمۡ فِي رَيۡبࣲ مِّمَّا نَزَّلۡنَا عَلَىٰ عَبۡدِنَا فَأۡتُواْ بِسُورَةࣲ مِّن مِّثۡلِهِۦ وَٱدۡعُواْ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمۡ صَٰدِقِينَ﴾ [البقرة: ۲۳] \"اگر تمھیں اس بات میں شبہ ہے کہ یہ کتاب جو ہم نے آپ نے بندے پر نازل کی ہے ہماری ہے یا نہیں، تو اس جیسی ایک ہی سورہ بنا لاؤ۔ایک اللہ کو چھوڑ کر باقی جس کو چاہو بلالو، اگر تم سچے ہو تو یہ کام کر کے دکھاؤ\"۔\nمگر جب وہ ایساکرنے میں بھی لاچار رہے تو قرآن نے ایک اور چیلنج دیا کہ اگر یہ قرآن گڑھا ہوا ہے تو اس جیسا کلام لاکر دکھادو۔\n۳- ﴿أَمۡ يَقُولُونَ تَقَوَّلَهُۥۚ بَل لَّا يُؤۡمِنُونَ فَلۡيَأۡتُواْ بِحَدِيثࣲ مِّثۡلِهِۦٓ إِن كَانُواْ صَٰدِقِينَ﴾ [الطور: ۳۳-۳۴] \"کیا یہ کہتے ہیں کہ اس نے یہ بات اپنی جانب سے بنا لی ہے؟نہیں، بلکہ یہ ایمان نہیں لانا چاہتے۔ اچھا،اگر یہ سچے ہیں تو اس جیسا کلام لاکر دکھائیں\"۔\nنبی اکرم صلی اللہ علیہ وسلم کاسب سے بڑا معجزہ یہی قرآن کریم ہے، جو آپ پر نازل ہو ا،جب کہ آپ اُمّی تھے۔ لیکن آپ کا لایا ہوا قرآن کروڑوں انسانوں کو متاثر کر گیا اور کرتا ہی رہے گا اور قیامت کے دن تک کوئی بھی اس جیسی کتاب لانے کا متحمل نہیں ہوسکتا۔\n۸- بادشاہوں کے نام دعوتی خطوط:\nنبی اکرم صلی اللہ علیہ وسلم نےاسلام کی دعوت کوپھیلانےاورعام کرنے کے لئے اپنے وقت کےامراء وسلاطین سے خط وکتابت کی اور ان کو اسلام قبول کرنے کی دعوت دی۔ ذیل میںنبی اکرم صلی اللہ علیہ وسلم کا ایک دعوتی خط (مکتوب)، جو آپ نے مصر کے بادشاہ کے نام لکھا تھا اور اس کاجواب جو اس نے لکھا تھادیا جارہاہے۔\nنبی اکرم صلی اللہ علیہ وسلم نے سن ۹ھ میں بہت سارے بادشاہوں کے نام خطوط لکھے۔ان ہی بادشاہوں میں مصر کا بادشاہ مقوقس بھی تھا،جس کو آپ نے یہ مکتوب لکھا:\nمحمد اللہ کے بندے اور رسول کی جانب سے مصر کے بادشاہ مقوقس کے نام، اس پر سلامتی ہو،جو صحیح راستا اختیار کرے۔\nاس کے بعد میں تمھیں اسلام قبول کرنے کی دعوت دیتاہوں۔اگر اسلام قبول کرلوگے تو تم محفوظ رہوگے اور اللہ تعالیٰ تمھارے ثواب کو دوگنا کردے گا اور اگر تم نے انکار کیا تو تم پر قبطیوں (مصریوں ) کا گناہ ہوگا۔پھر قرآن کریم کی مندرجہ ذیل آیت تحریر فرمائی: ﴿قُلۡ يَٰٓأَهۡلَ ٱلۡكِتَٰبِ تَعَالَوۡاْ إِلَىٰ كَلِمَةࣲ سَوَآءِۭ بَيۡنَنَا وَبَيۡنَكُمۡ أَلَّا نَعۡبُدَ إِلَّا ٱللَّهَ وَلَا نُشۡرِكَ بِهِۦ شَيۡـࣰٔ ا وَلَا يَتَّخِذَ بَعۡضُنَا بَعۡضًا أَرۡبَابࣰ ا مِّن دُونِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَقُولُواْ ٱشۡهَدُواْ بِأَنَّا مُسۡلِمُونَ﴾ [آل عمران: ۶۴] \"اے اہل کتاب!آؤ ایک ایسی بات پرسمجھوتا کرلیں جسے ہمارے او ر تمھارے درمیان یکساں طور سے منظوری حاصل ہے۔یہ کہ ہم اللہ کے سوا کسی غیر کی بندگی نہ کریں اور نہ ان کے ساتھ کسی کو شریک ٹھہرائیں اور نہ ہم آپس میں ایک دوسرے کو اللہ سے ہٹ کر رب بنائیں۔لیکن اگر وہ ان باتوں سے منہ موڑیں تو کہہ دو، گواہ رہو، ہم تو مسلمان(یعنی اللہ کے حکم ماننے والے) ہیں\"۔\nمصر کے بادشاہ مقوقس کا جواب:\nمحمد بن عبد اللہ کے نام مقوقس کی جانب سے سلام۔میں نے آپ کا مکتوب پڑھا۔ اس میں آپ نے جو کچھ ذکر کیا ہے اور آپ جو پیغام دیتے ہیں، میں سب سمجھ گیا۔مجھے اس بات کا علم تھا کہ ایک نبی آنے والا ہے،لیکن میرا خیال تھا کہ وہ شام میں آئے گا۔میں نے آپ کے سفیر کااستقبال کیا۔ میں آپ کو دو خوبصورت لڑکیاں تحفۃً بھیج رہاہوں، جن کی مصر میں بڑی اہمیت اور نام ہے اورانھی کے ساتھ کچھ کپڑے اور خچربھی بھیج رہاہوں، تاکہ آپ اس پرسواری کرسکیں۔ والسلام\nکچھ مغربی دانش وروں کا خیال ہے کہ مصر کے بادشاہ مقوقس کا جواب ان الفاظ میں تھا:\nاللہ کے نام سے،مقوقس کی جانب سے محمد کے نام۔اس کے بعد: مجھے آپ کا مکتوب ملا۔اس کو پڑھا اور جو کچھ اس میں لکھاتھا، میں سمجھ گیا۔آپ کہتے ہیں کہ اللہ نے آپ کو رسول بنا کر بھیجا ہے اور آپ پر قرآن نازل ہوا ہے۔اے محمد! ہمیں اپنے علم سے یہ معلوم ہوگیا ہے کہ آپ اللہ کی جانب بلانے والے ہیں۔ آپ سچ بات کرنے والے ہیں۔اگر میں ایک عظیم ملک کابادشاہ نہ ہوتا تو میں پہلا شخص ہوتا جو آپ کے پاس پہنچتا۔ مجھے اس بات کا بھی علم ہے کہ آپ نبیوں کے خاتم ہیں (آپ کے بعد کوئی دوسرانبی نہیں آئے گا)۔ آپ نبیوں کے سردار ہیں۔آپ پر اللہ کی سلامتی اور رحمت قیامت کے دن تک جاری رہے۔(مزید معلومات کےلیے ملاحظہ فرمائیں:الوثائق السیاسیہ،تالیف: ڈاکٹر محمد حمید اللہ:صفحہ ۰۶اـ۰۸ا)\nاوپر جن دو عورتوں کا ذکر ہوا ہے، ان میں سے ماریہ قبطیہ نامی عورت سےنبی اکرم صلی اللہ علیہ وسلم نے نکاح کیااورماریہ سےآپ کے صاحبزادےابراہیم کی پیدایش ہوئی، لیکن بہت جلد ابراہیم کا انتقال ہوگیا۔ اسی موقع پر نبی اکرم صلی اللہ علیہ وسلم نے فرمایاتھا: \"آنکھیں رو رہی ہیں، دل غم و اندوہ سے بھر اٹھا ہے،لیکن ایسے وقت میں ہم کوئی ایسی بات نہیں کہیں گے جو ہمارے رب کو ناپسند ہو\"۔\nشاہ مصرمقوقس تو مسلمان نہیں ہوا۔ لیکن عمر بن خطاب رضی اللہ عنہ کے دورحکومت میں سن ا۲ھ میں مسلمانوں نے عمرو بن العاص رضی اللہ عنہ کی قیادت میں مصر پر فتح پائی اور کچھ ہی برسوں بعد مصر میں اسلام پهیل گیا۔\nاسلامی تاریخ میں مصر کا نہایت ہی اہم مقام ہے۔وہاں بڑے بڑے علما پیدا ہوے۔وہ قرآن اور حدیث کی شرح وتفسیر کرنے والوں کا مرکز بن گیا۔دنیا کی سب سے پہلی اسلامی یونیورسٹی مصر میں ہی تقریباً ایک ہزار سال قبل قائم کی گئی،جو جامعہ ازہر کے نام سے مشہور ہے۔ آج بھی اس یونیورسٹی کے ہزاروں فارغ التحصیل اسلام کی تبلیغ اورعربی زبان کی تعلیم میں لگے ہوے ہیں۔\nمصر کے بادشاہ مقوقس کے نام نبی اکرم صلی اللہ علیہ وسلم کے مکتوب کی نقل استنبول کےایک عجائب گھر میں موجود ہے۔\n۹- آپ صلی اللہ علیہ وسلم تمام انبیاء ورسل سے أفضل ہیں۔\nجس کے کچھ شواہد یہاں پیش کیے جارہے ہیں۔\n۱) آپ کو اللہ نے رحمۃ للعالمین بناکر بھیجا، آپ کی رحمت انسانوں اور جنوں کے علاوہ جانوروں اور پرندوں کو بھی شامل ہے۔\n۲) آپ کے دل کو دو بار زمزم سے دھویا گیا اور اس کو حکمت سے معمور کیا گیا۔\n۳) آپ کو انسانوں کے علاوہ جنوں کیلئے بھی نبی بنا کر بھیجا گیا، اسلئے جنوں میں بھی صحابی، تابعی فقہاءوغیرہ پائے جاتے ہیں۔\n۴) آپ کے مقام کو خود اللہ رب العزت نے بلند کیا:﴿وَرَفَعۡنَا لَكَ ذِكۡرَكَ﴾ [الشرح: ۴]\nاسی لئے آج زمین وآسمان میں جس نبی کا ذکر سب سے زیادہ کیا جاتا ہے وہ محمد رسول اللہ صلی اللہ علیہ وسلم ہے، ہر مسجد سے دن میں پانچ بار آپ کے نام کو بلند آواز میں پکارا جاتا ہے اور آپ پر درود وسلام بھیجا جاتا ہے۔\n۵) آپ کو اللہ نے بیت اللہ سے مسجد اقصٰی اور پھر معراج کی سیر کرائی اور پھر آپ اس مقام تک پہنچ گئے جہاں جبریل علیہ السلام بھی نہیں جاسکتے تھے، جس کو\" سدرۃ المنتہی\" کہتے ہیں۔\n۶) بیت المقدس میں آپ نے تمام انبیاء کی امامت فرمائی، جن میں آدم علیہ السلام کے علاوہ دیگر انبیاء بھی تھے۔\n۷) آپ کو خاتم النبیین بناکر بھیجا گیا، اب آپ کےبعد کوئی نبی نہیں آسکتا، اگر اب کوئی نبوت کا دعویٰ کرتا ہے تو وہ کذاب ودجال ہے۔\n۸) جب عیسٰی علیہ السلام کا نزول ہوگا تو وہ آپ کے امتی کی اقتداء میں نماز ادا کریں گے۔\n۹) اگر موسیٰ علیہ السلام زندہ ہوتے تو وہ بھی آپ ہی کی اتباع کرتے۔\n۱۰) آپ قیامت کے دن سب سے پہلے شخص ہونگے جنہیں ان کی قبر سے اٹھایا جائے گا، یعنی تمام انبیاء ورسل سے پہلے آپ اپنی قبر سے باہر آئیں گے۔\n۱۱) آپ کو قیامت کے دن حوض کوثر عطاء کیا جائے گا:﴿إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ﴾ [الکوثر: ۱]\n۱۲) آپ کو مقام محمود عطا ہوگا جہاں سے آپ شفاعت فرمائیں گے:\n﴿عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامࣰ ا مَّحۡمُودࣰ ا﴾ [الإسراء: ۷۹] اس دن تمام انبیاء بشمول آدم علیہ السلام کہیں گے کہ جاؤ محمد کے پاس آج تو انہیں کی شفاعت قبول کی جائے گی۔\n۱۳) آپ کو اللہ نے ایسا رعب عطا کیا کہ دشمن تین دن کی مسافت سے ہی بھاگ کھڑا ہوتا تھا.\n۱۴) آپ کیلئے اور پھر آپ کی امت کیلئے اللہ نے پوری زمین کو مسجد بنادیا، تاکہ جہاں بھی نماز کا وقت ہوجائے وہیں نماز پڑھی جائے۔\n۱۵) آپ کو ریاض الجنۃ عطا کیا گیا جس کا محل وقوع آپ کے گھر سے لیکر آپ کے منبر کے درمیان ہے۔\nیہ وہ کچھ وجوہات ہیں جن کا ذکر میں نے یہاں کردیا ہے، انکے علاوہ بھی اور بہت ساری خصوصیات ہیں جن کی بنا پر اللہ نے آپ کو تمام انبیاء ورسل پر فضیلت عطا فرمائی۔","",{}]]);
